{
  "schema_version": "1.0.0",
  "intent_aliases": {
    "ui": ["ui", "ux", "界面", "交互", "frontend", "front-end"],
    "navigation": ["navigation", "导航", "route", "routing", "路由"],
    "layout": ["layout", "布局", "responsive", "响应式"],
    "document-preview": ["document", "preview", "文档", "预览", "pdf", "pptx", "原件"],
    "async-job": ["async", "job", "queue", "worker", "异步", "队列", "后台任务", "等待"],
    "knowledge-processing": ["knowledge", "知识", "提炼", "processing", "资料加工"],
    "backend": ["backend", "后端", "api", "接口"],
    "governance": ["governance", "治理", "contract", "契约"]
  },
  "core": {
    "id": "governed-task-contract",
    "roles": ["project-manager"],
    "clauses": ["CONST-08", "CONST-10", "TECH-ARCH-04", "TECH-TEST-01"],
    "must_read": ["AGENTS.md", "docs/AGENTS.md", "docs/CONSTITUTION.md", "docs/TECHNOLOGY.md"],
    "skills": ["governed-task-routing"],
    "required_outputs": [
      {"id": "task-contract", "fulfillment": "preflight", "owner_roles": ["project-manager"]}
    ],
    "checks": [
      {"id": "route-contract-schema", "type": "machine", "description": "Validate the selected task contract, actual loaded files, and delivery record schema."}
    ]
  },
  "routes": [
    {
      "id": "knowledge-processing-experience",
      "match": {
        "mode": "any",
        "intent_any": ["knowledge-processing"],
        "path_any": ["frontend/src/admin/knowledge/**", "backend/src/knowledge/**"]
      },
      "roles": ["ui-ux", "frontend", "backend", "test-manager"],
      "clauses": ["CONST-04", "CONST-10", "TECH-FE-03", "TECH-BE-04", "TECH-TEST-02", "TECH-TEST-03"],
      "must_read": ["docs/DESIGN.md", "docs/ia-information-architecture.md"],
      "skills": ["ux-task-and-state-design", "responsive-page-layout", "antd-component-engineering", "document-fidelity-viewing", "async-job-observability", "ui-evidence-verification"],
      "required_outputs": [
        {"id": "state-and-action-map", "fulfillment": "delivery", "owner_roles": ["ui-ux", "backend"]},
        {"id": "layout-contract", "fulfillment": "delivery", "owner_roles": ["ui-ux", "frontend"]},
        {"id": "component-selection", "fulfillment": "delivery", "owner_roles": ["architect", "frontend", "ui-ux"]},
        {"id": "preview-contract", "fulfillment": "delivery", "owner_roles": ["ui-ux", "frontend", "backend"]},
        {"id": "async-contract", "fulfillment": "delivery", "owner_roles": ["backend", "frontend", "ui-ux"]},
        {"id": "browser-and-source-evidence", "fulfillment": "delivery", "owner_roles": ["test-manager", "ui-ux"]}
      ],
      "checks": [
        {"id": "knowledge-state-contract-test", "type": "machine", "description": "Run state, API, or component tests that cover the selected knowledge-processing facts."},
        {"id": "knowledge-browser-and-source-review", "type": "human-browser", "description": "A named reviewer compares representative browser states and source pages; automation only records the supplied evidence."}
      ]
    },
    {
      "id": "frontend-experience",
      "match": {
        "mode": "any",
        "intent_any": ["ui", "layout"],
        "path_any": ["frontend/src/**", "frontend/e2e/**"]
      },
      "roles": ["ui-ux", "frontend", "test-manager"],
      "clauses": ["CONST-04", "CONST-10", "TECH-FE-01", "TECH-FE-03", "TECH-TEST-02"],
      "must_read": ["docs/DESIGN.md", "docs/ia-information-architecture.md"],
      "skills": ["ux-task-and-state-design", "responsive-page-layout", "antd-component-engineering", "ui-evidence-verification"],
      "required_outputs": [
        {"id": "state-and-action-map", "fulfillment": "delivery", "owner_roles": ["ui-ux", "frontend"]},
        {"id": "layout-contract", "fulfillment": "delivery", "owner_roles": ["ui-ux", "frontend"]},
        {"id": "component-selection", "fulfillment": "delivery", "owner_roles": ["architect", "frontend", "ui-ux"]},
        {"id": "browser-and-source-evidence", "fulfillment": "delivery", "owner_roles": ["test-manager", "ui-ux"]}
      ],
      "checks": [
        {"id": "frontend-experience-test", "type": "machine", "description": "Run the affected component, integration, or E2E test with a saved test report."},
        {"id": "frontend-browser-review", "type": "human-browser", "description": "A named reviewer records a browser review for the applicable viewport and interaction states."}
      ]
    },
    {
      "id": "navigation-change",
      "match": {
        "mode": "any",
        "intent_any": ["navigation"],
        "path_any": ["frontend/src/App.tsx", "frontend/src/**/router/**", "frontend/src/**/routes/**"]
      },
      "roles": ["ui-ux", "platform-product-manager", "frontend", "test-manager"],
      "clauses": ["CONST-04", "TECH-FE-03", "TECH-TEST-02"],
      "must_read": ["docs/ia-information-architecture.md", "docs/DESIGN.md"],
      "skills": ["information-architecture-navigation", "ui-evidence-verification"],
      "required_outputs": [
        {"id": "navigation-contract", "fulfillment": "delivery", "owner_roles": ["ui-ux", "platform-product-manager", "frontend"]},
        {"id": "browser-and-source-evidence", "fulfillment": "delivery", "owner_roles": ["test-manager", "ui-ux"]}
      ],
      "checks": [
        {"id": "navigation-route-test", "type": "machine", "description": "Run direct-open, refresh, and browser-back coverage for the affected address contract."},
        {"id": "navigation-browser-review", "type": "human-browser", "description": "A named reviewer checks page responsibility, deep links, and return context in a browser."}
      ]
    },
    {
      "id": "document-viewing",
      "match": {
        "mode": "any",
        "intent_any": ["document-preview"],
        "path_any": ["frontend/src/**/Document*.tsx", "frontend/src/**/Preview*.tsx", "backend/src/**/preview/**"]
      },
      "roles": ["ui-ux", "frontend", "backend", "test-manager"],
      "clauses": ["CONST-04", "CONST-10", "TECH-FE-02", "TECH-TEST-02"],
      "must_read": ["docs/DESIGN.md", "docs/TECHNOLOGY.md"],
      "skills": ["document-fidelity-viewing", "ui-evidence-verification"],
      "required_outputs": [
        {"id": "preview-contract", "fulfillment": "delivery", "owner_roles": ["ui-ux", "frontend", "backend"]},
        {"id": "browser-and-source-evidence", "fulfillment": "delivery", "owner_roles": ["test-manager", "ui-ux"]}
      ],
      "checks": [
        {"id": "document-preview-test", "type": "machine", "description": "Run affected preview, page-mapping, and error-state tests with a saved report."},
        {"id": "document-source-compare", "type": "human-browser", "description": "A named reviewer compares representative browser pages to the source document; automation does not judge fidelity."}
      ]
    },
    {
      "id": "async-job-change",
      "match": {
        "mode": "any",
        "intent_any": ["async-job"],
        "path_any": ["backend/src/**/*worker*", "backend/src/**/*job*", "backend/src/**/*queue*", "backend/src/**/*outbox*", "frontend/src/**/*Job*.tsx"]
      },
      "roles": ["backend", "frontend", "ui-ux", "test-manager"],
      "clauses": ["CONST-04", "TECH-BE-03", "TECH-BE-04", "TECH-FE-03", "TECH-TEST-02"],
      "must_read": ["docs/TECHNOLOGY.md", "docs/DESIGN.md"],
      "skills": ["async-job-observability", "ux-task-and-state-design", "ui-evidence-verification"],
      "required_outputs": [
        {"id": "state-and-action-map", "fulfillment": "delivery", "owner_roles": ["ui-ux", "backend", "frontend"]},
        {"id": "async-contract", "fulfillment": "delivery", "owner_roles": ["backend", "frontend", "ui-ux"]},
        {"id": "browser-and-source-evidence", "fulfillment": "delivery", "owner_roles": ["test-manager", "ui-ux"]}
      ],
      "checks": [
        {"id": "async-recovery-test", "type": "machine", "description": "Run queued, running, recovery, failure, cancellation, and uncertain-result coverage where applicable."},
        {"id": "async-browser-review", "type": "human-browser", "description": "A named reviewer checks that waiting, progress, and recovery claims match supplied execution facts."}
      ]
    },
    {
      "id": "backend-unrelated-change",
      "match": {
        "mode": "path",
        "path_any": ["backend/src/**", "backend/scripts/**"]
      },
      "roles": ["backend", "test-manager"],
      "clauses": ["CONST-04", "TECH-BE-01", "TECH-TEST-01"],
      "must_read": ["docs/TECHNOLOGY.md"],
      "skills": [],
      "required_outputs": [],
      "checks": [
        {"id": "backend-affected-test", "type": "machine", "description": "Run the affected deterministic backend validation and retain its report."}
      ]
    }
  ]
}

/* Ontology surfaces: user's seven reference images are the visual authority.
   Values are scoped; existing pages keep their own tokens. */
.ontology-shell {
  --onto-blue: #0658ff;
  --onto-blue-hover: #064bdd;
  --onto-white: #ffffff;
  --onto-ink: #192b4c;
  --onto-title: #17263f;
  --onto-quiet: #687b9a;
  --onto-canvas: #f2f6fc;
  --onto-selected: #e9f0ff;
  --onto-chip: #f4f6fa;
  --onto-line: #e9eef6;
  --onto-th: #f3f6fb;
  --onto-control-border: #dfe6f2;
  --onto-selection-border: #a8c4ff;
  --onto-purple: #7938ee;
  --onto-purple-light: #a568ff;
  --onto-icon-green: #0eb487;
  --onto-icon-orange: #ff8a15;
  --onto-icon-pink: #cc3d98;
  --onto-icon-blue: #147de0;
  --onto-icon-red: #f15b2a;
  --onto-success: #147f3d;
  --onto-success-bg: #eaf9ee;
  --onto-warning: #a45b14;
  --onto-warning-bg: #fff2df;
  --onto-danger: #b82f3c;
  --onto-shadow: 0 2px 8px #284f9010;
  --onto-dialog-shadow: 0 12px 40px #233d7026;
  --onto-backdrop: #162d4c2e;
}
:root {
  /* MASTER Product tokens + OpenAI-quiet mood — --color-* then wired into workbench tokens */
  --color-obsidian: #000000; /* hairline source only; not filled CTA */
  --color-ink: #1a1a1a; /* compact shell body; not pure #000 */
  --color-graphite: #6b6b6b; /* 基础灰：--ds-text-dim 挂在它上面，别在这里回指 token（会成环） */
  --color-smoke: #8a8a8a;
  --color-paper: #ffffff;
  --color-ash: #f1f1f1;
  --color-hairline: #eeeeee;
  --color-whisper: #0000000a;
  --color-primary: #DB1860;
  --color-primary-hover: #B81451;
  --color-success-vivid: #10B981;
  --color-warning-vivid: #F59E0B;
  --color-warning-tint: #FEF3C7;
  --color-text-dim: #6B7280;
  --color-page-bg: #FFFFFF;
  --font-openai-sans: ui-sans-serif, system-ui, "PingFang SC", "Noto Sans SC", "WenQuanYi Micro Hei", "Droid Sans Fallback", sans-serif;

  --bg: var(--color-paper);
  --bg-elevated: var(--color-ash);
  --border: #eee;
  --border-strong: #f0f0f0;
  --control-border: var(--color-smoke);
  --control-border-hover: var(--color-graphite);
  --control-border-invalid: #c43c3c;
  --focus-ring: var(--color-obsidian);
  --text: var(--color-ink);
  --text-muted: var(--color-graphite);

  --primary: #DB1860;
  /* 实底上的字用画布色：浅色 = #FFFFFF（4.87:1 ✓），深色自动跟随 --bg = #17191d（4.77:1 ✓）。
     此前深色写死 #FFFFFF，实测白字压在深色主色 #E0508C 上只有 **3.69:1**，不达 13px 文字的 4.5:1。 */
  --primary-fg: var(--bg);
  --primary-hover: #B81451;
  /* 主行动色当文字 / 图标时必须用它（docs/DESIGN.md §颜色 + WCAG AA）：#DB1860 在白底只有 4.87:1、
     在 --ds-surface 上 4.58:1，都低于正文的 4.5 余量要求；本值 = color-mix(--primary 84%, #000)，
     实测 #B81451 白底 6.45:1 / --ds-surface 6.06:1。派生而非硬写色值 —— --primary 迁移时自动跟随。 */
  --primary-text: color-mix(in srgb, var(--primary) 84%, #000000);
  /* 辅助色（蓝）：选中态、图标砖、分段选中、可点强调、信息性标记。
     主行动仍只走 --primary（品牌粉）——见 docs/DESIGN.md §颜色。
     辅助色 #4184ff 对白 3.52:1，可用于图形，不用于文字，
     故文字/图标档单独派生：--accent-text = 72% accent + 28% 黑 = #2f5fb8，
     对白 6.09:1 / 压在 8% 淡蓝砖上 5.57:1 ✓。 */
  --accent: #4184ff;
  --accent-hover: #3974e0;
  /* 深蓝档：需要 4.5:1 的地方（文字、图标字形），也用于把小徽标做成实底；
     实底上的字用 --accent-fg。四件套与 --primary/--primary-hover/--primary-text/--primary-fg 一一对应。 */
  --accent-text: color-mix(in srgb, var(--accent) 72%, #000000);
  --accent-fg: var(--bg);

  /* 类别色（图标砖按类别分色）：第 4 职责，职责与约束见 docs/DESIGN.md §颜色。
     只用于「按类别分组的目录面」的图标砖淡底 / 描边与砖内字形；不承担交互（--accent）
     与状态（--warning / --danger / --success）。每类四件套：基色（图形档）、字形档、
     砖底、描边。色相刻意与 --accent（亮蓝）拉开：靛蓝 / 紫 / 青 / 中性石墨。
     实测（node 计算）：字形档对砖底 6.96–7.83:1（浅）/ 6.18–7.64:1（深）；基色对画布 ≥4.67:1。 */
  --cat-library: #4f5bd5;
  --cat-assistant: #8f4fd5;
  --cat-crawl: #0f7f96;
  --cat-builtin: var(--text-muted);
  --cat-library-text: color-mix(in srgb, var(--cat-library) 72%, #000000);
  --cat-assistant-text: color-mix(in srgb, var(--cat-assistant) 72%, #000000);
  --cat-crawl-text: color-mix(in srgb, var(--cat-crawl) 72%, #000000);
  --cat-builtin-text: color-mix(in srgb, var(--cat-builtin) 72%, #000000);
  --cat-library-tile: color-mix(in srgb, var(--cat-library) 8%, var(--bg));
  --cat-assistant-tile: color-mix(in srgb, var(--cat-assistant) 8%, var(--bg));
  --cat-crawl-tile: color-mix(in srgb, var(--cat-crawl) 8%, var(--bg));
  --cat-builtin-tile: color-mix(in srgb, var(--cat-builtin) 8%, var(--bg));
  --cat-library-line: color-mix(in srgb, var(--cat-library) 18%, var(--border));
  --cat-assistant-line: color-mix(in srgb, var(--cat-assistant) 18%, var(--border));
  --cat-crawl-line: color-mix(in srgb, var(--cat-crawl) 18%, var(--border));
  --cat-builtin-line: color-mix(in srgb, var(--cat-builtin) 18%, var(--border));

  --danger: #c43c3c;
  --success: #2f7d73;
  --warning: #ea5504;
  --warning-text: color-mix(in srgb, var(--warning) 72%, var(--text));
  --success-text: color-mix(in srgb, var(--success) 72%, var(--text));

  --radius-sm: var(--ds-radius-input);
  --radius-md: var(--ds-radius-section);
  --control-bg: #efeff2;
  --control-pill-height: 36px;
  /* 控件尺寸、行高与命中区下限（纯新增数值，不改动上方既有 token）。口径见
     docs/DESIGN.md 员工端实施细则 §控件尺寸。注意 §8 的迁移清单
     （--primary 数值、--radius-cards 等）不在此处，需单独一轮。 */
  --hit-min: 24px;
  --control-h-sm: 24px;
  /* DESIGN §28: business knowledge rows, not generic table density. */
  --knowledge-row-h: 36px;
  --knowledge-row-h-detail: 44px;
  --control-h: 28px;
  --control-h-lg: 32px;
  /* 筛选 chips 高度（docs/DESIGN.md §4.1 尺寸表）。触摸模态只扩大命中区
     （--touch-hit-min 44px），不同步放大视觉控件。 */
  --chip-h: 28px;
  /* 图标只有两档（docs/ui-ux-rules.md 规则 17）：控件内 14、标识砖内 18。
     技能目录页此前把这两档定义在页面级，工作台右栏等其它表面取不到值，
     故在此登记为全局 token；页面级重复定义同样合法。 */
  --icon-sm: 14px;
  --icon-md: 18px;
  --icon-btn: 24px;
  /* 跟进红人卡片的头像图标砖边宽（docs/DESIGN.md §控件尺寸）。 */
  --kol-avatar-size: 28px;
  /* 首页工作台控件收敛为紧凑规格；触摸模态由下方规则单独扩至 44px 命中区。 */
  --home-chip-w: 88px;
  --home-chip-h: 28px;
  --home-chip-gap: 4px;
  --home-mode-tab-gap: 2px;
  /* 优先级列要放得下「重要紧急」（12px×4 + padding 20 + 边框 2 = 70），
     动作列放单行两个按钮（最长「查看邮件任务」+「编辑」≈ 144）。 */
  --workspace-task-priority-col: 72px;
  --workspace-task-actions-col: 156px;
  --workspace-task-action-h: 20px;
  /* Search, tab, task-row and CTA tokens — canonical values in docs/DESIGN.md §4.3–4.4 / §9.3.1. */
  --workspace-search-max-w: 18rem;
  --workspace-search-pad-x: 10px;
  --workspace-tab-h: 36px;
  --workspace-tab-indicator-h: 2px;
  --workspace-tab-gap: 16px;
  --filter-tab-h: 28px;
  --workspace-list-row-h: 44px;
  --workspace-list-row-h-relaxed: 52px;
  --workspace-list-cell-pad-x: 8px;
  --workspace-list-divider: var(--border);
  /* Task center uses intrinsic content columns so surplus width belongs to the task title. */
  --task-list-content-col-width: 1%;
  --task-list-actions-gap: var(--space-2);
  --task-list-row-h: var(--workspace-list-row-h);
  --task-list-header-h: var(--table-header-h);
  --task-list-cell-pad-x: var(--workspace-list-cell-pad-x);
  /* 中栏「查看最新」与提问框发送箭头共享同一视觉尺寸。 */
  --workspace-arrow-button-size: 32px;
  /* Home Agent 工作台列宽：唯一数值来源见 docs/DESIGN.md §Home Agent 工作台几何。 */
  --workspace-result-rail-min: 360px;
  --workspace-result-rail-ideal: 54%;
  --workspace-result-rail-max: 820px;
  --workspace-result-rail-collapsed: 56px;
  --workspace-pane-gutter: var(--space-4);
  --workspace-agent-content-w: 400px;
  --workspace-tabs-composer-gap: var(--space-2);
  --badge-h: 20px;
  --lh-control: 20px;
  --lh-control-sm: 16px;
  /* 按用途命名的圆角、表面三档。组件规范来源 = shadcn/ui：--radius-card 取
     `--radius: 0.5rem`（rounded-lg），--radius-control 取 `calc(0.5rem - 2px)`（rounded-md）。
     数值口径见 docs/DESIGN.md 员工端实施细则 §控件尺寸（唯一数值来源）。 */
  --radius-control: 6px;
  /* L3 文字按钮（docs/DESIGN.md §4 视觉强调四级） */
  --btn-text-h: 28px;
  --btn-text-pad-x: 8px;
  --btn-text-hover-bg: color-mix(in srgb, var(--accent) 8%, transparent);
  --radius-card: 8px;
  /* 紧凑等级/风险 chip 方角（docs/DESIGN.md §4.1，行内标记专用） */
  --radius-chip-square: 4px;
  /* 进度/比例条高度（docs/DESIGN.md §4.1 --cost-meter-h；比例只由形状表达，状态词与数值同时文字给出） */
  --cost-meter-h: 6px;
  /* 次要文字 12px（docs/DESIGN.md §5.1） */
  --ds-font-xs: 12px;
  /* 无限加载触发阈值（docs/DESIGN.md §9.4.2 v3.1，不复用 --feed-follow-threshold） */
  --infinite-load-threshold: 48px;
  --surface-hover: color-mix(in srgb, var(--text) 10%, var(--bg));

  /* ── 数据面（data-grid）与弹窗：docs/DESIGN.md §9.1 / §9.2 / §7.1 ────────
     这批 token 此前只在 DESIGN 的登记表里，styles.css 没有定义，页面写
     `var(--table-row-h)` 取到空值后行高落回内容高度。数值口径以 §9.1 表为准。 */
  --table-row-h-relaxed: 52px;   /* 含双行内容/对象卡的行 */
  --table-row-h: 44px;           /* 中台数据面默认档 */
  --table-row-h-compact: 32px;   /* 行数 >50 / 用户显式切换 */
  --kb-admin-row-h: 36px;        /* 管理端知识列表行（2026-10-07 收紧：44px → 36px） */
  --table-cell-pad-y: 12px;      /* 默认档单元格上下 padding */
  --table-header-h: 36px;        /* 表头：字重 500 + --text-quiet + --bg-subtle + sticky */
  --stat-value-font: 20px;       /* §9.2 KPI 数值，数据面唯一允许的字号例外 */
  --stat-label-font: 12px;       /* §9.2 指标名 */
  --stat-delta-font: 12px;       /* §9.2 环比 */
  --drawer-w-sm: 480px;          /* DESIGN §6.3：紧凑任务抽屉 */
  --dialog-h-max: 88dvh;         /* §7.1 弹窗高度上限（向导类另用 --dialog-h-wizard） */

  /* 表面两档：--surface = 当前卡片底色档（= --bg，§12 的 surface 档）；
     --bg-subtle = 表头 sticky 底色 / 展开行 / 悬停反馈的淡底档。
     淡底取「3% 正文色压在画布上」（浅 #f8f8f8 / 深 #1e2023），而不是直接复用 --bg-elevated：
     #f1f1f1 会让坐在它上面的 --text-quiet 只剩 4.0:1，违反 §1 不变量 4（见下）。 */
  --surface: var(--bg);
  --bg-subtle: color-mix(in srgb, var(--text) 3%, var(--bg));
  /* 辅助文字再弱一档（§3.1 任务-待办、§9.1 表头与空单元格 `—`）。
     口径：在不变量 4（13px 正文 ≥4.5:1）允许范围内取最弱的一档。
     --text-muted #6b6b6b 对白 5.33:1；本档 = 95% --text-muted + 5% 画布
     = #727272，对白 4.81:1、压在 --bg-subtle 上 4.53:1；再弱一档（94%）在淡底上只剩 4.40:1。
     深色下随 --text-muted / --bg 自动提亮（#9da3ad 一类，对深画布 >6:1）。 */
  --text-quiet: color-mix(in srgb, var(--text-muted) 95%, var(--bg));

  /* 状态色的「文字档」（§3 状态职责）：--warning / --danger 当 13px 正文色时
     对比度不足（--warning 白底 3.62:1）。派生方式与 --primary-text / --accent-text
     一致：浅色压暗到 4.5:1 以上；深色在下方主题块里翻转派生方向。 */
  --warning-text: color-mix(in srgb, var(--warning) 84%, #000000); /* #c54703：对白 4.91:1，压在 --bg-subtle 上 4.62:1 */
  --danger-text: color-mix(in srgb, var(--danger) 84%, #000000);   /* #a53232：对白 6.77:1，压在 --bg-subtle 上 6.37:1 */
  /* 焦点环：shadcn 的 focus-visible 契约。环色沿用既有的 --focus-ring（单一来源），
     此处只补环宽与偏移两个 token。 */
  --focus-ring-width: 2px;
  --focus-ring-offset: 2px;
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --prose-measure: 38em;
  --shadow-quiet: rgba(0, 0, 0, 0.02) 0 4px 6px 0, rgba(0, 0, 0, 0.05) 0 0 2px 0;
  --duration-instant: 100ms;
  --duration-control: 140ms;
  --duration-enter: 220ms;
  --duration-exit: 180ms;

  /* Type scale — Codex Regular: 15/24 body, 16–18 page titles / 500. Ban 700.
     全部指向文末的 --ds-* 阶梯（Design System v1）：老页面继续用 --font-*，
     但取值只有一处来源，改 token 就等于全站改。 */
  --font-xs: var(--ds-font-sm);
  --font-sm: var(--ds-font-sm);
  --font-body: var(--ds-font-ui);
  --font-nav: var(--ds-font-body);
  --font-section: var(--ds-font-section);
  --font-title: var(--ds-font-block-title);
  --font-page-title: var(--ds-font-block-title);
  --leading-body: var(--ds-line-ui);
  --leading-tight: 1.35;
  --font-product: var(--ds-font-helper);
  --font-tag: var(--ds-font-tag);

  /* Legacy aliases — old names map into the scale above */
  --font-hero: var(--font-page-title);
  --font-ui: var(--ds-font-ui);
  --font-table: var(--font-sm);
  --font-meta: var(--ds-font-sm);
  --leading-hero: var(--leading-tight);
  --leading-ui: var(--ds-line-ui);

  /* Migration aliases — existing classes keep working */
  --canvas: var(--bg);
  --chrome: var(--bg-elevated);
  --line: var(--border);
  --muted: var(--text-muted);
  --star: var(--primary);
  --orange: var(--warning);
  --ok: var(--success);
  --red: var(--danger);

  --chrome-2: #eceef0;
  --sidebar-thumb: #d0d0d0;
  --left-width: 260px;
  --page-gutter: clamp(16px, 2.2vw, 28px);
  --mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --sans: ui-sans-serif, system-ui, "PingFang SC", "Noto Sans SC", "WenQuanYi Micro Hei", "Droid Sans Fallback", sans-serif;

  /* MASTER Quick Start aliases — parallel names, existing --font-* / --space-* stay canonical */
  --text-caption: var(--font-xs);
  --leading-caption: 1.51;
  --tracking-caption: -0.13px;
  --text-input: var(--font-ui);
  --leading-input: 1.5;
  --tracking-input: -0.16px;
  --text-body-lg: var(--font-section);
  --leading-body-lg: 1.32;
  --tracking-body-lg: -0.18px;
  --text-subheading: var(--font-page-title);
  --leading-subheading: 1.26;
  --tracking-subheading: -0.22px;
  --text-heading: var(--font-page-title);
  --leading-heading: 1.21;
  --tracking-heading: 0.31px;
  --text-display: 48px;
  --leading-display: 1.16;
  --tracking-display: -1.44px;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --spacing-unit: 4px;
  --spacing-4: var(--space-1);
  --spacing-8: var(--space-2);
  --spacing-12: var(--space-3);
  --spacing-16: var(--space-4);
  --spacing-20: 20px;
  --spacing-24: var(--space-5);
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-52: 52px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-120: 120px;
  --radius-full: 9999px;
  --radius-tags: 9999px;
  --radius-cards: 14px;
  --radius-links: 4px;

  /* 弹窗密度与字阶按 docs/DESIGN.md §4/§5/§7；旧名称仅供现有组件迁移。 */
  --dialog-w-sm: 440px;
  --dialog-w-md: 560px;
  --dialog-w-lg: 720px;
  --dialog-w-form: var(--dialog-w-md);
  --dialog-w-browse: var(--dialog-w-lg);
  --dialog-pad-x: 20px;
  --dialog-pad-t: 20px;
  --dialog-pad-b: 26px;
  --dialog-pad-compact-x: 12px;
  --dialog-pad-compact-y: 16px;
  --radius-dialog: 8px;
  --drawer-w-md: 720px;
  --drawer-w-lg: 960px;
  --drawer-pad-x: var(--dialog-pad-x);
  --drawer-pad-y: var(--space-4);
  --control-h-form: 32px;
  /* Shared attribute/field patterns, DESIGN §19.2. */
  --property-label-w-short: 96px;
  --property-label-w: 112px;
  --property-label-w-long: 128px;
  --property-label-gap: var(--space-5);
  --field-value-max-w: 360px;
  --field-value-wide-max-w: 480px;
  --list-row-h: 40px;
  --radius-field-form: var(--radius-control);
  --radius-btn-form: var(--radius-control);
  --radius-icon-box: var(--radius-control);
  --note-h-form: auto;
  --dialog-head-gap: var(--space-4);
  --dialog-foot-pad-t: var(--space-3);
  --line-dialog-title: var(--ds-line-section);
  --field-gap: var(--space-2);
  --block-gap: var(--space-4);
  --grid-gap: var(--space-4);
  --row-gap: var(--space-2);
  --icon-box: 44px;
  --font-dialog-title: var(--ds-font-section);
  --font-field: var(--ds-font-sm);
  --font-hint: var(--ds-font-helper);
  --fill-control: var(--control-bg);
  --fill-card: #f8f8f7;        /* 弹窗卡片底色 */
  --border-quiet: #dadad9;     /* 描边按钮边框 */
  --border-dashed: #e5e5e4;    /* 图标虚线框 */
  --hint-text: #737373;        /* 说明文字颜色 */
  --placeholder-text: #a6a6a6; /* 占位文字颜色 */
  --danger-soft: #ee5b5e;      /* 删除图标红 */
  --action-strong: var(--primary);
  --action-strong-fg: var(--primary-fg);
  --secret-card-pad: var(--space-4);
  --secret-value-h: auto;
  --secret-row-gap: var(--space-3);
  --help-icon: var(--icon-sm);
  --browse-line: #e9e9e8;      /* 卡片 / 选中页签 / ＋ 描边（取样 233,233,232） */
  --browse-fill: #f0f0ef;      /* 搜索框填充（取样 240,240,239） */
  --browse-tile: #ffffff;      /* 图标砖底色（取样白砖） */
  --font-browse-title: var(--ds-font-section);
  --font-browse-desc: var(--ds-font-helper);
  --lh-browse-desc: var(--ds-line-helper);
  /* 连接器设置向导（弹窗内四步）。 */
  --wizard-step-h: var(--control-h-form);
  --wizard-step-gap: var(--space-1);
  --wizard-gap: 12px;          /* 步骤条 / 状态行 / 内容之间的纵向间距（收口 --block-gap 18） */
  --wizard-status-gap: 4px;    /* 步骤条到状态行 */
  --wizard-gate-gap: var(--space-1);
  --dialog-h-wizard: min(94dvh, 900px);  /* 向导弹窗高度上限（88dvh 会把步骤条挤出 900 高视口） */

  /* Primary tone scale for cards and panels (used by home-workbench review cards). */
  --radius-inputs: 22px;
  --radius-buttons: 9999px;
  --radius-nav: 8px;
  --composer-radius: 22px;
  --shadow-sm: var(--shadow-quiet);
  --surface-paper: var(--color-paper);
  --surface-ash: var(--color-ash);
  --surface-whisper: var(--color-whisper);

  font-family: var(--sans);
  font-size: var(--ds-font-section); /* match ChatGPT root; :root beats html, so this must not stay --font-body 15px */
  line-height: var(--leading-body);
  letter-spacing: 0;
  font-feature-settings: "kern" 1, "liga" 1, "calt" 1;
}

:root[data-theme="dark"] {
  --bg: #17191d;
  --bg-elevated: #101216;
  --border: #30343b;
  --border-strong: #77808c;
  --control-border: #77808c;
  --control-border-hover: #a2a8b2;
  --control-border-invalid: #ef7777;
  --control-bg: #23262c;
  /* 连接器弹窗在深色下沿用同一职责 token。 */
  --fill-control: #23262c;
  --fill-card: #17191d;
  --border-quiet: #3a3f47;
  --border-dashed: #3a3f47;
  --hint-text: #a2a8b2;
  --placeholder-text: #7b828c;
  --danger-soft: #ef7777;
  --action-strong: var(--primary);
  --action-strong-fg: var(--primary-fg);
  /* 浏览弹窗三色在深色下回落既有深色档（对照 --border / --fill-control）。 */
  --browse-line: #30343b;
  --browse-fill: #23262c;
  --browse-tile: #23262c;
  --focus-ring: #ffffff;
  --text: #f1f3f5;
  --text-muted: #a2a8b2;
  --primary: #E0508C;
  /* 深色里主色本身较亮：实底上的字改用画布色 #17191d（4.77:1 ✓），白字只有 3.69:1。 */
  --primary-fg: var(--bg);
  --primary-text: var(--primary); /* 深色下派生方向翻转：提亮而非压暗（对深画布 4.77:1 ✓） */
  --primary-hover: #C73B7A;
  /* 辅助色在深色下同样翻转：直接用 accent 本身（对 #17191d 5.00:1 ✓）。 */
  --accent-hover: #639aff;
  --accent-text: var(--accent);
  --accent-fg: var(--bg);
  /* 类别色在深色下同样翻转：基色提亮、字形档直接用基色；砖底 / 描边随 --bg / --border
     自动跟随，--cat-builtin 随 --text-muted 变亮。实测字形档对砖底 6.18–7.64:1。 */
  --cat-library: #909bff;
  --cat-assistant: #c39bff;
  --cat-crawl: #56c6dd;
  --cat-library-text: var(--cat-library);
  --cat-assistant-text: var(--cat-assistant);
  --cat-crawl-text: var(--cat-crawl);
  --cat-builtin-text: var(--cat-builtin);
  --chrome-2: #23262c;
  --sidebar-thumb: #5a616b;
  /* 状态色文字档在深色下翻转派生方向（同 --primary-text）：
     --danger #c43c3c 对深画布只有 3.40:1，需提亮到 #de9494（7.35:1）；
     --warning #ea5504 本身 4.86:1 已达标，直接沿用。 */
  --warning-text: var(--warning);
  --danger-text: color-mix(in srgb, var(--danger) 55%, #ffffff);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #17191d;
    --bg-elevated: #101216;
    --border: #30343b;
    --border-strong: #77808c;
    --control-border: #77808c;
    --control-border-hover: #a2a8b2;
    --control-border-invalid: #ef7777;
    --control-bg: #23262c;
    --focus-ring: #ffffff;
    --text: #f1f3f5;
    --text-muted: #a2a8b2;
    --primary: #E0508C;
    /* 同 :root[data-theme="dark"]：深色下实底字用画布色，主色文字档改提亮。 */
    --primary-fg: var(--bg);
    --primary-text: var(--primary);
    --primary-hover: #C73B7A;
    --accent-hover: #639aff;
    --accent-text: var(--accent);
    --accent-fg: var(--bg);
    /* 同 :root[data-theme="dark"]：类别色基色提亮、字形档用基色。 */
    --cat-library: #909bff;
    --cat-assistant: #c39bff;
    --cat-crawl: #56c6dd;
    --cat-library-text: var(--cat-library);
    --cat-assistant-text: var(--cat-assistant);
    --cat-crawl-text: var(--cat-crawl);
    --cat-builtin-text: var(--cat-builtin);
    --chrome-2: #23262c;
    --sidebar-thumb: #5a616b;
    /* 同 :root[data-theme="dark"]：状态色文字档翻转派生方向。 */
    --warning-text: var(--warning);
    --danger-text: color-mix(in srgb, var(--danger) 55%, #ffffff);
  }
}

* { box-sizing: border-box; }
* {
  scrollbar-width: thin;
  scrollbar-color: #d0d0d0 transparent;
}
*::-webkit-scrollbar {
  width: var(--scrollbar-size, 6px);
  height: var(--scrollbar-size, 6px);
}
*::-webkit-scrollbar-track { background: transparent; }
*::-webkit-scrollbar-thumb {
  background: #d0d0d0;
  border-radius: var(--ds-radius-tag);
}
*::-webkit-scrollbar-thumb:hover { background: #c4c4c4; }
html, body, #root { height: 100%; margin: 0; overflow: hidden; }
html {
  font-size: var(--ds-font-section); /* match ChatGPT root font-size */
}
html, body {
  font-family: var(--sans);
  font-weight: 400;
  line-height: var(--leading-body);
  color: #1a1a1a;
}
body {
  background: var(--bg-elevated);
  color: var(--text);
  font-family: var(--sans);
  font-size: var(--ds-font-ui);
  font-weight: 400;
}
h1 {
  font-size: var(--font-title);
  font-weight: 500;
  line-height: var(--leading-hero);
  letter-spacing: 0;
}
h2, h3, h4, strong, b {
  font-weight: 600;
}
a { color: var(--text); } /* quiet shell: --primary is filled CTA, not link ink */
a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
summary:focus-visible,
[tabindex]:not([tabindex="-1"]):focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}
/* Filled primary controls: invert outline on --primary pink + outer --focus-ring halo. */
.btn.work:focus-visible,
.btn.send:not(.send-arrow):focus-visible,
.settings-v2 .settings-primary:focus-visible,
.settings-memory-drawer .settings-primary:focus-visible,
.stage-chip.is-selected:focus-visible,
.follow-style-chip.is-on:focus-visible,
.suggested-actions button.is-on:focus-visible,
.suggested-actions button[aria-pressed="true"]:focus-visible,
.result-actions button.is-on:focus-visible,
.result-actions a.is-on:focus-visible {
  outline: 2px solid var(--bg);
  outline-offset: 2px;
  box-shadow: 0 0 0 4px var(--focus-ring);
}

.workbench {
  display: grid;
  grid-template-columns: var(--left-width) minmax(0, 1fr);
  height: 100%;
  min-height: 100%;
  overflow: hidden;
  background: var(--color-page-bg);
}
.workbench.sidebar-collapsed { --left-width: 56px; }
/* 管理面不再隐藏侧栏：员工端与管理端共用同一侧栏外壳，只换条目集合
   （docs/superpowers/specs/2026-09-26-admin-sidebar-shell-parity.md）。
   `admin-surface` 只作为钩子类保留（E2E / 脚本），不再参与布局。 */
.sidebar {
  width: var(--left-width);
  min-width: var(--left-width);
  background: var(--color-page-bg);
  border-right: 1px solid var(--border);
  /* No right padding: .sidebar-scroll must reach the 260 rail edge (~255 thumb). */
  padding: 12px 0 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-height: 0;
  height: 100%;
  overflow: hidden;
}
.sidebar-scroll {
  flex: 1 1 auto;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  /* Text inset only — do not reserve a classic ~16px gutter. */
  padding-right: 6px;
  scrollbar-gutter: auto;
}
/* ChatGPT thin rail scrollbar — light thumb, transparent track, no Windows arrows. */
.sidebar,
.sidebar-scroll {
  scrollbar-width: thin;
  scrollbar-color: #c7c7c7 transparent;
}
.sidebar::-webkit-scrollbar,
.sidebar-scroll::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
.sidebar::-webkit-scrollbar-track,
.sidebar-scroll::-webkit-scrollbar-track {
  background: transparent;
}
.sidebar::-webkit-scrollbar-thumb,
.sidebar-scroll::-webkit-scrollbar-thumb {
  background: #c7c7c7;
  border-radius: 99px;
}
.sidebar::-webkit-scrollbar-button,
.sidebar-scroll::-webkit-scrollbar-button {
  display: none;
  width: 0;
  height: 0;
}
.sidebar-nav-stack {
  display: flex;
  flex-direction: column;
  gap: 0;
  min-height: 0;
}
.sidebar-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  padding: 0 0 4px;
  margin-bottom: 4px;
}
.sidebar-brand {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  min-width: 0;
  text-decoration: none;
  color: inherit;
}
.sidebar-brand .brand-lockup--sidebar {
  justify-content: flex-start;
}
.sidebar-brand .brand-logo {
  height: 30px;
  width: auto;
  max-width: 148px;
}
.sidebar-lucas {
  flex: 0 0 30px;
  width: 30px;
  height: 30px;
  display: inline-grid;
  place-items: center;
}
.sidebar-lucas img {
  display: block;
  width: 30px;
  height: 30px;
  object-fit: contain;
}
.brand-name {
  font-size: var(--font-product);
  font-weight: 400;
  color: var(--text-muted);
  text-decoration: none;
  letter-spacing: 0;
  line-height: 1.3;
}
.rail-logo { display: none; }
.rail-logo::after { content: "灵"; }
.collapse-toggle { margin-left: auto; }
.workbench.sidebar-collapsed .sidebar { padding-inline: 8px 0; }
.workbench.sidebar-collapsed .sidebar-scroll { padding-right: 0; }
.workbench.sidebar-collapsed .sidebar-label,
.workbench.sidebar-collapsed .nav-label,
.workbench.sidebar-collapsed .nav-tag,
.workbench.sidebar-collapsed .nav-combo a,
.workbench.sidebar-collapsed .nav-combo .nav-dot,
.workbench.sidebar-collapsed .brand-name,
.workbench.sidebar-collapsed .sidebar-lucas,
.workbench.sidebar-collapsed .account-copy { display: none; }
.workbench.sidebar-collapsed .rail-logo { display: inline; }
.workbench.sidebar-collapsed .sidebar-head { justify-content: center; padding-inline: 0; }
.workbench.sidebar-collapsed .sidebar-brand { align-items: center; }
.workbench.sidebar-collapsed .sidebar-brand .brand-logo { height: 28px; max-width: 32px; object-fit: contain; }
.workbench.sidebar-collapsed .collapse-toggle { margin: 0; }
.workbench.sidebar-collapsed .nav-link,
.workbench.sidebar-collapsed .nav-combo { justify-content: center; padding-inline: 8px; }
/* 账户块在 56px 轨道里竖排：头像 / 竖向分段 / 设置 / 退出，三件事都还在，不靠弹窗。 */
.workbench.sidebar-collapsed .account-bar {
  flex-direction: column;
  align-items: center;
  gap: var(--space-1);
  padding-inline: 0;
}
.workbench.sidebar-collapsed .account-identity {
  flex: 0 0 auto;
  justify-content: center;
  padding: 0;
}
.workbench.sidebar-collapsed .account-avatar {
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
  margin: 0 auto;
}
.workbench.sidebar-collapsed .account-actions {
  flex-direction: column;
  align-items: center;
  gap: 2px;
}
.workbench.sidebar-collapsed .surface-switch {
  flex-direction: column;
  height: auto;
}
.workbench.sidebar-collapsed .surface-switch-seg {
  width: var(--control-h);
  height: var(--control-h);
}
/* 56px 轨道放不下版本号整串：整行隐藏，不让 .sidebar 静默裁切（DESIGN §不变量 5）。 */
.workbench.sidebar-collapsed .sidebar-version { display: none; }
.sidebar-search-btn {
  width: 36px;
  height: 36px;
  border: 0;
  background: transparent;
  color: var(--muted);
  border-radius: 0;
  cursor: pointer;
  display: grid;
  place-items: center;
  padding: 0;
}
/* 面板图标按规则 17 走控件档（--icon-sm），描边加粗一档保住辨识度。 */
.sidebar-search-btn svg { width: var(--icon-sm); height: var(--icon-sm); stroke-width: 2.2; }
.sidebar-search-btn:hover {
  background: color-mix(in srgb, var(--text) 6%, transparent);
  color: var(--text);
}
.nav-group { display: flex; flex-direction: column; gap: 2px; }
.nav-group + .nav-group {
  margin-top: 6px;
  padding-top: 8px;
  border-top: 1px solid var(--border);
}
.nav-label {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
.nav-ico {
  width: 18px;
  height: 18px;
  flex: 0 0 18px;
  color: #5c6370;
}
.nav-link, .nav-combo {
  color: var(--text);
  text-decoration: none;
  padding: 8px 10px;
  border-radius: var(--radius-nav);
  font-size: var(--font-nav);
  font-weight: 400;
  border: 1px solid transparent;
  display: flex;
  align-items: center;
  gap: 10px;
  background: transparent;
  min-height: 38px;
  min-width: 0;
}
.nav-link .sidebar-label,
.nav-combo a {
  white-space: normal;
  overflow-wrap: anywhere;
  min-width: 0;
}
.nav-tag,
.mobile-top a,
.mobile-top strong {
  white-space: nowrap;
}
.nav-link .sidebar-label,
.nav-combo a {
  font-weight: 400;
}
.nav-link:hover, .nav-combo:hover {
  background: color-mix(in srgb, var(--text) 6%, transparent);
  color: var(--text);
}
.nav-link:hover .nav-ico, .nav-combo:hover .nav-ico { color: var(--text); }
.nav-link.active, .nav-combo.active {
  background: var(--color-ash);
  color: var(--text);
  border-color: transparent;
  box-shadow: none;
  font-weight: 500;
}
.nav-link.active .nav-ico, .nav-combo.active .nav-ico { color: var(--text); }
.nav-combo { color: var(--text); }
.nav-combo a {
  color: inherit;
  text-decoration: none;
}
.nav-combo a.on { color: var(--text); font-weight: 500; }
.nav-combo.active a { color: var(--text-muted); font-weight: 400; }
.nav-combo.active a.on { color: var(--text); font-weight: 500; }
.nav-dot { color: var(--muted); }
.nav-combo.active .nav-dot { color: var(--text-muted); }
.nav-link.is-disabled {
  color: #9aa0a8;
  cursor: not-allowed;
  pointer-events: none;
}
.nav-tag {
  margin-left: auto;
  font-size: var(--font-tag);
  font-weight: 400;
  color: var(--muted);
  border: 1px solid var(--border);
  background: transparent;
  border-radius: var(--ds-radius-tag);
  padding: 1px 6px;
  line-height: 1.3;
}
.menu-popover {
  position: absolute;
  z-index: 80;
  min-width: 150px;
  padding: 6px;
  border: 1px solid var(--line);
  border-radius: 0;
  background: var(--canvas);
  box-shadow: var(--shadow-quiet);
  display: grid;
}
.menu-popover a, .menu-popover button {
  border: 0; background: none; color: var(--text); text-decoration: none;
  text-align: left; font: inherit; font-size: var(--font-ui); padding: 7px 9px; border-radius: 0; cursor: pointer;
  min-height: 36px;
}
.menu-popover a:hover, .menu-popover button:hover { background: color-mix(in srgb, var(--text) 6%, transparent); color: var(--text); }
.menu-popover a.active { background: var(--bg-elevated); color: var(--text); font-weight: 600; }
.danger-text { color: var(--red) !important; }
.status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex: 0 0 6px;
  background: var(--text-muted);
}
.status-dot.listening { background: var(--text-muted); }
.status-dot.running { background: var(--text); animation: breath-dot 1.8s ease-in-out infinite; }
.status-dot.waiting_approval { background: var(--warning); animation: breath-dot 2.2s ease-in-out infinite; }

.sidebar-foot {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid #eee;
  display: flex;
  flex-direction: column;
  gap: 0;
  flex: 0 0 auto;
}
/* 账户块：一行——头像 + 账号名 + 员工端⇄管理端分段切换 + 个人设置 + 退出登录。
   三件事都是常驻控件，不用弹窗；员工端侧栏脚与管理端导航脚共用同一个组件。
   角色文案（管理员/员工）按用户要求不再呈现，身份只留账号名。 */
.account-bar {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  min-width: 0;
  /* 页脚三件套（员工端⇄管理端切换 / 个人设置 / 退出登录）整体左移 30px，不贴右轨道边；
     收起态由 .workbench.sidebar-collapsed .account-bar 的 padding-inline: 0 覆盖回去。 */
  padding-right: 30px;
}
.account-identity {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  flex: 1 1 auto;
  min-width: 0;
  color: var(--text);
}
.account-avatar {
  width: var(--control-h);
  height: var(--control-h);
  flex: 0 0 var(--control-h);
  border-radius: var(--radius-full);
  background: color-mix(in srgb, var(--accent) 14%, var(--bg));
  color: var(--accent-text);
  font-size: var(--ds-font-sm);
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}
.account-avatar img[data-account-avatar],
.employee-person img[data-employee-avatar] {
  width: 100%;
  height: 100%;
  border-radius: inherit;
  object-fit: cover;
  display: block;
}
.account-copy {
  min-width: 0;
  display: grid;
  gap: 1px;
  flex: 1 1 auto;
}
.account-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--ds-font-sm);
  font-weight: 500;
  line-height: 1.3;
  color: var(--text);
}
.account-actions {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  flex: 0 0 auto;
}
.surface-switch {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  height: var(--control-h);
  padding: 2px;
  border: 1px solid var(--border);
  border-radius: var(--radius-full);
  background: var(--bg);
  flex: 0 0 auto;
}
.surface-switch-seg {
  width: 30px;
  height: 100%;
  display: grid;
  place-items: center;
  border-radius: var(--radius-full);
  color: var(--text-muted);
  text-decoration: none;
}
.surface-switch-seg .nav-ico,
.account-icon-btn .nav-ico { color: inherit; }
.surface-switch-seg:hover {
  background: color-mix(in srgb, var(--text) 6%, transparent);
  color: var(--text);
}
.surface-switch-seg[aria-current="page"],
.surface-switch-seg[aria-current="page"]:hover {
  background: var(--accent-text);
  color: var(--accent-fg);
}
.account-icon-btn {
  width: var(--control-h);
  height: var(--control-h);
  flex: 0 0 var(--control-h);
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: var(--radius-control);
  background: none;
  color: var(--text-muted);
  cursor: pointer;
}
.account-icon-btn:hover {
  background: color-mix(in srgb, var(--text) 6%, transparent);
  color: var(--text);
}

.main {
  min-width: 0;
  min-height: 0;
  height: 100%;
  padding: 0;
  background: var(--canvas);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.main > :not(.ontology-workspace):not(.perf-ant-app):not(.perf-workspace):not(.session-shell):not(.session-workspace):not(.home-pane):not(.admin-shell):not(.skill-catalog-page):not(.kbv-page):not(.tasks-page) {
  flex: 1 1 auto;
  min-height: 0;
  min-width: 0;
  padding: 20px var(--page-gutter) 40px;
  width: min(100%, 1360px);
  overflow-x: hidden;
  overflow-y: auto;
}

.main > .skill-catalog-page {
  flex: 1 1 auto;
  min-height: 0;
  min-width: 0;
  width: 100%;
  /* 页面自管左右留白（--page-gutter）与发丝分隔带，壳层不再加第二层内边距。 */
  padding: 0;
  overflow: hidden;
}
.main > .admin-shell {
  flex: 1 1 auto;
  min-height: 0;
  min-width: 0;
  width: 100%;
  padding: 0;
  overflow: hidden;
}
.page-kicker {
  font-size: var(--font-meta);
  font-weight: 400;
  letter-spacing: 0;
  color: var(--muted);
  margin-bottom: 6px;
}

/* Home + Agents visual pass: OpenAI-quiet tokens, no card-wall. */
.home-pane {
  flex: 1;
  height: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  background: var(--bg);
  overflow: hidden;
  /* Home-only wider rail. Keep --page-gutter for session-shell / other pages. */
  --home-gutter: clamp(10px, 0.7vw, 12px);
}
.home-loading { padding: 32px; }
.home-stage {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: flex-start;
  padding: 20px var(--home-gutter) 0;
  /* The single scroll container for the whole workspace. */
  overflow-y: auto;
  overflow-x: hidden;
}
.home-board {
  /* Plain flow inside the stage: no second scroll container, no flex squeeze. */
  flex: 0 0 auto;
  overflow: visible;
  padding-bottom: 8px;
}
.home-pane-sticky {
  position: sticky;
  top: 0;
  z-index: 3;
  background: var(--canvas);
  padding: 2px 0 8px;
}
.home-hero {
  width: 100%;
  max-width: none;
  display: flex;
  flex-direction: column;
  align-items: stretch;
}
.brand-lockup {
  display: flex;
  flex-direction: row;
  flex-wrap: nowrap;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.brand-logo {
  display: block;
  height: 30px;
  width: auto;
  flex: 0 0 auto;
}
.brand-slogans {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 2px;
  min-width: 0;
  max-width: 100%;
  text-align: left;
}
.brand-mark,
.brand-slogan-en,
.brand-slogan-zh {
  margin: 0;
  font-size: var(--font-xs);
  font-weight: 500;
  line-height: 1.25;
}
.brand-mark {
  font-size: var(--font-xs);
  font-weight: 400;
  letter-spacing: 0.02em;
  color: var(--text-muted);
  white-space: nowrap;
}
.brand-slogan-en {
  color: var(--text-muted);
  font-weight: 400;
  opacity: 0.72;
  white-space: normal;
  overflow-wrap: anywhere;
}
.brand-slogan-zh {
  color: var(--text-muted);
  font-weight: 400;
  opacity: 0.72;
  white-space: normal;
  overflow-wrap: anywhere;
}
.brand-lockup--sidebar {
  justify-content: flex-start;
  margin: 0;
  max-width: 100%;
}
.brand-lockup--home {
  justify-content: flex-start;
  margin: 0;
  max-width: 100%;
}
.brand-lockup--dialog {
  justify-content: flex-start;
  margin: 0 22px 10px;
}
.brand-lockup--dialog .brand-logo {
  height: 36px;
}
.home-hero h1,
.page-conclusion {
  font-size: var(--font-page-title);
  font-weight: 500;
  margin: var(--space-2) 0 var(--space-3);
  letter-spacing: -0.01em;
  line-height: var(--leading-tight);
  color: var(--text);
  text-align: left;
}
.task-catalog {
  display: grid;
  gap: 18px;
  width: 100%;
  margin-top: 18px;
}
.task-group h2 {
  margin: 0 0 8px;
  color: var(--text);
  font-size: var(--font-section);
  font-weight: 500;
  letter-spacing: 0;
}
.recs {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 8px;
  width: 100%;
}
.rec {
  position: relative;
  background: var(--canvas);
  border: 1px solid var(--line);
  border-radius: var(--ds-radius-input);
  padding: 11px 34px 11px 12px;
  text-align: left;
  cursor: pointer;
  font: inherit;
  color: var(--text);
  display: grid;
  gap: 3px;
  max-width: 100%;
  min-height: 68px;
}
.rec:hover { border-color: var(--accent); background: var(--bg-elevated); }
.rec:disabled { opacity: 0.55; cursor: not-allowed; }
.rec .rec-title, .rec h3 {
  margin: 0;
  font-size: var(--font-ui);
  font-weight: 400;
}
.rec-description {
  color: var(--muted);
  font-size: var(--font-meta);
  line-height: 1.45;
}
.rec-arrow {
  position: absolute;
  right: 12px;
  top: 50%;
  color: var(--muted);
  transform: translateY(-50%);
}

.home-hero { padding-bottom: 0; flex: 0 0 auto; }
.journey-guide {
  width: 100%;
  margin: 8px 0 18px;
  padding: 12px 14px 14px;
  border: 1px solid var(--line);
  border-radius: var(--ds-radius-section);
  background: var(--chrome);
}
.home-pane.is-composer-focused .journey-guide { opacity: .85; }
.journey-strip,
.journey-funnel {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 8px;
  list-style: none;
  margin: 0 0 10px;
  padding: 0;
}
.journey-strip li,
.journey-funnel li {
  color: var(--muted);
  font-size: var(--font-meta);
  line-height: 1.4;
}
.journey-strip li.is-current,
.journey-funnel li.is-current {
  color: var(--accent-text);
  font-weight: 600;
}
.journey-copy strong {
  display: block;
  font-size: var(--font-sm);
  font-weight: 600;
  margin-bottom: 4px;
}
.journey-copy p {
  margin: 0;
  color: var(--text);
  font-size: var(--font-ui);
  line-height: 1.6;
  max-width: 52rem;
}
.journey-mode {
  margin-top: 4px !important;
  color: var(--muted) !important;
  font-size: var(--font-xs) !important;
}
.journey-gaps {
  margin: 10px 0 0;
  color: var(--muted);
  font-size: var(--font-sm);
  line-height: var(--leading-body);
  max-width: 52rem;
}
.journey-guide.is-compact {
  margin: 0 0 12px;
  padding: 10px 12px;
}
.today-summary,
.recommend-work,
.home-mode-pane {
  width: 100%;
  min-width: 0;
  max-width: 100%;
  overflow-x: hidden;
  transition: opacity .2s ease;
}
/* Dimming the whole pane while the composer has focus reads as the ask box
   covering the result. Keep the fade on the summary strips only. */
.home-pane.is-composer-focused .today-summary,
.home-pane.is-composer-focused .recommend-work {
  opacity: .85;
}
.home-stats {
  margin: 0 0 var(--space-2);
  color: var(--text-muted);
  font-size: var(--font-meta);
  line-height: 1.5;
  white-space: normal;
  overflow-wrap: anywhere;
}
/* Followed/lifecycle: collapse the task-spine summary so the object list
   gets the vertical pixels. Other modes keep 「N项待处理 · 逾期 · 今天到期」. */
[data-home-active-mode="lifecycle"] .home-stats,
[data-home-active-mode="pool"] .home-stats,
[data-followed-chrome="compact"] .home-stats {
  display: none;
}
[data-home-active-mode="lifecycle"] .home-mode-tabs,
[data-followed-chrome="compact"] .home-mode-tabs {
  margin-bottom: var(--space-2);
}
.home-mode-tabs {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: var(--space-2) var(--space-4);
  width: 100%;
  border-bottom: 1px solid var(--border);
  margin: 0 0 var(--space-3);
  overflow: visible;
}
.home-mode-tabs button[role="tab"] {
  border: 0;
  border-bottom: 2px solid transparent;
  background: none;
  margin-bottom: -1px;
  padding: 8px 0 10px;
  color: var(--muted);
  font: inherit;
  font-size: var(--font-body);
  font-weight: 400;
  white-space: nowrap;
  cursor: pointer;
  min-height: 36px;
}
.home-mode-tabs button[role="tab"][aria-selected="true"] {
  color: var(--text);
  border-bottom-color: var(--text);
  font-weight: 500;
}
.home-mode-count {
  font-size: var(--font-xs);
  font-weight: 400;
  color: var(--text-muted);
  flex: 0 0 auto;
  margin-left: var(--home-mode-tab-gap);
}
.home-mode-dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  margin: 0 0 8px 6px;
  border-radius: 50%;
  background: var(--red);
  vertical-align: middle;
}
.home-templates-link {
  margin-left: auto;
  border: 0;
  background: none;
  color: var(--muted);
  font: inherit;
  font-size: var(--font-sm);
  cursor: pointer;
  padding: 8px 0 10px;
  white-space: nowrap;
}
.home-templates-link:hover { color: var(--accent-text); }
.recommended-tasks {
  width: 100%;
  max-width: 42rem;
  margin: 0 0 16px;
  overflow-x: hidden;
}
.recommend-md-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 2px;
}
.recommend-md-item {
  display: grid;
  grid-template-columns: 1.6em 1.4em minmax(0, 1fr);
  gap: var(--space-2);
  align-items: start;
  width: 100%;
  border: 0;
  background: transparent;
  text-align: left;
  font: inherit;
  color: var(--text);
  padding: var(--space-1) var(--space-2);
  border-radius: var(--radius-sm);
  cursor: pointer;
  min-height: 36px;
}
.recommend-md-item:hover { background: var(--bg-elevated); }
.recommend-md-item:disabled { opacity: 0.55; cursor: not-allowed; }
.recommend-md-n {
  font-family: var(--mono);
  color: var(--muted);
  font-size: var(--font-sm);
  line-height: var(--leading-body);
}
.recommend-md-icon {
  font-size: var(--ds-font-body);
  line-height: 1.5;
}
.recommend-md-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}
.recommend-md-copy strong {
  font-size: var(--font-ui);
  font-weight: 400;
}
.recommend-md-reason {
  color: var(--muted);
  font-size: var(--font-xs);
  line-height: 1.45;
}
.home-lane-label {
  margin: 0 0 var(--space-2);
  color: var(--text-muted);
  font-size: var(--font-meta);
  font-weight: 500;
  letter-spacing: 0;
}
.recommend-md-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: var(--space-2);
  align-items: start;
  min-width: 0;
}
.recommend-to-todo {
  margin-top: 2px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg);
  color: var(--text-muted);
  font: inherit;
  font-size: var(--font-sm);
  line-height: var(--leading-tight);
  padding: 6px 10px;
  cursor: pointer;
  white-space: nowrap;
  min-height: 36px;
}
.recommend-to-todo:hover {
  color: var(--accent-text);
  border-color: var(--accent);
}
.recommend-to-todo:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}
.today-existing-todos {
  margin: var(--space-4) 0 0;
  width: 100%;
  max-width: none;
}
.today-brief {
  margin: 0 0 var(--space-3);
  color: var(--text);
  font-size: var(--font-ui);
}
.today-brief-lead {
  margin: 0 0 var(--space-2);
  font-weight: 600;
}
.today-brief-primary {
  margin: 0 0 var(--space-3);
  color: var(--accent-text);
  font-size: var(--font-sm);
  font-weight: 600;
}
.today-brief-sections {
  display: grid;
  gap: var(--space-3);
  margin: 0 0 var(--space-3);
}
.today-brief-section h3 {
  margin: 0 0 4px;
  font-size: var(--font-sm);
}
.today-brief-section p,
.today-brief-section ul {
  margin: 0;
  color: var(--text-muted);
  font-size: var(--font-xs);
  line-height: 1.45;
}
.today-todo-list,
.today-todo-ol,
.today-todo-row {
  min-width: 0;
  max-width: 100%;
  overflow-x: hidden;
}
.today-todo-ol {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: var(--space-3);
}
.today-todo-row {
  display: grid;
  gap: 4px;
  padding: var(--space-2) 0;
  border-bottom: 1px solid var(--border);
}
.today-todo-row:last-child {
  border-bottom: 0;
}
.today-todo-line {
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
}
.today-todo-line1 {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}
.today-todo-label {
  flex: 0 0 auto;
  color: var(--accent-text);
  font-size: var(--font-xs);
  font-weight: 600;
  white-space: nowrap;
}
.today-todo-title {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--font-ui);
}
.today-todo-title strong {
  font-weight: 500;
}
.today-todo-due {
  color: var(--text-muted);
  font-weight: 400;
}
.today-todo-act {
  flex: 0 0 auto;
  margin: 0;
  border: 0;
  border-radius: var(--radius-sm);
  background: var(--primary);
  color: #fff;
  font: inherit;
  font-size: var(--font-sm);
  line-height: 1;
  padding: 8px 12px;
  min-height: 32px;
  cursor: pointer;
  white-space: nowrap;
}
.today-todo-act:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}
.today-todo-line2 {
  margin: 0;
  color: var(--text-muted);
  font-size: var(--font-xs);
  line-height: 1.45;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.home-dedupe-notice {
  margin: 0 0 var(--space-2);
  color: var(--text-muted);
  font-size: var(--font-meta);
}
.discovery-composer-conditions {
  display: grid;
  gap: var(--space-3);
  padding: 0 4px 10px;
  min-width: 0;
  overflow-x: hidden;
}
.discovery-composer-conditions .discovery-chip-row {
  flex-wrap: wrap;
}
.composer-override-hint {
  margin: 0 4px 8px;
  color: var(--text-muted);
  font-size: var(--font-sm);
}
.discovery-process {
  list-style: none;
  margin: 0 0 var(--space-3);
  padding: 0;
  display: grid;
  gap: var(--space-1);
  color: var(--text-muted);
  font-size: var(--font-sm);
}
.discovery-result-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: var(--space-2) var(--space-3);
  margin: 0 0 var(--space-3);
  min-width: 0;
}
.discovery-result-head h2 {
  margin: 0;
  font-size: var(--font-section);
  line-height: var(--leading-tight);
}
.discovery-result-head p,
.discovery-toast {
  margin: 0 0 var(--space-3);
  color: var(--text-muted);
  font-size: var(--font-sm);
}
.discovery-toast a {
  color: var(--accent-text);
}
.discovery-form {
  display: grid;
  gap: var(--space-2);
  margin: 0 0 var(--space-2);
}
.discovery-query-label {
  display: grid;
  gap: var(--space-1);
}
.discovery-query-label .home-lane-label {
  margin: 0;
}
.discovery-query-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: var(--space-2);
}
.discovery-query {
  width: 100%;
  min-width: 0;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg);
  color: var(--text);
  font: inherit;
  font-size: var(--font-ui);
  line-height: var(--leading-tight);
  padding: var(--space-2) var(--space-3);
  resize: vertical;
  min-height: 36px;
}
.discovery-filters {
  display: grid;
  gap: var(--space-2);
  min-width: 0;
  overflow-x: hidden;
}
.discovery-condition-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
  min-width: 0;
}
.discovery-condition-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2) var(--space-3);
  margin-left: auto;
}
.discovery-match-count {
  margin: 0;
  color: var(--text-muted);
  font-size: var(--font-sm);
  line-height: 1.4;
}
.discovery-advanced-link {
  border: 0;
  background: transparent;
  color: var(--text-muted);
  font: inherit;
  font-size: var(--font-sm);
  line-height: 1.4;
  padding: 0;
  text-decoration: underline;
  text-underline-offset: 2px;
  cursor: pointer;
}
.discovery-advanced-link:hover {
  color: var(--text);
}
.discovery-condition-editor,
.discovery-advanced-panel {
  display: grid;
  gap: var(--space-2);
  min-width: 0;
  padding: var(--space-3);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg);
  box-shadow: var(--shadow-quiet);
}
.discovery-advanced-panel {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2);
}
.discovery-direction-editor {
  display: grid;
  gap: var(--space-2);
  flex: 1 1 auto;
  min-width: 0;
}
.discovery-chip-label {
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  padding: 0;
  cursor: pointer;
}
.discovery-chip-soft {
  height: 22px;
  min-height: 22px;
  padding: 0 var(--space-2);
  font-size: var(--font-xs);
  color: var(--text-muted);
  cursor: default;
}
.discovery-chip-soft:hover {
  border-color: var(--border);
}
.discovery-filters-reset {
  flex: 0 0 auto;
  border: 0;
  background: transparent;
  color: var(--text-muted);
  font: inherit;
  font-size: var(--font-sm);
  line-height: 1.4;
  padding: var(--space-1) 0;
  cursor: pointer;
}
.discovery-filters-reset:hover {
  color: var(--accent-text);
}
.discovery-filter-group {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-1) var(--space-2);
  min-width: 0;
}
.discovery-filter-title {
  flex: 0 0 auto;
  min-width: 2.5em;
  color: var(--text-muted);
  font-size: var(--font-sm);
  line-height: 1.4;
}
.discovery-filter-group .discovery-chip-row {
  flex: 1 1 auto;
}
.discovery-filter-group .discovery-direction-limit {
  flex: 1 1 100%;
}
.discovery-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  min-width: 0;
}
.discovery-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-1);
  height: 32px;
  min-height: 32px;
  padding: 0 var(--space-3);
  border: 1px solid var(--border);
  border-radius: 16px;
  background: var(--bg);
  color: var(--text);
  font: inherit;
  font-size: var(--font-sm);
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
}
.discovery-chip:hover {
  border-color: var(--accent);
}
.discovery-chip[aria-pressed="true"] {
  background: color-mix(in srgb, var(--accent) 14%, var(--bg));
  border-color: var(--accent);
  color: var(--accent-text);
}
.discovery-chip-tag {
  padding-right: 6px;
  cursor: default;
}
.discovery-chip-tag:hover {
  border-color: var(--border);
}
.discovery-chip-remove {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: var(--ds-radius-tag);
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: var(--font-sm);
  line-height: 1;
  cursor: pointer;
}
.discovery-chip-remove:hover {
  background: color-mix(in srgb, var(--accent) 12%, transparent);
}
.discovery-chip-add {
  color: var(--text-muted);
}
.discovery-direction-add {
  position: relative;
  min-width: 0;
}
.discovery-direction-add[data-open] {
  margin-bottom: 168px;
}
.discovery-direction-popover {
  position: absolute;
  z-index: 20;
  top: calc(100% + 6px);
  left: 0;
  width: min(320px, calc(100vw - 32px));
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg);
  box-shadow: var(--shadow-quiet);
  display: grid;
  gap: var(--space-2);
}
.discovery-direction-input {
  width: 100%;
  min-width: 0;
  height: 32px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg);
  color: var(--text);
  font: inherit;
  font-size: var(--font-sm);
  padding: 0 10px;
}
.discovery-chip-preset {
  height: 28px;
  min-height: 28px;
  font-size: var(--font-sm);
}
.discovery-direction-limit {
  margin: 0;
  color: var(--text-muted);
  font-size: var(--font-sm);
}
.discovery-form-actions,
.discovery-plan-actions,
.discovery-candidate-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}
.discovery-plan {
  display: grid;
  gap: var(--space-2);
  min-width: 0;
  padding: var(--space-2) 0 0;
  overflow-x: hidden;
}
.discovery-plan-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: var(--space-1) var(--space-2);
  min-width: 0;
}
.discovery-plan-head p {
  flex: 1 1 12rem;
}
.discovery-candidate {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: start;
  gap: var(--space-2);
  min-width: 0;
  padding: var(--space-2) 0;
  border-bottom: 1px solid var(--border);
  overflow-x: hidden;
}
.discovery-candidate-copy {
  min-width: 0;
  overflow-x: hidden;
}
.discovery-candidate-identity {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0 var(--space-2);
  min-width: 0;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.discovery-candidate-handle {
  min-width: 0;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.discovery-candidate-nickname {
  font-weight: 500;
  color: var(--text-muted);
  font-size: var(--font-ui);
}
.discovery-panel .task-empty,
.discovery-stream-panel .task-empty {
  padding: var(--space-3) var(--space-4);
  margin-top: var(--space-2);
  border-radius: var(--radius-md);
}
.discovery-panel .task-empty p,
.discovery-stream-panel .task-empty p {
  margin: var(--space-1) 0 0;
}
.discovery-candidate-actions {
  grid-column: 2;
  min-width: 0;
  justify-content: flex-start;
  align-items: center;
}
.discovery-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: var(--ds-radius-tag);
  background: transparent;
  color: var(--text-muted);
  font: inherit;
  font-size: var(--font-sm);
  letter-spacing: 0.08em;
  cursor: pointer;
}
.discovery-icon-btn:hover,
.discovery-icon-btn[aria-pressed="true"] {
  color: var(--text);
}
.discovery-row-more {
  position: relative;
}
.discovery-row-menu {
  position: absolute;
  z-index: 20;
  top: calc(100% + 4px);
  right: 0;
  min-width: 7.5rem;
  padding: var(--space-1);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg);
  box-shadow: var(--shadow-quiet);
}
.discovery-row-menu-item {
  display: block;
  width: 100%;
  border: 0;
  background: transparent;
  color: var(--text);
  font: inherit;
  font-size: var(--font-sm);
  text-align: left;
  padding: var(--space-2);
  border-radius: var(--radius-sm);
  cursor: pointer;
}
.discovery-row-menu-item:hover:not(:disabled) {
  background: var(--bg-elevated);
}
.discovery-follow-quiet {
  display: inline-flex;
  align-items: center;
  height: 32px;
  margin: 0;
  padding: 0 var(--space-2);
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-muted);
  font: inherit;
  font-size: var(--font-sm);
  line-height: 1;
  cursor: pointer;
}
.discovery-candidate:hover .discovery-follow-quiet,
.discovery-candidate:focus-within .discovery-follow-quiet,
.discovery-follow-quiet:hover:not(:disabled),
.discovery-follow-quiet:focus-visible {
  color: var(--text);
}
.discovery-follow-quiet:disabled {
  opacity: 0.45;
  cursor: default;
}
@media (min-width: 900px) {
  .discovery-candidate {
    grid-template-columns: auto minmax(0, 1fr) auto;
    align-items: center;
  }
  .discovery-candidate-actions {
    grid-column: auto;
    justify-self: end;
    align-self: center;
    justify-content: flex-end;
  }
  .discovery-candidate-select {
    align-self: center;
    margin-top: 0;
  }
}
.discovery-candidate[data-discovery-preview="out"] {
  opacity: 0.55;
}
.discovery-candidate-select {
  display: inline-flex;
  align-items: flex-start;
  gap: var(--space-2);
  min-width: 1.25rem;
  margin-top: 0.2rem;
  color: var(--text);
  font-size: var(--font-ui);
}
.discovery-candidate-select input {
  width: 1rem;
  height: 1rem;
  margin: 0.15rem 0 0;
}
.discovery-run-bar,
.discovery-batch-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) 0;
  border-bottom: 1px solid var(--border);
  list-style: none;
  background: var(--bg);
}
.discovery-run-bar.is-selecting,
.discovery-batch-bar.is-selecting {
  position: sticky;
  top: 0;
  z-index: 3;
}
.discovery-batch-select,
.discovery-batch-conditions,
.discovery-batch-plan {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2);
}
.discovery-threshold {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  color: var(--text);
  font-size: var(--font-ui);
}
.discovery-threshold input {
  width: 5.5rem;
  min-height: 2rem;
  padding: 0.25rem 0.4rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg);
  color: var(--text);
  font-size: var(--font-ui);
}
.discovery-batch-plan .discovery-chip {
  pointer-events: none;
  cursor: default;
}
.discovery-plan strong,
.discovery-candidate strong {
  font-size: var(--font-section);
  font-weight: 600;
}
.discovery-plan p,
.discovery-candidate p,
.discovery-quiet {
  margin: 0;
  color: var(--text-muted);
  font-size: var(--font-ui);
  line-height: 1.5;
  overflow-wrap: anywhere;
}
.discovery-candidate-reason {
  margin-top: var(--space-1);
  color: var(--text);
}
.discovery-candidate-meta {
  margin-top: var(--space-1);
  color: var(--text-muted);
  font-size: var(--font-sm);
  line-height: 1.4;
}
.discovery-error-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: var(--space-2);
  margin-top: var(--space-3);
}
.discovery-error-detail,
.task-empty.discovery-error .discovery-error-debug {
  margin: 0 auto var(--space-3);
  max-width: 36rem;
  text-align: left;
  color: var(--text-muted);
  font-size: var(--font-sm);
  line-height: 1.5;
}
.discovery-error-detail summary {
  cursor: pointer;
  color: var(--text);
  font-size: var(--font-sm);
}
.discovery-error-detail pre,
.discovery-error-debug {
  margin: var(--space-2) 0 0;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  font-size: var(--font-sm);
  color: var(--text-muted);
}
.discovery-plan ol {
  margin: 0;
  padding-left: 1.2em;
  color: var(--text);
  font-size: var(--font-sm);
  line-height: var(--leading-tight);
}
.discovery-candidate-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0;
  min-width: 0;
}
.discovery-confirm-layer {
  position: fixed;
  inset: 0;
  z-index: 80;
  display: grid;
  place-items: center;
  padding: var(--space-5);
}
.discovery-confirm-backdrop {
  position: absolute;
  inset: 0;
  background: color-mix(in srgb, var(--text) 28%, transparent);
}
.discovery-confirm {
  position: relative;
  width: min(var(--dialog-w-sm), 100%);
  display: grid;
  gap: var(--space-3);
  padding: var(--dialog-pad-compact-y) var(--dialog-pad-compact-x);
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-quiet);
}
.discovery-confirm-head {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}
.discovery-confirm-title {
  font-size: var(--ds-font-section);
  line-height: var(--ds-line-section);
  font-weight: var(--ds-weight-section);
}
.discovery-confirm-risk {
  display: inline-flex;
  align-items: center;
  height: 20px;
  padding-inline: var(--space-1);
  border: 1px solid var(--border);
  border-radius: var(--radius-control);
  color: var(--text-quiet);
  font-size: var(--ds-font-helper);
  line-height: var(--ds-line-helper);
  font-weight: 500;
}
.discovery-confirm-rows {
  display: grid;
  margin: 0;
}
.discovery-confirm-row {
  display: grid;
  grid-template-columns: 52px 1fr;
  gap: var(--space-2);
  padding-block: var(--space-1);
  font-size: var(--ds-font-sm);
  line-height: var(--ds-line-sm);
}
.discovery-confirm-row + .discovery-confirm-row {
  border-top: 1px solid var(--border);
}
.discovery-confirm-row dt {
  color: var(--text-quiet);
  white-space: nowrap;
}
.discovery-confirm-row dd {
  margin: 0;
  color: var(--text);
  overflow-wrap: anywhere;
}
.discovery-confirm-row dd code {
  font-size: var(--ds-font-helper);
  color: var(--text-quiet);
}
.discovery-confirm-error {
  margin: 0;
  color: var(--danger);
  font-size: var(--ds-font-sm);
  line-height: var(--ds-line-sm);
}
.discovery-confirm-actions {
  display: flex;
  justify-content: flex-end;
  gap: var(--space-2);
}
.discovery-confirm [data-discovery-follow-error] {
  color: var(--danger);
}
/* 紧凑检索区：标题 / 平台 / 条件合并为一块，左沿与状态卡、工具栏、候选列表一致（无卡片内边距）。 */
.ai-discovery-card {
  display: flex;
  flex-direction: column;
  gap: var(--ds-section-gap);
  margin: 0 0 var(--ds-section-gap);
  padding: 0;
  border: 0;
  background: transparent;
}
/* 选择器带上 `.ai-discovery-card` 是为了压过全局桌面密度规则
   `.home-pane h2 { font-size: var(--ds-font-ui); font-weight: 500 }`（同权重、在它之后）。 */
/* 标题与说明同排一行：块标题走 ui 档（DESIGN §字号阶梯用途，≥20px/600 的 hero 卡头废止），
   说明降 helper 档，只作补充语义。 */
.ai-discovery-card .ai-discovery-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: var(--ds-space-2) var(--ds-space-3);
}
.ai-discovery-card .ai-discovery-head h2 {
  margin: 0;
  font-size: var(--ds-font-ui);
  line-height: var(--ds-line-ui);
  font-weight: 600;
  color: var(--text);
}
.ai-discovery-card .ai-discovery-head p {
  margin: 0;
  font-size: var(--ds-font-helper);
  line-height: var(--ds-line-helper);
  color: var(--ds-text-dim);
}
/* 分区 = 一级信息；只有分区之间有线，分区内部靠间距（视觉规范 §10）。 */
.ai-discovery-section { display: flex; flex-direction: column; gap: var(--ds-space-5); }
.ai-discovery-section + .ai-discovery-section {
  padding-top: var(--ds-section-gap);
  border-top: 1px solid var(--ds-border);
}
.ai-discovery-section h3 {
  margin: 0;
  font-size: var(--ds-font-section);
  line-height: var(--ds-line-section);
  font-weight: var(--ds-weight-section);
  color: var(--text);
}
.ai-discovery-rows { display: grid; gap: var(--ds-row-gap); min-width: 0; }
/* 内容效果：两项并排，各自仍复用同一个 Label 列宽。 */
.ai-discovery-rows.is-pair { grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: var(--ds-space-8); }
/* 固定 Label 纵轴：平台/地区/方向/关键词/粉丝数/近10条均播/期望人数的控件都从同一条 X 起。 */
.ai-discovery-row {
  display: grid;
  grid-template-columns: var(--ds-label-w) minmax(0, 1fr);
  align-items: center;
  column-gap: var(--ds-space-5);
  min-width: 0;
}
.ai-discovery-label {
  font-size: var(--ds-font-label);
  line-height: var(--ds-line-label);
  font-weight: var(--ds-weight-label);
  color: var(--ds-text-dim);
}
.ai-discovery-param-value { display: grid; gap: var(--ds-space-2); min-width: 0; }
.ai-discovery-param-value > .ai-discovery-input { min-width: 0; width: 100%; }
.skill-param-readonly { min-width: 0; overflow-wrap: anywhere; color: var(--ds-text-strong); font-size: var(--ds-font-body); }
.skill-param-reason { color: var(--ds-text-muted); font-size: var(--ds-font-helper); line-height: var(--ds-line-helper); }
.skill-param-error { color: var(--danger); font-size: var(--ds-font-helper); line-height: var(--ds-line-helper); }
.ai-discovery-param-value [aria-invalid="true"] { border-color: var(--danger); }
.result-rail { min-width: 0; overflow-wrap: anywhere; }
.result-rail-context {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--ds-space-1) var(--ds-space-3);
  margin: 0 0 var(--ds-space-2);
  color: var(--ds-text-muted);
  font-size: var(--ds-font-helper);
}
.result-rail-memory,
.result-rail-history,
.result-rail-suggestions,
.result-rail-actions { min-width: 0; margin-block: var(--ds-space-2); }
.next-action-bar { display: grid; gap: var(--ds-space-2); min-width: 0; }
.next-action-recommendation,
.next-action-registered {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--ds-space-2) var(--ds-space-3);
  min-width: 0;
  padding-block: var(--ds-space-2);
  border-bottom: 1px solid var(--ds-border);
  font-size: var(--ds-font-sm);
}
.next-action-recommendation > div { flex: 1 1 12rem; min-width: 0; }
.next-action-recommendation p,
.next-action-registered span { margin: var(--ds-space-1) 0 0; color: var(--ds-text-muted); font-size: var(--ds-font-helper); }
.result-fallback-list,
.result-fallback-fields { margin: 0; padding-left: var(--ds-space-4); overflow-wrap: anywhere; }
.result-fallback-fields > div { display: grid; grid-template-columns: minmax(5rem, 0.35fr) minmax(0, 1fr); gap: var(--ds-space-2); }
.result-fallback-fields dt { color: var(--ds-text-muted); }
.result-fallback-fields dd { margin: 0; min-width: 0; }
.ai-discovery-chips { display: flex; flex-wrap: wrap; gap: var(--ds-chip-gap); align-items: center; }
.ai-discovery-inline { display: flex; align-items: center; gap: var(--ds-space-3); min-width: 0; }
.ai-discovery-dash, .ai-discovery-op { color: var(--ds-text-dim); }
.ai-discovery-card .discovery-direction-limit {
  flex: 1 1 100%;
  font-size: var(--ds-font-helper);
  line-height: var(--ds-line-helper);
  color: var(--ds-text-dim);
}
/* Filter chip：默认「浅底 + 几近无描边」，靠底色与间距分组；描边只出现在选中态。 */
.ai-discovery-card .discovery-chip {
  display: inline-flex;
  align-items: center;
  gap: var(--ds-space-2);
  height: var(--ds-chip-h);
  min-height: var(--ds-chip-h);
  padding: 0 var(--ds-space-4);
  border: 1px solid transparent;
  border-radius: var(--ds-radius-chip);
  background: var(--ds-surface);
  color: var(--text);
  font-size: var(--ds-font-body);
  line-height: var(--ds-line-body);
}
.ai-discovery-card .discovery-chip:hover { background: var(--ds-surface-hover); }
/* 选中态：底色 10% 品牌色 / 描边 35% / 文字 100%，三处不同权重，不再全是饱和红（§5）。 */
.ai-discovery-card .discovery-chip[aria-pressed="true"] {
  background: var(--ds-selected-bg);
  border-color: var(--ds-selected-border);
  color: var(--accent-text);
}
.ai-discovery-card .discovery-chip:disabled { opacity: .45; cursor: not-allowed; }
.ai-discovery-card .discovery-chip:focus-visible {
  outline: 2px solid var(--ds-selected-border);
  outline-offset: 1px;
}
.discovery-platform-ico { width: 16px; height: 16px; flex: 0 0 16px; }
/* Field System：所有输入框同高、同圆角、同描边、同字号（§8/§9）。 */
.ai-discovery-card .ai-discovery-input {
  width: 100%;
  min-width: 0;
  height: var(--ds-control-h);
  padding: 0 var(--ds-space-3);
  border: 1px solid var(--ds-border);
  border-radius: var(--ds-radius-input);
  background: var(--bg);
  font-size: var(--ds-font-body);
  line-height: var(--ds-line-body);
  color: var(--text);
}
.ai-discovery-card .ai-discovery-input:focus-visible {
  outline: none;
  border-color: var(--ds-selected-border);
  box-shadow: 0 0 0 3px var(--ds-selected-bg);
}
.ai-discovery-card .ai-discovery-input.is-number {
  flex: 0 0 var(--ds-control-w);
  width: var(--ds-control-w);
}
.ai-discovery-card textarea.ai-discovery-input {
  height: auto;
  min-height: calc(var(--ds-control-h) * 3);
  padding-block: var(--ds-space-2);
  resize: vertical;
}
/* 候选行里的平台/在库是「状态 Tag」：满圆角，与 Filter chip 区分开（§3 圆角层级）。 */

/* Crawl status / Completed：单行状态卡。左沿与检索区/工具栏/列表一致（只留纵向内边距）。 */
.discovery-status-card {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--ds-space-2) var(--ds-space-5);
  margin: 0 0 var(--ds-space-4);
  padding: var(--ds-space-3) 0;
  border-top: 1px solid var(--ds-border);
  border-bottom: 1px solid var(--ds-border);
}
.discovery-status-state {
  display: inline-flex;
  align-items: center;
  gap: var(--ds-space-2);
  font-size: var(--ds-font-body);
  line-height: var(--ds-line-body);
  color: var(--ds-text-dim);
}
.discovery-status-dot {
  flex: 0 0 8px;
  width: 8px;
  height: 8px;
  border-radius: var(--radius-full);
  background: var(--color-smoke);
}
/* 成功态：绿点 + 绿字 + 状态文案三者并存。 */
.discovery-status-card.is-ok .discovery-status-state { color: var(--color-success-vivid); }
.discovery-status-card.is-ok .discovery-status-dot { background: var(--color-success-vivid); }
.discovery-status-rows { display: flex; flex-wrap: wrap; gap: var(--ds-space-2) var(--ds-space-5); margin: 0; }
.discovery-status-row { display: flex; align-items: baseline; gap: var(--ds-space-2); }
.discovery-status-row dt { font-size: var(--ds-font-helper); line-height: var(--ds-line-helper); color: var(--ds-text-dim); }
.discovery-status-row dd { margin: 0; font-size: var(--ds-font-body); color: var(--text); }
@media (max-width: 720px) {
  .recommend-md-row {
    grid-template-columns: minmax(0, 1fr);
  }
}
.todo-md { margin: 8px 0 0; width: 100%; max-width: none; min-width: 0; }
.todo-md-empty {
  color: var(--text-muted);
  font-size: var(--font-xs);
  width: 100%;
  max-width: none;
}
.todo-card-act {
  display: grid;
  grid-template-columns: 1.6em minmax(0, 1fr);
  gap: var(--space-2);
  align-items: start;
  width: 100%;
  max-width: none;
  border: 0;
  background: transparent;
  text-align: left;
  font: inherit;
  color: var(--text);
  padding: var(--space-2) var(--space-2) var(--space-2) 0;
  border-radius: var(--radius-sm);
  cursor: pointer;
  overflow: hidden;
}
.todo-card-act:hover { background: var(--bg-elevated); }
.todo-card-mark {
  color: var(--text-muted);
  font-size: var(--font-sm);
  line-height: var(--leading-body);
}
.todo-card-copy {
  display: grid;
  gap: 4px;
  min-width: 0;
  max-width: none;
  width: 100%;
  text-align: left;
  justify-items: start;
  overflow-x: hidden;
}
.todo-card-main {
  display: grid;
  gap: 4px;
  min-width: 0;
  width: 100%;
}
.todo-card-copy strong {
  display: block;
  max-width: 100%;
  color: var(--text);
  font-size: var(--font-section);
  font-weight: 600;
  line-height: 1.35;
  overflow-wrap: anywhere;
  word-break: break-word;
  white-space: normal;
}
.todo-card-kicker,
.todo-card-status,
.todo-card-progress,
.todo-card-why {
  margin: 0;
  max-width: 100%;
  color: color-mix(in srgb, var(--text) 78%, var(--text-muted));
  font-size: var(--font-ui);
  line-height: 1.5;
  overflow-wrap: anywhere;
  word-break: break-word;
  white-space: normal;
}
.todo-card-kicker { color: color-mix(in srgb, var(--text) 88%, var(--text-muted)); }
.todo-card-status { color: color-mix(in srgb, var(--text) 82%, var(--text-muted)); }
@media (min-width: 900px) {
  .todo-card-act {
    align-items: center;
  }
  .todo-card-copy {
    grid-template-columns: minmax(0, 1fr) auto;
    column-gap: var(--space-4);
    align-items: start;
  }
  .todo-card-main {
    grid-column: 1;
  }
  .todo-card-status {
    grid-column: 2;
    grid-row: 1;
    justify-self: end;
    align-self: center;
    text-align: right;
    white-space: nowrap;
  }
  .todo-card-progress,
  .todo-card-why {
    grid-column: 1;
  }
}
.insight-confirm { margin: 16px 0 0; }
.home-fold-more {
  display: inline-flex;
  align-items: center;
  margin: 4px 0 8px;
  border: 0;
  background: none;
  color: var(--muted);
  font: inherit;
  font-size: var(--font-xs);
  line-height: 1.4;
  cursor: pointer;
  padding: 6px 0;
}
.home-fold-more:hover { color: var(--accent-text); }
.todo-card-list,
.insight-card-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0;
}
.todo-card,
.insight-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: var(--space-2) var(--space-3);
  align-items: center;
  padding: var(--space-3) var(--space-1);
  border-bottom: 1px solid var(--border);
  min-width: 0;
  overflow: hidden;
}
.todo-card-body,
.insight-card-body {
  min-width: 0;
}
.todo-card-head,
.todo-card-meta,
.insight-card-meta {
  display: flex;
  flex-wrap: nowrap;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
  color: var(--muted);
  font-size: var(--font-xs);
}
.todo-card-head strong,
.todo-card-body strong,
.insight-card-body strong {
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--font-section);
  font-weight: 600;
  line-height: 1.35;
  color: var(--text);
}
.todo-urgency {
  flex: 0 0 auto;
  font-weight: 500;
  font-size: var(--font-meta);
  line-height: 1.2;
  padding: 1px 7px;
  border-radius: var(--ds-radius-tag);
  background: var(--chrome);
  white-space: nowrap;
}
.todo-card-head time { flex: 0 0 auto; white-space: nowrap; }
.todo-urgency.is-overdue { color: var(--red); background: #fdecec; }
.todo-urgency.is-today { color: #b45309; background: #fff4e5; }
.todo-urgency.is-waiting { color: #8a6d3b; }
.todo-handle,
.todo-reason,
.todo-next {
  margin: var(--space-1) 0 0;
  color: var(--text-muted);
  font-size: var(--font-ui);
