}
.today-summary h2,
.recommend-work h2 {
  margin: 8px 0 0;
  font-size: var(--font-section);
  font-weight: 600;
  color: var(--text);
  white-space: nowrap;
}
.today-summary-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  column-gap: 36px;
  row-gap: 6px;
  margin: 0 0 14px;
  min-width: 0;
}
.today-summary-head h2 {
  margin: 0;
  line-height: 1.3;
}
.today-summary-head .home-work-links {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 20px 28px;
  margin: 0;
  padding-top: 1px;
}
.home-work-links .work-panel-open {
  display: inline;
  margin: 0;
  padding: 0;
  text-decoration: none;
  font-size: var(--font-ui);
