}
.today-summary .task-filters { margin-bottom: 18px; }
.followed-object-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2);
  margin: 0 0 var(--space-1);
  width: 100%;
  max-width: 100%;
  min-width: 0;
}
/* 两段式：左边「找谁」（搜索 + 阶段筛选），右边「对选中的做什么」。
   2026-09-22 评审前这里是一条平铺的 flex，计数的「1 人」与筛选控件的
   「阶段（高级）」只隔 8px，被读成「1 人 阶段（高级）」一个短语。 */
.followed-object-look {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  gap: var(--space-2);
  /* flex-basis auto 会让本组按 max-content（搜索框的内在宽度）定宽，
     于是「阶段筛选」被挤到第二行、整条工具栏长到 80px。改成吃满剩余空间。 */
  flex: 1 1 auto;
  min-width: 0;
}
.followed-object-batch {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2);
  margin-left: auto;
  min-width: 0;
}
.followed-advanced-label {
  color: var(--text-muted);
  font-size: var(--font-sm);
  white-space: nowrap;
}
.followed-select-all {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--text-muted);
  font-size: var(--font-sm);
  white-space: nowrap;
  cursor: pointer;
}
.followed-select-all input:disabled { cursor: default; }
.followed-select-all:has(input:disabled) { cursor: default; }
.followed-object-search {
  display: block;
  flex: 0 1 22rem;
  min-width: min(12rem, 100%);
  max-width: 22rem;
}
.followed-object-search input {
  display: block;
  width: 100%;
  min-height: 36px;
  border: 1px solid var(--border);
  border-radius: var(--radius-inputs);
  background: var(--bg);
  color: var(--text);
  font: inherit;
  font-size: var(--ds-font-body);
  line-height: var(--leading-tight);
  padding: 6px 10px;
  box-sizing: border-box;
}
.followed-object-search input:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}
.followed-object-count {
  margin: 0;
  color: var(--text-muted);
  font-size: var(--font-sm);
  white-space: nowrap;
}
.followed-advanced-filter {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--text-muted);
  font-size: var(--font-sm);
}
.followed-advanced-filter select {
  min-height: 36px;
  border: 1px solid var(--border);
  border-radius: var(--radius-inputs);
  background: var(--bg);
  color: var(--text);
  font: inherit;
  font-size: var(--font-sm);
  padding: 4px 8px;
}
.followed-stage-filter {
  display: flex;
  flex: 1 1 100%;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
  min-width: 0;
  overflow-x: hidden;
  padding: 2px 0 4px;
}
.followed-stage-filter button {
  display: inline-flex;
  flex: 1 1 0;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 32px;
  min-width: 0;
  padding: 5px 8px;
  border: 1px solid transparent;
  border-radius: var(--ds-radius-tag);
  background: transparent;
  color: var(--text-muted);
  font: inherit;
  font-size: var(--font-sm);
  line-height: 1.2;
  cursor: pointer;
  white-space: nowrap;
}
.followed-stage-filter button > span:first-child {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.followed-stage-filter button:hover {
  background: color-mix(in srgb, var(--text) 4%, var(--bg));
  color: var(--text);
}
.followed-stage-filter button.is-active {
  border-color: var(--border-strong);
  background: var(--bg);
  color: var(--text);
  font-weight: 500;
}
.followed-stage-count {
  min-width: 1.25em;
  color: var(--text-muted);
  font-size: var(--font-xs);
  font-variant-numeric: tabular-nums;
  text-align: center;
}
.followed-stage-filter button.is-active .followed-stage-count {
  color: var(--text);
}
.followed-stage-select-compat {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  border: 0;
  opacity: 0;
  pointer-events: none;
  overflow: hidden;
}
.followed-batch-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--spacing-8);
  width: 100%;
  max-width: 100%;
  min-width: 0;
  padding: var(--spacing-8) 0;
  border-bottom: 1px solid var(--border);
  background: var(--bg);
}
.followed-batch-bar.is-selecting {
  position: sticky;
  top: 0;
  z-index: 3;
}
.followed-batch-select {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--spacing-8);
}
.followed-batch-select .followed-kol-select {
  margin-top: 0;
  align-items: center;
  gap: var(--spacing-8);
  color: var(--text);
  font-size: var(--font-sm);
}
.followed-batch-cta {
  border-radius: var(--radius-buttons);
}
.followed-kol-select {
  display: inline-flex;
  align-items: flex-start;
  flex: 0 0 auto;
  margin-top: 4px;
}
.followed-kol-select input {
  width: 1rem;
  height: 1rem;
  margin: 0;
  accent-color: var(--accent);
}
.followed-batch-confirm-list {
  margin: var(--spacing-8) 0 0;
  padding-left: 1.2rem;
  color: var(--text);
  font-size: var(--font-body);
  line-height: var(--leading-body);
}
.kol-secondary-filters {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2);
  margin: 0 0 var(--space-2);
  min-width: 0;
}
.kol-filter-label {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  color: var(--text-muted);
  font-size: var(--font-sm);
}
.kol-filter-label select {
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-muted);
  font: inherit;
  font-size: var(--font-sm);
  padding: 6px 8px;
  max-width: 10rem;
  min-height: 36px;
}
.kol-filter-label select:hover,
.kol-filter-label select:focus-visible {
  border-color: var(--border);
  background: var(--bg);
  color: var(--text);
}
.kol-sorts {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
}
.kol-sorts button {
  border: 1px solid var(--border);
  border-radius: var(--ds-radius-tag);
  background: var(--bg);
  color: var(--text-muted);
  font: inherit;
  font-size: var(--font-sm);
  padding: 6px var(--space-2);
  cursor: pointer;
  min-height: 36px;
}
.kol-sorts button[aria-pressed="true"] {
  color: var(--accent-text);
  border-color: var(--accent);
}
.profile-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 4px;
}
.profile-tag {
  border: 1px solid var(--border);
  background: var(--bg-elevated);
  color: var(--text-muted);
  border-radius: var(--ds-radius-tag);
  font-size: var(--font-sm);
  padding: 1px 7px;
  line-height: 1.6;
}
.follow-style-tags {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 4px;
  align-items: center;
}
.follow-style-tag {
  border: 1px solid var(--border);
  background: var(--bg-elevated);
  color: var(--text);
  border-radius: var(--ds-radius-tag);
  font-size: var(--font-sm);
  padding: 1px 8px;
  line-height: 1.6;
}
.follow-style-bar {
  position: relative;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  margin: 8px 0 2px;
}
.follow-style-add {
  border: 1px dashed var(--border-strong);
  background: transparent;
  color: var(--text-muted);
  border-radius: var(--ds-radius-tag);
  font-size: var(--font-sm);
  padding: 1px 8px;
  cursor: pointer;
}
.follow-style-panel {
  position: absolute;
  z-index: 8;
  top: calc(100% + 6px);
  left: 0;
  width: min(360px, 100%);
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg);
  box-shadow: var(--shadow-quiet);
}
.follow-style-presets {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 8px 0;
}
.follow-style-chip {
  border: 1px solid var(--border);
  background: var(--bg);
  color: var(--text);
  border-radius: var(--ds-radius-tag);
  font-size: var(--font-sm);
  padding: 3px 10px;
  cursor: pointer;
}
.follow-style-chip.is-on {
  background: color-mix(in srgb, var(--accent) 10%, var(--bg));
  border-color: var(--accent);
  color: var(--accent-text);
}
.follow-style-custom {
  display: grid;
  grid-template-columns: 4em minmax(0, 1fr);
  gap: 8px;
  align-items: center;
  font-size: var(--font-sm);
  color: var(--text-muted);
}
.follow-style-custom input {
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 6px 8px;
}
.follow-style-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 10px;
}
.suggested-follow-tags {
  margin-top: 12px;
}
.suggested-follow-tags ul {
  list-style: none;
  margin: 8px 0 0;
  padding: 0;
  display: grid;
  gap: 8px;
}
.suggested-follow-tags li {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  align-items: center;
  font-size: var(--font-sm);
}
.task-history {
  display: block;
  margin-top: 3px;
  color: var(--ds-text-dim);
  font-size: var(--font-xs);
  line-height: 1.4;
}
.kol-card-fields {
  display: grid;
  gap: var(--space-1);
  margin-top: var(--space-2);
  min-width: 0;
  max-width: 100%;
}
.kol-card-field {
  display: grid;
  grid-template-columns: 7.2em minmax(0, 1fr);
  gap: var(--space-2);
  font-size: var(--font-meta);
  line-height: 1.45;
  min-width: 0;
}
.kol-card-field dt {
  color: var(--text-muted);
  font-weight: 500;
}
.kol-card-field dd {
  margin: 0;
  color: var(--text);
  min-width: 0;
  overflow-wrap: anywhere;
}
.kol-card-fields.is-compact {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-2) var(--space-3);
  margin-top: var(--space-2);
  width: 100%;
  max-width: 100%;
  min-width: 0;
}
.followed-kol .kol-card-fields.is-compact > .kol-card-field,
.kol-card-fields.is-compact .kol-card-field {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 2px;
  min-width: 0;
  grid-template-columns: none;
}
.kol-card-status-line {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2) var(--space-4);
  min-width: 0;
}
.kol-card-status-line .kol-card-field {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  flex: 1 1 8rem;
  gap: 2px;
  min-width: 0;
  font-size: var(--font-meta);
  line-height: 1.4;
}
.kol-card-status-line .kol-card-field + .kol-card-field::before {
  content: none;
}
.kol-card-fields.is-compact dt,
.kol-card-status-line dt {
  flex: none;
  font-size: var(--font-xs);
}
.kol-card-fields.is-compact dd,
.kol-card-status-line dd {
  min-width: 0;
  max-width: 100%;
  width: 100%;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  overflow-wrap: anywhere;
  word-break: break-word;
  white-space: normal;
  line-height: 1.4;
}
.followed-kol.is-exception .task-source-mark,
.followed-kol-item.is-exception .kol-chip.is-risk { color: var(--danger); }
.unread-badge, .unread-total, .kol-chip.is-unread {
  display: inline-flex;
  align-items: center;
  margin-left: 0;
  padding: 1px var(--space-2);
  border-radius: var(--ds-radius-tag);
  background: color-mix(in srgb, var(--danger) 12%, var(--bg));
  color: var(--danger);
  font-size: var(--font-meta);
  font-weight: 600;
  white-space: nowrap;
}
.home-mode-pane h2 .btn { margin-left: 10px; vertical-align: middle; }
.kol-card-body {
  min-width: 0;
  display: grid;
  gap: 8px;
}
.kol-mail-preview {
  display: grid;
  gap: var(--space-1);
  margin: 0;
  padding: var(--space-2) 0 0;
  border-top: 1px solid var(--border);
  min-width: 0;
}
.kol-mail-preview .mail-preview-meta {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1) var(--space-2);
  margin: 0;
  font-size: var(--font-meta);
  color: var(--text-muted);
  min-width: 0;
}
.kol-mail-preview .thread-subject {
  color: var(--text);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
}
.kol-mail-preview .mail-preview-text {
  margin: 0;
  font-size: var(--font-meta);
  line-height: 1.45;
  color: var(--text-muted);
  min-width: 0;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.mail-preview-link,
.kol-mail-preview [data-open-original-mail] {
  justify-self: start;
  border: 0;
  background: none;
  padding: 0;
  color: var(--text-muted);
  font: inherit;
  font-size: var(--font-meta);
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 2px;
}
.mail-preview-link:hover,
.kol-mail-preview [data-open-original-mail]:hover {
  color: var(--accent-text);
}
.kol-card-cta {
  justify-self: start;
  white-space: nowrap;
}
@media (max-width: 720px) {
  .recommend-row.followed-kol {
    grid-template-columns: 28px minmax(0, 1fr);
  }
  .recommend-row.followed-kol .kol-card-cta {
    grid-column: 2;
  }
}
.recommend-work { padding-top: 0; border-top: 0; width: 100%; max-width: 100%; }
.followed-kol-pane,
.home-mode-pane[data-home-pane="lifecycle"] {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  align-self: stretch;
}
/*
 * Followed decision column: full available rail width.
 * OpenAI-quiet readable workbench (content-first, not stretched ERP rows).
 * Keep the card content-first: full-width natural paragraphs with a quiet
 * divider between the latest interaction and recommendation. Density dial 8.
 */
.followed-kol-column {
  --followed-decision-max: 100%;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  justify-items: start;
  align-items: stretch;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  overflow-x: hidden;
  margin-inline: auto;
  /* 清单末尾与提问框页脚之间留一口气：滚动到底时最后一张卡不贴住发丝线。 */
  padding-bottom: var(--space-3);
}
.followed-kol-column .home-pane-sticky,
.followed-kol-column .followed-brief,
.followed-kol-column .followed-kol-list,
.followed-kol-column .task-empty {
  width: 100%;
  max-width: var(--followed-decision-max);
  min-width: 0;
  box-sizing: border-box;
}
.followed-kol-column .followed-object-toolbar,
.followed-kol-column .followed-batch-bar,
.followed-kol-column .followed-kol-item {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  box-sizing: border-box;
}
.followed-kol-column .home-pane-sticky {
  overflow-x: hidden;
  padding: 0 0 var(--space-1);
}
.followed-kol-list {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  justify-items: stretch;
  gap: var(--space-3);
  min-width: 0;
  width: 100%;
  overflow-x: hidden;
}
.followed-kol-item {
  min-width: 0;
  width: 100%;
  max-width: 100%;
  list-style: none;
  overflow-x: hidden;
}
/* 风险不再染整条左边界：那个形状与「选中」同构，且只靠颜色。
   状态色改为紧贴文案的局部标记（DESIGN.md §不变量 4）。 */
.kol-band {
  min-width: 0;
  max-width: 100%;
  width: 100%;
  box-sizing: border-box;
}
.kol-band-identity {
  display: flex;
  flex-direction: row;
  flex-wrap: nowrap;
  align-items: flex-start;
  gap: var(--space-2);
}
/* 头像 = 图标砖：小圆角方形，淡辅助底 + 辅助字形（DESIGN.md §颜色「图标砖与图标字形」）。 */
/* 身份块两行：第一行身份、第二行元信息（普通属性 + 14 日计时同一条弱化行）。 */
.kol-identity-main {
  min-width: 0;
  flex: 1 1 auto;
  width: 100%;
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0 6px;
}
.kol-identity-main > .kol-identity-line { flex: 1 1 100%; }
.kol-identity-main > .kol-chip-row { flex: 1 1 auto; width: auto; }
.kol-identity-main > .kol-mail-meta { flex: 0 0 auto; }
/* 第一行与头像同高：勾选框、头像与姓名在同一行内垂直居中。 */
.kol-identity-line {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  column-gap: var(--space-2);
  row-gap: 2px;
  min-width: 0;
  min-height: var(--kol-avatar-size);
  width: 100%;
}
/* 列表行内容：一级只用 --ds-font-body（DESIGN.md §字号阶梯用途），不再借分区标题档。 */
.kol-band-identity .kol-name,
.kol-band-identity strong {
  display: inline;
  flex: 0 1 auto;
  max-width: 100%;
  min-width: 0;
  font-size: var(--ds-font-body);
  font-weight: 600;
  line-height: var(--leading-tight);
  color: var(--text);
  white-space: normal;
  overflow-wrap: anywhere;
  word-break: break-word;
}
/* 行内图标只取 --icon-sm 一档，不撑高、不折行。 */
/* 阶段标签：短标签 + 淡辅助底 + 细描边，与行内其它标记同档高（--badge-h）。 */
.kol-stage-badge {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  max-width: 100%;
  height: var(--badge-h);
  padding: 0 6px;
  border: 1px solid color-mix(in srgb, var(--accent) 26%, var(--border));
  border-radius: var(--ds-radius-tag);
  background: color-mix(in srgb, var(--accent) 8%, var(--bg));
  color: var(--accent-text);
  line-height: var(--lh-control-sm);
}
.kol-stage-badge .kol-stage,
.kol-stage-badge [data-stage-label] {
  margin: 0;
  font-size: var(--ds-font-sm);
  font-weight: 500;
  line-height: var(--lh-control-sm);
  color: var(--accent-text);
}
/* 时间压力固定在右上角，表格数字对齐。 */
.kol-stage-stay {
  margin-left: auto;
  color: var(--text-muted);
  font-size: var(--ds-font-sm);
  line-height: 1.35;
  font-variant-numeric: tabular-nums;
}
/* 普通属性不做标签：无底色无描边，只用中点分隔。 */
.kol-chip-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0 6px;
  margin-top: 0;
  min-width: 0;
  width: 100%;
  overflow-wrap: anywhere;
}
.kol-chip {
  display: inline-flex;
  align-items: center;
  border: 1px solid transparent;
  background: transparent;
  color: var(--text-muted);
  border-radius: var(--ds-radius-tag);
  font-size: var(--ds-font-sm);
  line-height: 1.3;
  padding: 0;
  max-width: 100%;
  min-width: 0;
  white-space: normal;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.kol-chip-row > .kol-chip + .kol-chip::before {
  content: "·";
  margin-right: 6px;
  color: var(--text-muted);
}
/* 未读是信息性标记（辅助色职责），不是风险：红色只留给异常与失败。 */
.kol-chip.is-unread {
  padding: 0;
  background: transparent;
  color: var(--accent-text);
  font-weight: 500;
}
/* 已有风险标记时未读退为弱文本 —— 每条记录最多一个状态强调点。 */
.kol-chip.is-unread.is-quiet {
  color: var(--text-muted);
  font-weight: 400;
}
/* 异常/风险：状态色描边 + 图标 + 文案，颜色不是唯一信号。
   描边取 70% 危险色 = 3.3:1（纯图形 ≥3:1），图标字形本身 5.17:1。 */
.kol-chip.is-risk {
  gap: 4px;
  height: var(--badge-h);
  padding: 0 6px;
  border-color: color-mix(in srgb, var(--danger) 70%, var(--border));
  color: var(--danger);
  background: transparent;
  font-weight: 500;
  line-height: var(--lh-control-sm);
}
.kol-chip.is-style {
  border-color: var(--border);
  background: var(--bg-elevated);
  color: var(--text);
}
.kol-state-block {
  min-width: 0;
  max-width: 100%;
  box-sizing: border-box;
}
.kol-state-fields {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: var(--space-1) var(--space-2);
  min-width: 0;
}
.kol-state-fields p {
  margin: 0;
}
.kol-band-label {
  display: none;
}
.kol-state-block p {
  margin: 0;
  min-width: 0;
  max-width: 100%;
  white-space: normal;
  overflow-wrap: anywhere;
  word-break: break-word;
}
/* 「AI 建议 · 理由」同一条弱化行：判断来自谁 + 依据，各自只占一级信息。 */
/* 一级：当前建议 —— 与姓名同档，靠字重与颜色抢注意力，不靠字号。 */
/* AI 可信度：证据不足时图标 + 弱化色，不把猜测装成结论。 */
/* 依据入口：展开态由 <details> 自己驱动，箭头是统一 SVG，不用文本字符。 */
.kol-band-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-start;
  gap: var(--space-1) var(--space-2);
  min-width: 0;
  padding-top: 2px;
}
/* 文字链接默认不加下划线：靠颜色与位置识别，hover / focus 才强化。 */
/* 行内 CTA 不是胶囊：胶囊只留给身份/状态语义（DESIGN.md §控件尺寸）。 */
/* Row CTAs stay ghost; the one filled --primary CTA lives on the bulk top bar. */
.followed-brief {
  margin: 0 0 16px;
  padding: 0;
}
.followed-brief-lead,
.followed-brief-title {
  margin: 0 0 6px;
  font-weight: 600;
}
.followed-brief-stats,
.followed-brief-meta,
.followed-brief-kicker {
  margin: 0 0 8px;
  color: var(--muted, var(--ds-text-dim));
  font-size: var(--font-sm, 13px);
}
/* 简报计数：非零的那一档才是可点的情境分区（一次回答内收窄），
   零档保持纯文本 —— 不给点不动的假按钮。选中态同时改字重与下划线，
   不只靠颜色（根 AGENTS.md §4）。 */
.followed-brief-stats {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}
.followed-brief-sep {
  color: color-mix(in srgb, var(--muted, var(--ds-text-dim)) 55%, transparent);
}
.followed-brief-stat-action {
  border: 0;
  background: none;
  padding: 0;
  font: inherit;
  color: inherit;
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 2px;
  text-decoration-thickness: 1px;
  text-decoration-color: color-mix(in srgb, currentColor 45%, transparent);
}
.followed-brief-stat-action:hover { color: var(--accent-text); }
.followed-brief-stat-action:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
  border-radius: var(--radius-control);
}
.followed-brief-stat-action[aria-pressed="true"] {
  color: var(--text);
  font-weight: 600;
  text-decoration-color: currentColor;
}
.followed-brief-stat-action.is-clear {
  margin-left: 4px;
  text-decoration: none;
}
.followed-brief-primary {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
}
/* 我的红人：连续对象清单。阶段导航、搜索与批量动作固定在列表顶部，
   每位红人只保留身份、最近互动和下一步，避免把右栏做成卡片墙。 */
.followed-journey {
  display: flex;
  align-items: flex-end;
  gap: clamp(16px, 2.4vw, 34px);
  width: 100%;
  min-width: 0;
  overflow-x: auto;
  border-bottom: 1px solid var(--border);
  scrollbar-width: none;
}
.followed-journey::-webkit-scrollbar { display: none; }
/* 图2：三行同一档字号（13px），阶段导航一行的字重比快速筛选一行重。 */
.followed-journey span {
  position: relative;
  flex: 0 0 auto;
  padding: 6px 0 9px;
  color: var(--text-muted);
  font-size: var(--font-sm);
  font-weight: 600;
  line-height: 1.35;
  white-space: nowrap;
}
.followed-journey span.is-active {
  color: var(--text);
  font-weight: 600;
}
.followed-journey span.is-active::after {
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 2px;
  border-radius: 2px 2px 0 0;
  background: var(--accent);
  content: "";
}
.followed-stage-quick-filter {
  display: flex;
  align-items: center;
  gap: clamp(16px, 2vw, 28px);
  width: 100%;
  min-width: 0;
  padding: 8px 0 2px;
  overflow-x: auto;
  border-bottom: 1px solid var(--border);
  scrollbar-width: none;
}
.followed-stage-quick-filter::-webkit-scrollbar { display: none; }
.followed-stage-quick-filter button {
  position: relative;
  flex: 0 0 auto;
  min-height: 28px;
  margin: 0;
  padding: 4px 0 8px;
  border: 0;
  border-bottom: 2px solid transparent;
  background: transparent;
  color: var(--text-muted);
  font: inherit;
  font-size: var(--font-sm);
  cursor: pointer;
  white-space: nowrap;
}
.followed-stage-quick-filter button:hover { color: var(--text); }
.followed-stage-quick-filter button.is-active {
  border-bottom-color: var(--accent);
  color: var(--text);
  font-weight: 500;
}
.followed-kol-column .followed-brief {
  display: flex;
  align-items: center;
  min-height: 34px;
  margin: 0;
  padding: 5px 0;
  border-bottom: 1px solid var(--border);
  background: transparent;
}
.followed-kol-column .followed-brief-lead,
.followed-kol-column .followed-brief-primary { display: none; }
.followed-kol-column .followed-brief-stats {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  color: var(--text-muted);
  font-size: var(--font-sm);
  line-height: 1.35;
}
.followed-kol-column .followed-brief-stat-action {
  min-height: 26px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--text-muted);
  font: inherit;
  cursor: pointer;
}
.followed-kol-column .followed-brief-stat-action:hover,
.followed-kol-column .followed-brief-stat-action[aria-pressed="true"] {
  color: var(--accent-text);
  font-weight: 600;
}
.followed-kol-column .followed-object-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2) var(--space-3);
  margin: 0;
  /* 右栏右上角是 24px 折叠按钮：工具行给它留出 gutter，控件不钻到按钮下面。 */
  padding: 12px calc(var(--icon-btn) + var(--space-2)) 12px 0;
  border-bottom: 1px solid var(--border);
}
/* 搜索框不再被批量动作挤扁：放不下时整组换行，而不是两个控件互相重叠。 */
.followed-kol-column .followed-object-look {
  flex: 1 1 22rem;
  min-width: min(12rem, 100%);
  flex-wrap: nowrap;
}
.followed-kol-column .followed-object-batch {
  flex-wrap: wrap;
  margin-left: auto;
}
/* 图3/图4：与公海同一套控件配方 —— 32px 高、可操作控件边框（--control-border 3.45:1）、
   框内左侧内联搜索图标；宽度收口到 18rem，不再横贯整栏。 */
.followed-kol-column .followed-object-search {
  position: relative;
  display: block;
  flex: 0 1 18rem;
  min-width: min(12rem, 100%);
  max-width: 18rem;
}
.followed-kol-column .followed-object-search .followed-inline-icon {
  position: absolute;
  left: 10px;
  top: 50%;
  width: var(--icon-sm);
  height: var(--icon-sm);
  transform: translateY(-50%);
  color: var(--text-muted);
  pointer-events: none;
}
.followed-kol-column .followed-object-search input {
  height: var(--control-h-lg);
  min-height: var(--control-h-lg);
  border: 1px solid var(--control-border);
  border-radius: var(--radius-control);
  background: var(--bg);
  line-height: var(--lh-control);
  padding: 0 10px 0 32px;
}
/* 工具行的按钮与同排搜索框同档（32px），文字 13px：原来是 36px，比搜索框还高。 */
.followed-kol-column .followed-object-batch .btn.sm {
  height: var(--control-h-lg);
  min-height: var(--control-h-lg);
  padding: 0 12px;
  border-radius: var(--radius-control);
  font-size: var(--ds-font-sm);
}
.followed-kol-column .followed-advanced-filter {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
}
.followed-kol-column .followed-stage-select-compat {
  width: 1px;
  min-width: 1px;
  height: 1px;
  min-height: 1px;
  padding: 0;
  border: 0;
}
.followed-kol-column .followed-object-count {
  padding-right: 2px;
  font-variant-numeric: tabular-nums;
}
.followed-kol-column .followed-object-sort {
  display: inline-flex;
  align-items: center;
  min-width: 0;
}
.followed-kol-column .followed-object-sort select {
  height: var(--control-h-lg);
  min-height: var(--control-h-lg);
  max-width: 9.5rem;
  padding: 0 26px 0 10px;
  border: 1px solid var(--control-border);
  border-radius: var(--radius-control);
  background: var(--bg);
  color: var(--text-muted);
  font: inherit;
  font-size: var(--ds-font-sm);
  cursor: pointer;
}
.followed-kol-column .followed-select-all {
  min-height: var(--control-h-lg);
  color: var(--text);
  font-size: var(--ds-font-sm);
}
.followed-kol-column .followed-select-all input {
  width: 16px;
  height: 16px;
  margin: 0;
  accent-color: var(--accent-text);
}
.followed-kol-column .followed-kol-list {
  gap: 10px;
  border-bottom: 0;
}
/* 勾选框与第一行的 28px 行框居中：(28 − 16) / 2。 */
.followed-kol-column .followed-kol-select { margin-top: 6px; }
.followed-kol-column .kol-band-identity { gap: var(--space-2); }
.followed-kol-column .kol-identity-line { column-gap: var(--space-2); }
.followed-kol-column .kol-chip-row { gap: 0 6px; }
.followed-kol-column .kol-split { gap: var(--space-2); }
.followed-kol-column .kol-band-recommend {
  gap: 6px;
}
/* 只藏事实层的 kicker：建议层的来源说明保留，用来区分保存记录与事实摘录。 */
.followed-kol-column .kol-mail-meta,
.followed-kol-column .kol-judgment { font-size: var(--ds-font-sm); }
.followed-kol-column .kol-band-actions { justify-content: space-between; }
.followed-kol-column .kol-cta-secondary { gap: 10px; }
.followed-kol-column .kol-cta-link { font-size: var(--ds-font-sm); }
/* 信息上下铺满，不做左右两栏；每层内部横向排满，行内排不下时自己换行。 */
/* 事实层：正文与邮件来源同行（来源靠右），不再各占一行。 */
/* flex-basis 取 0：否则换行判定用「内容宽度」，来源 meta 会被挤到自己一行。 */
/* 建议层：左侧建议 + 理由，右侧「依据/互动/详情 + 主 CTA」，两者垂直居中成一组。 */
/* width:auto 是关键：.kol-band 组的 width:100% 会让这组动作的 flex 基准 = 整行，
   于是永远换行、每个对象白多一行。这里必须按内容宽度参与排布。 */
/* 只有展开的判断依据才引入局部分隔线。 */
/* 卡片主 CTA 与工具行同档（32px），不再比同屏其它控件高一头。 */
/* 跟进卡片的最终密度：头像承担身份锚点，其余信息共享整行内容宽度。 */
/* 触摸模态只扩大命中区，不改视觉尺寸、不动布局边界（DESIGN.md §控件尺寸）。
   负外边距正好抵掉撑大的内边距与最小宽高，勾选框位置与静止态逐像素相同。 */
@media (pointer: coarse) {
  .followed-kol-column .followed-kol-select {
    position: relative;
    z-index: 1;
    min-width: 44px;
    min-height: 44px;
    margin: -8px -28px -12px 0;
    padding: 0;
  }
}
@media (max-width: 640px) {
  .followed-kol-column .followed-object-toolbar { grid-template-columns: minmax(0, 1fr); }
  .followed-kol-column .followed-object-batch { justify-content: flex-start; }
  .followed-kol-column .followed-select-all { margin-right: auto; }
}
@media (max-width: 1200px) {
  .followed-stage-filter {
    justify-content: flex-start;
    overflow-x: auto;
    scrollbar-width: thin;
    scrollbar-color: var(--border) transparent;
  }
  .followed-stage-filter button {
    flex: 0 0 auto;
  }
}
.recommend-list {
