  font: inherit;
  font-size: var(--font-sm);
  padding: 6px 11px;
  cursor: pointer;
  text-decoration: none;
  white-space: nowrap;
  max-width: min(100%, 28rem);
  overflow: hidden;
  text-overflow: ellipsis;
  min-height: 36px;
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
}
.task-filters button[aria-pressed="true"] {
  color: var(--accent-text);
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 8%, var(--bg));
}
.task-controls select { border-radius: 8px; cursor: default; }
.today-task-list { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--line); }
.today-task {
  display: grid;
  grid-template-columns: 26px 30px minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  min-height: 76px;
  padding: 10px 8px;
  border-bottom: 1px solid var(--border);
  min-width: 0;
  overflow-x: hidden;
}
.today-task:hover { background: var(--bg-elevated); }
.recommend-row.today-task {
  grid-template-columns: 28px minmax(0, 1fr) auto;
  border-bottom: 0;
  min-height: 64px;
}
.today-task:hover { background: var(--bg-elevated); }
.task-source-mark {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  color: var(--accent-text);
  font-size: var(--font-ui);
}
.task-ai .task-source-mark { color: var(--text); }
.status-running .task-source-mark,
.status-waiting .task-source-mark,
.status-queued .task-source-mark { color: var(--text-muted); }
.status-completed .task-source-mark,
.status-done .task-source-mark { color: var(--success); }
.status-failed .task-source-mark,
.today-task:has(.task-risk) .task-source-mark { color: var(--danger); }
.task-index { color: var(--text-muted); font: var(--font-sm) var(--mono); }
.task-main {
  display: grid;
  gap: 3px;
  min-width: 0;
  color: var(--text);
  text-decoration: none;
  border: 0;
  background: transparent;
  cursor: pointer;
  font: inherit;
  text-align: left;
  width: 100%;
}
.task-main strong { font-size: var(--font-ui); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.task-meta, .task-tail { color: var(--muted); font-size: var(--font-meta); }
.task-risk { color: var(--red); font-size: var(--font-meta); }
.task-tail { display: grid; justify-items: end; gap: 3px; white-space: nowrap; }
/* 紧凑空态（DESIGN §内容密度）：左对齐、内容字号、小内边距、动作内联；
   hero 式居中大标题空态废止。文案仍须诚实区分尚无结果/服务不可用/筛选无结果。 */
.task-empty {
  text-align: left;
  color: var(--muted);
  border: 1px dashed var(--line);
  border-radius: var(--ds-radius-section);
  padding: var(--space-3) var(--space-4);
  margin-top: var(--space-2);
  font-size: var(--ds-font-sm);
}
.task-empty strong { color: var(--text); font-size: var(--ds-font-body); font-weight: var(--ds-weight-label); }
.task-empty p { margin: var(--space-1) 0 0; font-size: var(--ds-font-sm); }
.task-empty-actions { display: flex; flex-wrap: wrap; gap: var(--space-2); justify-content: flex-start; margin-top: var(--space-2); }
.creation-feedback {
  width: 100%;
  box-sizing: border-box;
  border: 1px solid color-mix(in srgb, var(--accent) 22%, var(--border));
  background: color-mix(in srgb, var(--accent) 5%, var(--bg));
  border-radius: var(--radius-md);
  padding: var(--space-2) var(--space-3);
  margin: var(--space-3) 0 0;
  box-shadow: none;
}
.creation-feedback[data-kind="missing"] {
  border-color: color-mix(in srgb, var(--warning) 35%, var(--border));
  background: color-mix(in srgb, var(--warning) 6%, var(--bg));
}
.creation-feedback[data-kind="recognizing"] {
  border-color: var(--border);
  background: var(--bg-elevated);
  box-shadow: none;
}
.creation-feedback strong { font-size: var(--font-ui); }
.creation-feedback p { margin: 4px 0 8px; color: var(--muted); font-size: var(--font-xs); }
.creation-feedback .wait-stream { display: grid; gap: 2px; }
.creation-feedback-fields {
  display: grid;
  gap: 2px;
  margin: 0 0 8px;
  padding: 0;
  list-style: none;
  font-size: var(--font-xs);
  color: var(--text);
}
.feedback-links { display: flex; flex-wrap: wrap; gap: 7px; justify-content: center; }
.creation-feedback .feedback-links { justify-content: flex-start; }
.clarification-chip:hover, .feedback-links a:hover { color: var(--accent-text); border-color: var(--accent); }

.composer-dock {
  flex: 0 0 auto;
  padding: 8px 28px 18px;
  background: var(--canvas);
  position: relative;
}
.skill-picker {
  position: absolute;
  left: 28px;
  right: 28px;
  bottom: calc(100% - 8px);
  background: var(--canvas);
  border: 1px solid var(--line);
