  z-index: 30;
  padding: 6px;
}
.skill-option {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  text-align: left;
  border: 0;
  background: transparent;
  padding: 8px 10px;
  border-radius: 8px;
  cursor: pointer;
  color: var(--text);
  font: inherit;
}
.skill-option:hover,
.skill-option:focus {
  background: #f3f4f6;
}
.skill-option-label { font-size: var(--font-ui); font-weight: 600; }
.skill-option-id { font-size: var(--font-xs); color: var(--muted); font-family: var(--mono); }
.skill-picker-empty { padding: 10px 12px; margin: 0; }
.composer-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 0 12px 8px;
}
.composer-template-preview {
  margin: 0 4px 8px;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--chrome);
  font-size: var(--font-meta);
  line-height: 1.45;
}
.composer-template-preview-head {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 10px;
  align-items: baseline;
}
.composer-template-preview-head strong {
  font-size: var(--font-meta);
  font-weight: 600;
}
.composer-template-preview-subject {
  color: var(--muted);
}
.composer-template-preview--lock {
  padding-block: 6px;
}
.composer-template-preview-excerpt {
  margin: 6px 0 0;
  color: var(--text);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.composer-template-preview details {
  margin-top: 4px;
}
.composer-template-preview summary {
  cursor: pointer;
  color: var(--muted);
  font-size: var(--font-meta);
}
.composer-template-preview pre {
  margin: 6px 0 0;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: break-word;
  font-size: var(--font-meta);
  font-family: inherit;
  max-height: 160px;
  overflow: auto;
}
.composer-mail-subject {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: var(--space-2);
  margin: 0 var(--space-3) var(--space-1);
  color: var(--muted);
  font-size: var(--ds-font-helper);
}
.composer-mail-subject input {
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: var(--radius-control);
  padding: var(--space-1) var(--space-2);
  background: var(--canvas);
  color: var(--text);
  font: inherit;
}
.composer-mail-candidates {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
  margin: 0 0 var(--space-2);
}
.skill-chip,
.attach-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-height: 32px;
  font-size: var(--ds-font-body);
  line-height: 20px;
  border: 1px solid transparent;
  background: var(--composer-chip-bg);
  border-radius: 9999px;
  padding: 3px 10px;
  color: var(--composer-accent, var(--accent-text));
}
.attach-chip { color: var(--accent-text); }
.chip-x {
  border: 0;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: var(--ds-font-body);
  line-height: 1;
  padding: 0 0 0 2px;
  min-width: 36px;
  min-height: 36px;
}
.composer-err { padding: 0 28px 8px; }
.process-trace details {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid var(--line);
  color: var(--muted);
}
.process-trace details summary { cursor: pointer; color: var(--text); font-weight: 600; }
.process-trace details p { margin: 6px 0 0; white-space: pre-wrap; }
.trace-list {
  display: grid;
  gap: 6px;
  margin: 10px 0 0;
  padding: 0;
  list-style: none;
}
.trace-list li {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr) auto;
  align-items: baseline;
  gap: 6px;
  color: var(--ds-text-dim);
  font-size: var(--ds-font-sm);
  line-height: var(--ds-line-sm);
}
.trace-list li i { font-style: normal; font-family: var(--mono); }
.trace-list li[data-status="running"] { color: var(--accent-text); }
.trace-list li[data-status="running"] i { animation: breath-dot 1.6s ease-in-out infinite; }
.trace-list li span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.trace-list li[data-status="done"] i { color: color-mix(in srgb, var(--success) 80%, var(--text)); }
.trace-list li[data-status="failed"] { color: color-mix(in srgb, var(--danger) 80%, var(--text)); }
.trace-list li[data-kind="reasoning"] {
  grid-template-columns: 18px minmax(0, 1fr);
}
.conversation-content .process-trace,
.conversation-content .operation-trace { margin-block: var(--space-3); }
.conversation-content .trace-list { gap: var(--space-2); }
.trace-list li[data-kind="reasoning"] span,
.trace-list li span.is-streaming {
  white-space: pre-wrap;
  overflow: visible;
  text-overflow: unset;
}
.trace-list li span.is-streaming::after {
  content: "▍";
  margin-left: 2px;
  color: var(--accent-text);
  animation: stream-caret 1s step-end infinite;
}
.composer-dock,
.composer,
.home-composer-dock,
.session-composer {
  --composer-bg: #ffffff;
  --composer-border: var(--border);
  --composer-radius: 22px;
  --composer-accent: var(--accent);
  --composer-placeholder: #8a8a8a;
  --composer-toolbar-fg: var(--text);
  --composer-send-idle: var(--text-muted);
  --composer-divider: #eee;
  --composer-chip-bg: var(--bg-elevated);
  --composer-chip-radius: 12px;
  --composer-side-btn-bg: var(--bg-elevated);
  --composer-side-btn-size: 36px;
}
:root[data-theme="dark"] .composer-dock,
:root[data-theme="dark"] .composer,
:root[data-theme="dark"] .home-composer-dock,
:root[data-theme="dark"] .session-composer {
  --composer-bg: var(--bg);
  --composer-border: color-mix(in srgb, var(--accent) 42%, var(--border));
  --composer-placeholder: #8b8f96;
  --composer-toolbar-fg: var(--text);
  --composer-send-idle: var(--text-muted);
  --composer-divider: var(--border);
  --composer-chip-bg: color-mix(in srgb, var(--accent) 18%, var(--bg-elevated));
  --composer-side-btn-bg: var(--bg-elevated);
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) .composer-dock,
  :root:not([data-theme="light"]) .composer,
  :root:not([data-theme="light"]) .home-composer-dock,
  :root:not([data-theme="light"]) .session-composer {
    --composer-bg: var(--bg);
    --composer-border: color-mix(in srgb, var(--accent) 42%, var(--border));
    --composer-placeholder: #8b8f96;
    --composer-toolbar-fg: var(--text);
    --composer-send-idle: var(--text-muted);
    --composer-divider: var(--border);
    --composer-chip-bg: color-mix(in srgb, var(--accent) 18%, var(--bg-elevated));
    --composer-side-btn-bg: var(--bg-elevated);
  }
}
.composer {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  width: 100%;
  background: var(--composer-bg);
  border: 1px solid var(--composer-border);
  border-radius: var(--composer-radius);
  padding: 10px 12px 10px 8px;
  box-shadow: none;
  transition: border-color .18s ease, box-shadow .18s ease;
}
.composer:hover {
  border-color: #e4e4e4;
}
.composer:focus-within {
  border-color: #ddd;
  box-shadow: none;
}
.composer:focus-within :is(button, textarea, select):focus-visible {
  outline-color: var(--composer-accent);
}
.composer:not(.composer--workspace) .composer-inline-tools,
.composer:not(.composer--workspace) .composer-toolbar-end {
  display: contents;
}
.composer:not(.composer--workspace) textarea { order: 2; }
.composer:not(.composer--workspace) .composer-add-wrap { order: 1; }
.composer:not(.composer--workspace) .composer-toolbar-divider { order: 3; }
.composer:not(.composer--workspace) .tier-control { order: 4; }
.composer:not(.composer--workspace) .send { order: 5; }
.composer.composer--workspace {
  flex-direction: column;
  align-items: stretch;
  min-height: var(--composer-idle-min, 56px);
  max-height: var(--composer-max-height, 420px);
  border-radius: var(--composer-radius);
  padding: 10px 16px 8px;
  gap: 6px;
}
.composer.composer--workspace textarea {
  width: 100%;
  min-height: 40px;
  max-height: var(--composer-text-max, 336px);
  overflow-y: auto;
  font-size: var(--font-body);
  line-height: var(--composer-line-height, 26px);
  text-align: left;
}
.home-pane.is-composer-reading .composer.composer--workspace { min-height: var(--composer-default-min, 200px); }
.home-pane.is-composer-focused .composer.composer--workspace { min-height: var(--composer-default-min, 200px); }
/* Reading state (not focused) keeps the composer compact so the pane content it
   serves is not pushed off-screen (DESIGN.md §不变量 5). */
.home-pane.is-composer-reading:not(.is-composer-focused) .composer.composer--workspace { min-height: var(--composer-reading-min, 128px); }
.home-pane.is-composer-reading:not(.is-composer-focused) .composer.composer--workspace textarea { min-height: 40px; }

/* Home + session Composer share a rounded-rect, not a full pill. */
.home-composer-dock,
.home-composer-dock .composer-dock,
.home-composer-dock .composer {
  --composer-radius: 22px;
}
.home-composer-dock .composer-toolbar-divider { display: none; }
.home-composer-dock .composer-plus {
  background: transparent;
  color: var(--text-muted);
}
.home-composer-dock .composer-plus:hover,
.home-composer-dock .composer-plus.is-selected,
.home-composer-dock .composer-plus[aria-expanded="true"] {
  background: var(--bg-elevated);
  color: var(--text);
}
.home-composer-dock .tier-control {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
}
.home-composer-dock:focus-within .tier-trigger {
  color: var(--text);
}

.composer-plus {
  width: var(--composer-side-btn-size, 36px);
  height: var(--composer-side-btn-size, 36px);
  border: 0;
  background: var(--composer-side-btn-bg, var(--bg-elevated));
  color: var(--composer-toolbar-fg, #000000);
  font-size: var(--ds-font-block-title);
  line-height: 1;
  cursor: pointer;
  border-radius: var(--ds-radius-tag);
  display: flex;
  align-items: center;
  justify-content: center;
}
.composer-plus:hover,
.composer-plus.is-selected,
.composer-plus[aria-expanded="true"] {
  color: var(--composer-accent, var(--accent-text));
  background: var(--composer-chip-bg);
}
.composer textarea, .field input, .field textarea, .field select, .search-box,
.action-row input, .action-row select {
  flex: 1;
  border: 0;
  background: transparent;
  font: inherit;
  font-size: var(--font-body);
  line-height: var(--leading-body);
  color: var(--text);
}
.composer textarea { outline: none; }
.field input:focus-visible,
.field textarea:focus-visible,
.field select:focus-visible,
.search-box:focus-visible,
.action-row input:focus-visible,
.action-row select:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}
.composer textarea { resize: none; font-size: var(--font-body); line-height: var(--composer-line-height, 26px); max-height: var(--composer-text-max, 336px); }
.composer textarea::placeholder { color: var(--composer-placeholder, #8a8a8a); font-size: var(--font-body); line-height: 24px; }
.composer-tools {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
  padding: 8px 12px 0;
  font-size: var(--font-xs);
  color: var(--muted);
}
.composer-tools a { color: var(--composer-accent, var(--accent-text)); text-decoration: none; }
.composer-hint { color: var(--muted); }
.composer-tier {
  margin-left: auto;
  color: var(--muted);
}
.composer-add-wrap { position: relative; }
.composer-add-menu { left: 0; bottom: 42px; }
.cascade-menu {
  width: 270px;
  padding: 8px;
  border-radius: 16px;
  overflow: visible;
  box-shadow: var(--shadow-quiet);
}
/* 根菜单的行：单列、整行可点（图 4 形态）。按钮挂在 .composer-menu-section 下，
   原来写成 `.cascade-menu > button`（直接子节点）从未命中 —— 行因此退化成 inline 流，
   两个按钮挤在一行（这正是「两列一组」的成因）。子面板的行由 .cascade-submenu 规则负责。 */
.cascade-menu .composer-menu-section > button {
  min-height: 42px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 10px;
  border-radius: var(--ds-radius-input);
  font-size: var(--font-sm);
  width: 100%;
  box-sizing: border-box;
  text-align: left;
}
/* Nested skills live in .submenu-scroll; descendant selectors keep flex + gap. */
.cascade-submenu button,
.cascade-submenu a,
.submenu-scroll > button {
  min-height: 42px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 10px;
  border-radius: var(--ds-radius-input);
  font-size: var(--font-sm);
  width: 100%;
  box-sizing: border-box;
  text-align: left;
  border: 0;
  background: transparent;
  cursor: pointer;
  color: inherit;
}
.cascade-menu .composer-menu-section > button > span:not(.menu-arrow) { flex: 1; }
/* 图标字形走辅助色（docs/DESIGN.md §颜色：图标砖与图标字形归 --accent*）。 */
.cascade-icon { width: 20px; height: 20px; flex: 0 0 20px; color: var(--accent-text); }
.menu-arrow { margin-left: auto; color: var(--muted); font-size: 22px; line-height: 1; }
.menu-divider { height: 1px; margin: 6px -8px; background: var(--line); }
.cascade-submenu {
  left: calc(100% + 10px);
  bottom: 0;
  width: 310px;
  max-height: min(520px, 70vh);
  padding: 8px;
  border-radius: 16px;
  overflow-y: auto;
  box-shadow: var(--shadow-quiet);
}
.cascade-submenu button > span,
.cascade-submenu a > span:last-child {
  min-width: 0;
  flex: 1;
  display: grid;
  gap: 2px;
}
.cascade-submenu strong { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: var(--font-ui); }
.cascade-submenu small { color: var(--muted); font-size: var(--font-xs); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.submenu-scroll { max-height: 330px; overflow-y: auto; display: grid; }
.menu-symbol { width: 20px; text-align: center; color: var(--muted); font-size: 17px; }
.menu-empty { margin: 8px 10px; color: var(--muted); font-size: var(--font-xs); }
.project-chip {
  display: inline-flex; align-items: center; gap: 8px; max-width: 260px;
  border: 1px solid var(--accent); border-radius: var(--ds-radius-input); padding: 6px 8px; background: var(--chrome);
}
.project-chip > span:nth-child(2) { min-width: 0; display: grid; }
.project-chip strong { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: var(--font-sm); }
.project-chip small { color: var(--muted); font-size: var(--font-xs); }
.skill-chip--quiet {
  color: var(--text-muted);
  background: #f5f5f5;
  font-weight: 400;
}
.attachment-card {
  display: flex; align-items: center; gap: 8px; max-width: 260px;
  border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 7px 8px;
  background: var(--bg-elevated);
}
.attachment-icon { color: var(--text-muted); font-size: var(--ds-font-block-title); }
.attachment-meta { min-width: 0; display: grid; }
.attachment-meta strong { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: var(--font-xs); }
.attachment-meta small { color: var(--muted); font-size: var(--font-xs); }
.drop-overlay { position: absolute; inset: 0 20px; display: grid; place-items: center; background: color-mix(in srgb, var(--bg) 94%, transparent); border: 2px dashed var(--border-strong); border-radius: var(--radius-md); color: var(--text); z-index: 50; }
