.admin-header-actions { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.btn.sm,
.btn.ghost.sm { padding: 6px 10px; font-size: var(--font-sm); min-height: 36px; }
/* L3 文字按钮：无边框、无底色，行内次级动作与「查看更多/收起」的默认档。
   该用文字按钮的地方出现描边按钮视为 bug（docs/DESIGN.md §1 不变量 8）。 */
.btn.text {
  height: var(--btn-text-h);
  min-height: var(--btn-text-h);
  padding: 0 var(--btn-text-pad-x);
  border: 0;
  border-radius: var(--radius-control);
  background: transparent;
  box-shadow: none;
  color: var(--accent-text);
  font-size: var(--ds-font-sm);
}
.btn.text:hover:not(:disabled) { background: var(--btn-text-hover-bg); }
.btn.text:disabled { background: transparent; color: var(--text-muted); }
.admin-shell .btn {
  min-height: var(--control-h-lg);
  padding: var(--space-1) var(--space-3);
  font-size: var(--ds-font-body);
  line-height: var(--ds-line-body);
}
.admin-shell .btn.sm,
.admin-shell .btn.ghost.sm {
  min-height: var(--control-h-lg);
  padding: var(--space-1) var(--space-2);
  font-size: var(--ds-font-body);
}

.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }

.btn {
  font-family: var(--sans);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 7px 12px;
  cursor: pointer;
  background: var(--canvas);
  color: var(--text);
  font-size: var(--font-ui);
  min-height: 36px;
  box-sizing: border-box;
}
/* 行 / 卡内动作：不是视口主行动。按 docs/DESIGN.md §不变量 1（同一视口最多一个实底主 CTA），
   列表与卡片里的动作一律用描边款；`.btn.work` / `.btn.primary` 只留给页面级或抽屉级的主行动。 */
.btn.row-action {
  background: var(--bg);
  border-color: var(--control-border);
  color: var(--accent-text);
}

.btn.row-action:hover:not(:disabled) {
  background: color-mix(in srgb, var(--accent) 8%, var(--bg));
  border-color: var(--accent);
}

.btn.row-action:disabled {
  background: transparent;
  border-color: var(--border);
  color: var(--text-muted);
}

.btn.primary {
  background: var(--primary);
  color: var(--primary-fg);
  border: 1px solid var(--primary);
  border-radius: var(--radius-sm);
  box-shadow: none;
}
.btn.primary:hover:not(:disabled) {
  background: var(--primary-hover);
  border-color: var(--primary-hover);
}
.btn.primary:focus-visible {
  outline: 2px solid var(--bg);
  outline-offset: 2px;
  box-shadow: 0 0 0 4px var(--focus-ring);
}
.btn:hover { border-color: var(--control-border-hover); }
.btn.send {
  background: var(--primary);
  color: var(--primary-fg);
  border-color: var(--primary);
  border-radius: var(--ds-radius-tag);
  padding: 7px 16px;
}
.btn.send:not(:disabled):hover { filter: brightness(1.05); }
.composer .btn.send.send-arrow,
.btn.send.send-arrow {
  width: var(--composer-side-btn-size, 36px);
