.home-composer-dock .btn.send.send-arrow,
.home-composer-dock .btn.send.send-arrow:disabled,
.home-composer-dock .btn.send.send-arrow:not(:disabled),
.home-composer-dock .btn.send.send-arrow:not(:disabled):hover {
