}
.btn.ghost { background: var(--canvas); color: var(--text); border-color: var(--line); }
.btn.danger { background: var(--bg); color: var(--danger); border-color: color-mix(in srgb, var(--danger) 45%, var(--border)); }
.btn.selected {
