}
.md {
  font-size: var(--font-body);
  line-height: var(--leading-body);
  color: var(--text);
}
.md h1, .md h2, .md h3, .md h4 {
  margin: 0 0 8px;
  letter-spacing: 0;
  font-weight: 600;
  color: var(--text);
}
.md p { margin: 0 0 8px; }
.md ul, .md ol { margin: 0 0 8px; padding-left: 1.2em; }
.md table {
  width: 100%;
