}
.md th {
  color: var(--muted);
  font-weight: 500;
  letter-spacing: 0;
  font-size: var(--font-meta);
  width: 88px;
  font-family: var(--sans);
}
.md td {
  font-family: var(--sans);
  font-size: var(--font-table);
}
.md code, .mono {
  font-family: var(--mono);
