  color: var(--ok);
  font-size: var(--font-sm);
  white-space: pre-wrap;
}
.zh .zh-body { margin-top: 6px; }
.lock { color: var(--ok); font-style: normal; font-size: var(--font-xs); }
.steps {
  border: 0;
  padding: 0;
  background: transparent;
}
.steps h4 { margin: 0 0 8px; font-size: var(--font-table); font-weight: 500; letter-spacing: 0; }
.steps li { font-size: var(--font-xs); margin: 3px 0; color: var(--muted); font-family: var(--mono); }

.board {
  display: grid;
  grid-template-columns: repeat(5, minmax(170px, 1fr));
  gap: 8px;
  overflow-x: auto;
}
.col {
