  border: 1px solid var(--line);
  border-radius: var(--ds-radius-input);
  padding: 8px;
  min-height: 240px;
}
.col h3 {
  margin: 0 0 10px;
  font-size: var(--font-meta);
  font-weight: 500;
  letter-spacing: 0;
  color: var(--muted);
}
.kol-card {
  background: var(--canvas);
  border: 1px solid var(--line);
  border-radius: var(--ds-radius-input);
  padding: 8px;
  margin-bottom: 8px;
}
.kol-card .meta {
  font-size: var(--font-xs);
  color: var(--muted);
  margin: 4px 0 8px;
}
.kol-card .acts { display: flex; flex-wrap: wrap; gap: 6px; }

.pipeline-page { max-width: 1180px; }
.pipeline-page.has-drawer { padding-right: min(428px, 42vw); }
.main > .pipeline-page.has-drawer {
  overflow: hidden;
}
.pipeline-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
  align-items: center;
  margin: 12px 0 4px;
}
.pipeline-filters label {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: var(--font-meta);
  color: var(--muted);
}
.pipeline-filters select {
  font: inherit;
  font-size: var(--font-meta);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--canvas);
  color: var(--text);
  padding: 3px 8px;
}
.pipeline-table {
  border: 1px solid var(--line);
  border-radius: var(--ds-radius-input);
  background: var(--canvas);
  overflow-x: auto;
  font-feature-settings: "tnum" 1;
}
.pipeline-head,
.pipeline-row {
  display: grid;
  grid-template-columns: 168px minmax(520px, 1fr);
  gap: 12px;
  align-items: center;
  min-width: 720px;
}
.pipeline-head {
  padding: 10px 12px 8px;
  border-bottom: 1px solid var(--line);
  background: var(--chrome);
  font-size: var(--font-meta);
  font-weight: 500;
  color: var(--muted);
  letter-spacing: 0;
}
.pipeline-id-col {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
  text-align: left;
}
.pipeline-id-col strong { font-size: var(--font-table); }
.pipeline-id-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}
.pipeline-owner {
  font-size: var(--font-xs);
  color: var(--muted);
}
.pipeline-track-col { min-width: 0; }
.stage-domains {
  display: grid;
  grid-template-columns: repeat(15, minmax(0, 1fr));
  margin-bottom: 4px;
  font-size: var(--font-xs);
  color: var(--muted);
}
.stage-domains span {
  text-align: center;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.stage-track {
  display: grid;
  grid-template-columns: repeat(15, minmax(0, 1fr));
  list-style: none;
  margin: 0;
  padding: 0;
  position: relative;
}
.stage-track::before {
  content: "";
  position: absolute;
  left: 8%;
  right: 8%;
  top: 50%;
  height: 1px;
  background: var(--line);
}
.stage-track-legend {
  font-size: var(--font-xs);
  color: var(--muted);
  text-align: center;
}
.stage-track-legend::before { display: none; }
.stage-track-legend li {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.stage-track.is-phases {
  grid-template-columns: repeat(8, minmax(0, 1fr));
  align-items: start;
}
.stage-track.is-phases::before {
  top: 6px;
}
.stage-track li {
  position: relative;
  display: flex;
  justify-content: center;
  z-index: 1;
}
.stage-track.is-phases li {
  flex-direction: column;
  align-items: center;
  gap: 6px;
}
.stage-track .phase-label {
  font-size: var(--font-xs);
  line-height: 1.3;
  color: var(--muted);
  text-align: center;
}
.stage-track li[data-phase-state="current"] .phase-label {
  color: var(--orange);
  font-weight: 600;
}
.stage-track li[data-phase-state="done"] .phase-label {
  color: var(--success);
}
.milestone {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  border: 1.5px solid var(--line);
  background: var(--canvas);
}
.milestone.is-done {
  background: var(--success);
  border-color: var(--success);
}
.milestone.is-current {
  width: 11px;
  height: 11px;
  background: var(--text);
  border-color: var(--text);
  box-shadow: none;
}
.pipeline-item {
  border-top: 1px solid var(--line);
}
.pipeline-item:first-of-type { border-top: 0; }
.pipeline-item.is-selected { background: var(--chrome); }
.pipeline-item.exception .pipeline-row { box-shadow: inset 3px 0 0 var(--danger); }
.pipeline-row {
  width: 100%;
  border: 0;
  background: transparent;
  padding: 10px 12px;
  cursor: pointer;
  font: inherit;
  color: inherit;
}
.pipeline-row:hover { background: color-mix(in srgb, var(--accent) 4%, transparent); }
.pipeline-kv {
  display: grid;
  grid-template-columns: 72px minmax(0, 1fr) 72px minmax(0, 1fr);
  gap: 6px 16px;
  margin: 0;
  font-size: var(--font-sm);
}
.pipeline-kv dt { color: var(--muted); }
.pipeline-kv dd { margin: 0; min-width: 0; }
.pipeline-empty-hint { margin: 0; }
.pipeline-drawer {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: min(420px, 94vw);
  z-index: 81;
  display: flex;
  flex-direction: column;
  background: var(--bg);
  border-left: 1px solid var(--border);
  box-shadow: var(--shadow-quiet);
}
.pipeline-drawer-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  padding: 16px 16px 12px;
  border-bottom: 1px solid var(--line);
}
.pipeline-drawer-head h2 {
  margin: 2px 0 6px;
  font-size: var(--font-title);
}
.pipeline-drawer-body {
  flex: 1;
  min-height: 0;
  overflow: auto;
  padding: 12px 16px 20px;
  display: grid;
  gap: 16px;
}
.pipeline-drawer-body h3 {
  margin: 0 0 8px;
  font-size: var(--font-section);
}
.pipeline-drawer-body .pipeline-kv {
  grid-template-columns: 72px minmax(0, 1fr);
}
.pipeline-drawer-track {
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px 4px;
}
.pipeline-drawer-track::before { display: none; }
.pipeline-drawer-track li {
  flex-direction: column;
  gap: 4px;
}
.pipeline-drawer-tick {
  font-size: var(--font-xs);
  color: var(--muted);
  text-align: center;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
}
.pipeline-drawer-foot {
  padding: 12px 16px 16px;
  border-top: 1px solid var(--line);
}
.pipeline-drawer [data-stage-graph="product"] .stage-chip-picker {
  margin-top: 8px;
}
.pipeline-drawer [data-stage-graph="product"] .stage-chip {
  min-height: 32px;
}
.chip {
  font-size: var(--font-sm);
  letter-spacing: 0;
  background: var(--canvas);
  border: 1px solid var(--line);
  border-radius: var(--ds-radius-tag);
  padding: 6px 10px;
  font-family: var(--sans);
  color: var(--text);
  white-space: nowrap;
  display: inline-flex;
  align-items: center;
  min-height: 36px;
  box-sizing: border-box;
}

.list-page { display: grid; gap: 12px; max-width: none; width: 100%; }
.exam-page { gap: var(--space-4); max-width: 46em; }
.exam-page h1 {
  font-size: var(--font-page-title);
  font-weight: 600;
  line-height: var(--leading-tight);
  letter-spacing: -0.02em;
}
.exam-empty {
  padding: var(--space-5) 0 var(--space-4);
}
.exam-empty h2 {
  margin: 0 0 var(--space-2);
  font-size: var(--font-section);
  font-weight: 600;
  line-height: var(--leading-tight);
}
.exam-empty .muted { margin: 0 0 var(--space-2); }
.exam-list { display: grid; gap: var(--space-3); }
.exam-card h3 { font-size: var(--font-section); font-weight: 600; }
.exam-take, .exam-result { display: grid; gap: var(--space-3); }
.exam-question legend { font-weight: 600; }
.exam-question p { margin: 0 0 var(--space-2); }
.admin-exams .chip-row { margin-bottom: var(--space-3); }

/* ---- 考试改版（2026-10-08）：状态 chip / KPI / 左右布局 / 答题进度 / 复盘 ---- */

/* 状态 chip：20px 描边、12px/500、方角 4px；状态同时用文案表达（§24.6） */
.exam-chip {
  display: inline-flex;
  align-items: center;
  height: 20px;
  padding: 0 8px;
  border: 1px solid var(--border);
  border-radius: 4px;
  font-size: 12px;
  font-weight: 500;
  line-height: 1;
  white-space: nowrap;
}
.exam-chip[data-tone="quiet"] { color: var(--text-quiet); border-color: var(--border); }
.exam-chip[data-tone="accent"] { color: var(--accent-text); border-color: var(--accent); }
.exam-chip[data-tone="success"] { color: var(--success); border-color: var(--success); }
.exam-chip[data-tone="warning"] { color: var(--warning); border-color: var(--warning); }
.exam-chip[data-tone="danger"] { color: var(--danger); border-color: var(--danger); }

/* 管理侧页头：标题 + 右侧唯一 L1 */
.exam-page-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-3);
}
.exam-page-head .btn { flex-shrink: 0; }

/* KPI 统计条（§9.2）：4 卡等分，全部可点击下钻 */
.exam-kpi {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--space-3);
}
.exam-kpi-card {
  display: grid;
  gap: var(--space-1);
  padding: 12px 16px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-card);
  text-align: left;
  cursor: pointer;
}
.exam-kpi-card:hover { border-color: var(--accent); }
.exam-kpi-value { font-size: 20px; font-weight: 600; color: var(--text); line-height: 1.2; }
.exam-kpi-label { font-size: 12px; color: var(--text-quiet); }

/* 管理侧主区：左考试列表 + 右详情（§24.2；≤1100px 堆叠） */
.exam-manage {
  display: grid;
  grid-template-columns: 280px minmax(0, 1fr);
  gap: var(--space-3);
  align-items: start;
}
@media (max-width: 1100px) {
  .exam-manage { grid-template-columns: minmax(0, 1fr); }
}
.exam-side-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--space-2);
  margin-bottom: var(--space-2);
}
.exam-side-head h2 { margin: 0; font-size: var(--ds-font-sm); font-weight: 600; }
.exam-side-list { list-style: none; margin: 0; padding: 0; display: grid; }
.exam-side-row {
  display: grid;
  gap: var(--space-1);
  width: 100%;
  padding: 10px 12px;
  border: 0;
  border-left: 2px solid transparent;
  border-top: 1px solid var(--border);
  background: transparent;
  text-align: left;
  cursor: pointer;
}
.exam-side-list li:first-child .exam-side-row { border-top: 0; }
.exam-side-row:hover { background: var(--surface-hover); }
.exam-side-row[data-selected="true"] {
  border-left-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 8%, transparent);
}
.exam-side-title { font-size: var(--ds-font-sm); font-weight: 500; color: var(--text); overflow-wrap: anywhere; }
.exam-side-meta { display: flex; align-items: center; gap: var(--space-2); font-size: 12px; flex-wrap: wrap; }

/* 右详情：标题 + Tab */
.exam-detail-head h2 { margin: 0 0 var(--space-1); font-size: var(--ds-font-sm); font-weight: 600; }
.exam-detail-head .muted { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; margin: 0 0 var(--space-2); }
.exam-tabs {
  display: flex;
  gap: var(--space-4);
  border-bottom: 1px solid var(--border);
  margin-bottom: var(--space-3);
}
.exam-tab {
  height: 36px;
  padding: 0 2px;
  border: 0;
  background: transparent;
  color: var(--text-quiet);
  font-size: var(--ds-font-sm);
  cursor: pointer;
}
.exam-tab[data-selected="true"] {
  color: var(--accent-text);
  font-weight: 600;
  box-shadow: inset 0 -2px 0 var(--accent);
}
.exam-tabpane { display: grid; gap: var(--space-4); }
.exam-block { display: grid; gap: var(--space-2); align-content: start; }
.exam-block > h3 { margin: 0; font-size: var(--ds-font-sm); font-weight: 600; }
.exam-block .muted { margin: 0; }
.exam-block-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
  flex-wrap: wrap;
}
.exam-block-head h3 { margin: 0; font-size: var(--ds-font-sm); font-weight: 600; }
.exam-batch { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; }
.exam-actions { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; }

/* 试题行：选择框 + 内容 + L3 操作（三段式 §24.6）
   注：用 .admin-row.exam-item-row 双类提升特异性，覆盖旧 .admin-row 的 flex 规则 */
.admin-row.exam-item-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: var(--space-2);
  align-items: start;
  justify-content: stretch;
}
.exam-item-check { margin-top: 2px; }
.exam-item-main { display: grid; gap: var(--space-1); min-width: 0; }
.exam-item-prompt { margin: 0; font-size: var(--ds-font-sm); color: var(--text); overflow-wrap: anywhere; }
.exam-item-main .muted { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; margin: 0; font-size: 12px; }
.exam-item-index { min-width: 20px; text-align: right; font-size: 12px; padding-top: 2px; }

/* 知识多选（>8 项降级为带搜索的紧凑列表，§4.1） */
.exam-search { max-width: 18rem; margin-bottom: var(--space-2); }
.exam-knowledge-list {
  display: grid;
  gap: var(--space-1);
  max-height: 192px;
  overflow-y: auto;
  padding: var(--space-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-control);
  margin-bottom: var(--space-2);
}

/* 发布区：R3 前置校验原因 */
.exam-publish { border-top: 1px solid var(--border); padding-top: var(--space-3); }
.exam-block-reason {
  margin: 0;
  font-size: 12px;
  color: var(--warning);
}

/* 分配 */
.exam-assign-form { max-width: 28rem; }
.admin-row.exam-assign-row { display: block; }

/* 成绩：通过率分布条 + 筛选 + 明细表 */
.exam-dist { display: grid; gap: var(--space-2); }
.exam-dist-bar { display: flex; gap: var(--space-1); }
.exam-dist-seg {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 32px;
  padding: 0 var(--space-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-control);
  background: transparent;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  overflow: hidden;
  white-space: nowrap;
}
.exam-dist-seg[data-tone="success"] {
  color: var(--success);
  border-color: color-mix(in srgb, var(--success) 40%, transparent);
  background: color-mix(in srgb, var(--success) 10%, transparent);
}
.exam-dist-seg[data-tone="danger"] {
  color: var(--danger);
  border-color: color-mix(in srgb, var(--danger) 40%, transparent);
  background: color-mix(in srgb, var(--danger) 10%, transparent);
}
.exam-dist-seg[aria-pressed="true"] { font-weight: 600; box-shadow: inset 0 0 0 1px currentColor; }
.exam-score-filters { margin-bottom: 0; }
.exam-score-filters .btn.text[data-selected="true"] {
  color: var(--accent-text);
  font-weight: 600;
  background: var(--btn-text-hover-bg);
}

/* 紧凑空态（§9.3）：左对齐、无 hero */
.exam-empty-compact { padding: var(--space-3) 0; }
.exam-empty-compact .muted { margin: 0 0 var(--space-2); }

/* ---- 员工侧 ---- */

/* 待办汇总条（不变量 6：汇总层） */
.exam-summary { margin: 0; font-size: var(--ds-font-sm); color: var(--text); font-weight: 500; }

/* 紧凑列表行（三段式 §24.6）：标题+元信息 | 状态 chip | L3 操作 */
.exam-rows { list-style: none; margin: 0; padding: 0; display: grid; }
.exam-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: var(--space-3);
  align-items: center;
  padding: 10px 0;
  border-top: 1px solid var(--border);
}
.exam-rows .exam-row:first-child { border-top: 0; }
.exam-row-main { display: grid; gap: 2px; min-width: 0; }
.exam-row-title { font-size: var(--ds-font-sm); font-weight: 500; color: var(--text); overflow-wrap: anywhere; }
.exam-row-meta { font-size: 12px; }

/* 答题页：sticky 进度头 */
.exam-take-head {
  position: sticky;
  top: 0;
  z-index: 5;
  background: var(--bg);
  padding: var(--space-2) 0;
  display: grid;
  gap: var(--space-2);
}
.exam-progress { display: flex; align-items: center; gap: var(--space-2); }
.exam-progress-bar {
  flex: 1;
  height: 6px;
  border-radius: 3px;
  background: color-mix(in srgb, var(--text) 12%, transparent);
  overflow: hidden;
}
.exam-progress-bar > span {
  display: block;
  height: 100%;
  background: var(--accent);
  border-radius: 3px;
  transition: width 0.2s ease;
}

/* 选项：radio 列表行（非 checkbox chip，避免多选语义混淆） */
.exam-options { display: grid; gap: var(--space-2); }
.exam-option {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: 8px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-control);
  font-size: var(--ds-font-sm);
  cursor: pointer;
}
.exam-option:hover { background: var(--surface-hover); }
.exam-option[data-checked="true"] {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 8%, transparent);
}
.exam-option input { margin: 0; }

/* 答题页：sticky 提交栏（关键操作区无滚动遮挡，不变量 5） */
.exam-submit-bar {
  position: sticky;
  bottom: 0;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  padding: var(--space-3) 0;
  background: var(--bg);
  border-top: 1px solid var(--border);
}

/* 结果复盘 */
.exam-result h2 { display: flex; align-items: center; gap: var(--space-2); margin: 0; font-size: var(--ds-font-sm); font-weight: 600; }
.exam-result h3 { margin: var(--space-2) 0 0; font-size: var(--ds-font-sm); font-weight: 600; }
.exam-review { list-style: none; margin: 0; padding: 0; display: grid; }
.exam-review-row { display: grid; gap: var(--space-1); padding: 10px 0; border-top: 1px solid var(--border); }
.exam-review-row:first-child { border-top: 0; }
.exam-review-prompt { margin: 0; font-size: var(--ds-font-sm); color: var(--text); overflow-wrap: anywhere; }
.exam-review-row .muted { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; margin: 0; font-size: 12px; }
.connector-use-page {
  max-width: 40rem;
  gap: var(--space-5);
}
.connector-use-hero {
  display: grid;
  gap: var(--space-2);
}
.connector-use-hero .page-kicker { margin-bottom: 0; }
.connector-use-page h1 {
  margin: 0;
  font-size: var(--font-page-title);
  line-height: var(--leading-tight);
  font-weight: 600;
}
.connector-use-hero .muted { margin: 0; max-width: 36em; }
.connector-use-error {
  display: grid;
  justify-items: start;
  gap: var(--space-3);
}
.connector-use-error .error { margin: 0; }
.connector-use-list {
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg);
}
.connector-use-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: var(--space-3) var(--space-4);
  align-items: start;
  padding: var(--space-4);
  border-top: 1px solid var(--border);
  font-size: var(--font-body);
}
.connector-use-row:first-child { border-top: 0; }
.connector-use-row strong { display: block; font-size: var(--font-section); font-weight: 600; }
.connector-use-row .muted { margin: var(--space-1) 0 0; }
.connector-use-aside {
  display: grid;
  justify-items: end;
  align-content: start;
  gap: var(--space-2);
}
.connector-use-status {
  font-size: var(--font-sm);
  color: var(--text-muted);
  white-space: nowrap;
}
.connector-use-status[data-status="needs_personal_bind"],
.connector-use-status[data-status="expired"] { color: var(--text); }
.connector-use-access {
  font-size: var(--font-sm);
}
.connector-use-aside [data-connector-use-read-hint] {
  margin: 0;
  text-align: right;
}
.connector-use-page .btn,
.connector-use-page a.btn {
  min-height: 44px;
  min-width: 44px;
  padding: var(--space-2) var(--space-4);
  border-radius: var(--radius-md);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-decoration: none;
}
@media (max-width: 720px) {
  .connector-use-row { grid-template-columns: minmax(0, 1fr); }
  .connector-use-aside { justify-items: start; }
}
.list-page.kb-page { max-width: none; gap: var(--space-4); }
.kb-page, .admin-kb {
  --kb-accent: var(--accent);
  --kb-accent-ink: var(--accent-text);
  --kb-ok: var(--success);
  --kb-warn: var(--danger);
}
.kb-page .panel,
.admin-kb .panel {
  border-radius: var(--radius-md);
}
.kb-page .btn,
.admin-kb .btn,
.kb-page .chip,
.admin-kb .chip,
.kb-page .field input,
.kb-page .field textarea,
.kb-page .field select,
.admin-kb .field input,
.admin-kb .field textarea,
.admin-kb .field select {
  border-radius: var(--radius-sm);
}
.kb-page .btn, .admin-kb .btn { margin-top: 0; }
.kb-page .btn:hover, .admin-kb .btn:hover {
  border-color: var(--control-border-hover);
  color: var(--text);
}
.kb-page .btn.work, .admin-kb .btn.work {
  border-radius: var(--radius-sm);
}
.kb-page .btn:active,
.kb-page .btn.is-on,
.kb-page .btn[aria-pressed="true"],
.admin-kb .btn:active,
.admin-kb .btn.is-on,
.admin-kb .btn[aria-pressed="true"] {
  background: color-mix(in srgb, var(--accent) 10%, var(--bg));
  border-color: var(--accent);
  color: var(--accent-text);
}
.kb-page .btn.work:active,
.admin-kb .btn.work:active {
  background: var(--primary-hover);
  border-color: var(--primary-hover);
  color: var(--primary-fg);
}
.kb-page .btn.is-on:hover,
.kb-page .btn[aria-pressed="true"]:hover,
.admin-kb .btn.is-on:hover,
.admin-kb .btn[aria-pressed="true"]:hover {
  background: color-mix(in srgb, var(--accent) 14%, var(--bg));
  border-color: var(--accent);
  color: var(--accent-text);
}
.kb-hero {
  padding: var(--space-1) var(--space-1) 0;
}
.kb-hero h1, .kb-hero h2 { margin: 0 0 var(--space-2); font-size: var(--font-page-title); letter-spacing: -0.02em; font-weight: 500; line-height: var(--leading-tight); }
.kb-lead { margin: var(--space-2) 0 var(--space-3); color: var(--muted); font-size: var(--font-body); line-height: var(--leading-body); max-width: 46em; }
.kb-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: var(--space-2) var(--space-3);
}
.kb-search { flex: 1 1 18rem; min-width: 0; }
.kb-search-input {
  display: block;
  width: 100%;
  box-sizing: border-box;
  min-height: var(--control-pill-height);
  padding: 0 var(--space-3);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--canvas);
  color: var(--text);
  font: inherit;
  font-size: var(--font-ui);
}
.kb-filters { display: flex; flex-wrap: wrap; gap: var(--space-2) var(--space-3); }
.kb-filter {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  color: var(--muted);
  font-size: var(--font-ui);
}
.kb-filter select {
  min-height: var(--control-pill-height);
  padding: 0 var(--space-2);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--canvas);
  color: var(--text);
  font: inherit;
  font-size: var(--font-ui);
}
.kb-org-link { margin: 0 0 16px; font-size: var(--font-sm); }
.kb-org-link a { color: var(--muted); }
.kb-org-link a:hover { color: var(--kb-accent); }
.kb-group { display: grid; gap: 10px; }
.kb-group-head h2 { margin: 0; font-size: var(--font-section); }
.kb-group-head p { margin: 4px 0 0; color: var(--muted); font-size: var(--font-ui); }
/* 分类选择（族 → 域 → 库）：一行下拉，不做二次分栏。 */
.kb-scope-picker { display: grid; gap: var(--space-2); margin: 0 0 var(--space-3); }
.kb-scope-lead { margin: 0; color: var(--muted); font-size: var(--font-ui); }
.kb-scope-selects { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-2) var(--space-3); }
.kb-scope-path { margin: 0; color: var(--text); font-size: var(--font-sm); }
.list-page.kb-page.has-drawer { padding-right: min(440px, 42vw); }
.kb-card {
  padding: var(--space-4);
  border-radius: var(--radius-md);
  box-shadow: none;
  display: grid;
  gap: var(--space-2);
}
.kb-card.is-cited {
  border-color: color-mix(in srgb, var(--accent) 35%, var(--border));
  box-shadow: inset 3px 0 0 var(--accent);
}
.kb-card.is-hidden {
  border-color: var(--kb-warn);
  box-shadow: inset 4px 0 0 var(--kb-warn);
}
.kb-card-title-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}
.kb-card-title-row h3 { margin: 0; font-size: var(--font-section); line-height: var(--leading-tight); }
.kb-card { padding: var(--space-3) var(--space-4); }
.kb-card-tags { display: flex; flex-wrap: wrap; gap: var(--space-1); justify-content: flex-end; }
.kb-kind { color: var(--muted); }
.kb-card-meta-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-1) var(--space-3);
}
.kb-scope { display: inline-flex; flex-wrap: wrap; gap: var(--space-1); }
.kb-scope-chip { color: var(--text); }
.kb-card .kb-actions { margin-top: var(--space-1); }
.kb-card-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
.kb-card-head h3 { margin: 0 0 8px; font-size: var(--font-section); }
.kb-card-meta { display: flex; flex-wrap: wrap; gap: 6px; margin: 0; }
.kb-card-body { margin: 10px 0 8px; line-height: 1.6; }
.kb-card-scope,
.kb-card-summary,
.kb-card-vars,
.kb-card-source,
.kb-card-hidden {
  margin: 0;
  font-size: var(--font-ui);
  line-height: var(--leading-body);
}
.kb-card-scope { color: var(--text); }
.kb-card-summary { color: var(--muted); }
.kb-card-vars { color: var(--text); }
.kb-card-source,
.kb-card-hidden { color: var(--muted); font-size: var(--font-sm); }
.kb-starter { margin: 0 0 10px; font-size: var(--font-ui); color: var(--text); }
.kb-starter code {
  font-family: var(--mono);
  font-size: var(--font-xs);
  background: var(--chrome);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  padding: 2px 6px;
}
.kb-actions { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.kb-more {
  margin-top: 4px;
  color: var(--muted);
  font-size: var(--font-sm);
}
.kb-more summary { cursor: pointer; user-select: none; }
.kb-more-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 8px; }
.kb-action { position: relative; display: inline-flex; align-items: center; }
.kb-tip {
  position: absolute;
  left: 0;
  top: calc(100% + 8px);
  z-index: 30;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  width: max-content;
  min-width: 220px;
  max-width: min(320px, 70vw);
  padding: var(--space-3);
  background: var(--bg);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-quiet);
  font-size: var(--font-xs);
  font-weight: 400;
  line-height: 1.55;
}
.kb-action:last-child .kb-tip { left: auto; right: 0; }
.kb-tip-x {
  flex: 0 0 auto;
  width: 18px;
  height: 18px;
  margin: 0;
  border: 1px solid var(--line);
  background: #fff;
  color: var(--muted);
  border-radius: 0;
  cursor: pointer;
  font: inherit;
  font-size: var(--ds-font-body);
  line-height: 1;
  padding: 0;
}
.kb-tip-x:hover { border-color: var(--kb-accent); color: var(--kb-accent); }
.kb-result { margin: 10px 0 0; color: var(--muted); font-size: var(--font-sm); line-height: var(--leading-body); }
.chip-ok {
  background: var(--kb-ok, #008f6b);
  border-color: var(--kb-ok, #008f6b);
  color: #fff;
}
.chip-warn {
  background: var(--kb-warn, #e11d2e);
  border-color: var(--kb-warn, #e11d2e);
  color: #fff;
}
.kb-hide-panel {
  margin-top: 12px;
  display: grid;
  gap: 8px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}
.kb-hide-title { margin: 0; font-size: var(--font-ui); font-weight: 600; }
.kb-hide-option {
  text-align: left;
  display: grid;
  gap: 4px;
  border: 1px solid var(--line);
  background: var(--chrome);
  border-radius: var(--radius-sm);
  padding: 10px 12px;
  cursor: pointer;
  color: inherit;
  font: inherit;
}
.kb-hide-option:hover { border-color: var(--kb-accent); color: var(--kb-accent); }
.kb-hide-option:active, .kb-hide-option:focus-visible {
  background: var(--kb-accent);
  border-color: var(--kb-accent);
  color: #fff;
  outline: none;
}
.kb-hide-option:active span, .kb-hide-option:focus-visible span { color: #fff; }
.kb-hide-option span { color: var(--muted); font-size: var(--font-xs); line-height: 1.5; }
.kb-modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(16, 18, 22, 0.46);
  display: grid;
  place-items: center;
  padding: 24px;
  z-index: 40;
}
.kb-modal {
  width: min(720px, 100%);
  max-height: min(80vh, 840px);
  overflow: auto;
  background: var(--canvas);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 20px 22px;
  box-shadow: var(--shadow-quiet);
}
.kb-modal-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }
.kb-modal-head h2 { margin: 4px 0 0; font-size: var(--font-title); }
.kb-drawer {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: min(440px, 94vw);
  z-index: 81;
  display: flex;
  flex-direction: column;
  background: var(--canvas);
  border-left: 1px solid var(--border);
  box-shadow: var(--shadow-quiet);
}
.kb-drawer-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  padding: 16px 16px 12px;
  border-bottom: 1px solid var(--line);
}
.kb-drawer-head h2 { margin: 4px 0 8px; font-size: var(--font-title); }
.kb-drawer-status { margin: 0; }
.kb-drawer-body {
  flex: 1;
  min-height: 0;
  overflow: auto;
  padding: 12px 16px 20px;
  display: grid;
  gap: 10px;
  align-content: start;
}
.kb-drawer-foot {
  padding: 12px 16px 16px;
  border-top: 1px solid var(--line);
}
.kb-preview-meta { display: flex; flex-wrap: wrap; gap: 6px; margin: 12px 0; }
.kb-preview-subject { margin: 0 0 10px; font-size: var(--font-sm); }
.kb-preview-subject span { color: var(--muted); margin-right: 8px; font-size: var(--font-xs); }
.kb-provenance {
  display: grid;
  gap: var(--space-1);
  padding-top: var(--space-2);
  border-top: 1px solid var(--line);
}
.kb-provenance-title { margin: 0; color: var(--muted); font-size: var(--font-sm); }
.kb-provenance-grid {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: var(--space-1) var(--space-3);
  margin: 0;
  font-size: var(--font-ui);
}
.kb-provenance-grid > div { display: contents; }
.kb-provenance-grid dt { color: var(--muted); font-size: var(--font-sm); }
.kb-provenance-grid dd { margin: 0; color: var(--text); }
.kb-preview-body {
  white-space: pre-wrap;
  font-size: var(--font-body);
  line-height: 1.65;
  background: var(--chrome);
  border: 1px solid var(--line);
  padding: 14px 16px;
  border-radius: var(--radius-sm);
  margin: 0;
}
.admin-kb { display: grid; gap: var(--space-4); }
.kb-hero-admin h2 { font-size: var(--font-page-title); }
.kb-step { padding: 18px 20px; border-radius: var(--radius-md); }
.kb-step-head { display: flex; gap: 12px; align-items: flex-start; margin-bottom: 12px; }
.kb-step-n {
  width: 28px;
  height: 28px;
  border-radius: var(--radius-sm);
  background: var(--kb-accent);
  color: var(--accent-fg);
  display: grid;
  place-items: center;
  font-size: var(--font-sm);
  font-weight: 700;
  flex: 0 0 auto;
}
.kb-step-head h2 { margin: 0 0 4px; font-size: var(--font-section); }
.kb-subhead { margin: 16px 0 8px; font-size: var(--font-meta); font-weight: 500; letter-spacing: 0; color: var(--muted); }
.kb-upload input[type="file"] {
  display: block;
  width: 100%;
  border: 1px dashed var(--line);
  border-radius: var(--radius-sm);
  padding: 12px;
  background: var(--chrome);
  color: var(--text);
  cursor: pointer;
}
.kb-inline-form { max-width: none; margin-top: 8px; }
.kb-asset {
  border-top: 1px solid var(--line);
  padding: 14px 0 6px;
}
.kb-asset.is-open {
  border-color: var(--kb-accent);
  box-shadow: inset 4px 0 0 var(--kb-accent);
  padding-left: 12px;
}
.kb-asset-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }
.kb-versions {
  margin: 10px 0 0;
  padding: 10px 12px;
  list-style: none;
  background: color-mix(in srgb, var(--accent) 6%, var(--bg));
  border: 1px solid color-mix(in srgb, var(--accent) 22%, var(--border));
  border-radius: var(--radius-sm);
  color: var(--text);
  font-size: var(--font-sm);
}
.kb-versions li { margin: 4px 0; }
.kb-transfer { margin-top: 10px; }
.kb-stat-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }
.kb-stat {
  background: var(--chrome);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  padding: 14px;
}
.kb-stat strong { display: block; font-size: 28px; letter-spacing: -0.02em; color: var(--kb-accent); }
.kb-stat p { margin: 4px 0 6px; font-weight: 600; font-size: var(--font-sm); }
.kb-stat span { color: var(--muted); font-size: var(--font-xs); line-height: 1.5; }
@media (max-width: 820px) {
  .kb-stat-grid { grid-template-columns: 1fr; }
  .kb-asset-head { flex-direction: column; }
}
.list-page.skills-page { max-width: none; }
.skill-funnel { display: grid; gap: 10px; }
.skill-funnel-head {
  display: flex;
  align-items: baseline;
  gap: 10px;
}
.skill-funnel-head h2 {
  margin: 0;
  font-size: var(--font-section);
  font-weight: 600;
}
.skill-funnel-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}
@media (max-width: 720px) {
  .skill-funnel-grid { grid-template-columns: 1fr; }
}
.skill-summary { margin: 0 0 8px; min-height: 36px; }
.skill-card-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}
.sop-editor { display: grid; gap: 10px; }
.sop-field {
  display: grid;
  gap: 6px;
  font-size: var(--font-ui);
}
.sop-field input,
.sop-field textarea {
  font: inherit;
  font-size: var(--font-body);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 8px 10px;
  background: var(--canvas);
  color: var(--text);
}
.sop-field textarea { font-family: var(--mono); line-height: 1.45; resize: vertical; }
.sop-list {
  list-style: none;
  margin: 10px 0 0;
  padding: 0;
  display: grid;
  gap: 6px;
}
.sop-list li {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: var(--font-sm);
}
.sop-list .btn { margin-top: 0; margin-left: auto; }
.panel {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 12px 14px;
  box-shadow: none;
}
.expert-page .panel,
.settings-page .panel,
.crawl-plan-card,
.crawl-status-card,
.crawl-results {
  background: var(--bg);
  border-color: var(--border);
  border-radius: 0;
  box-shadow: none;
}
.panel h3 { margin: 0 0 8px; }
.panel .btn { margin-top: 8px; }
.agent-page .panel .btn { margin-top: 0; }
.panel.actions, .actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.muted { color: var(--muted); font-size: var(--font-sm); }
.error { color: var(--red); font-size: var(--font-sm); }
[data-confirm-stage-feedback] { margin: 8px 0 0; line-height: 1.45; }
.error-card {
  background: color-mix(in srgb, var(--danger) 8%, var(--bg));
  border: 1px solid color-mix(in srgb, var(--danger) 35%, var(--border));
  border-radius: var(--radius-sm);
  padding: 10px 12px;
  font-size: var(--font-sm);
}
.error-card strong { display: block; margin-bottom: 6px; color: var(--red); font-family: var(--sans); font-size: var(--font-ui); letter-spacing: 0; }
.badge-red {
  display: inline-block;
  background: var(--red);
  color: #fff;
  font-size: var(--font-xs);
  letter-spacing: 0;
  border-radius: 2px;
  padding: 1px 6px;
  margin-left: 6px;
}
.chip-row { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 8px; }
.hidden-connector { text-decoration: line-through; opacity: 0.55; }
.kol-card.exception { border-color: rgba(196, 60, 60, 0.45); }
.exception-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: #fdf4f4;
  border: 1px solid rgba(196, 60, 60, 0.3);
  border-radius: 8px;
  padding: 8px 10px;
  margin: 12px 0 16px;
}

.session-shell {
  /* 右栏宽度与收起宽度＝今日任务工作台同一组 token（styles.css :root，DESIGN §Home 几何）。 */
  --scope-task-rail-width: clamp(
    var(--workspace-result-rail-min),
    var(--workspace-result-rail-ideal),
    var(--workspace-result-rail-max)
  );
  display: grid;
  grid-template-columns: minmax(0, 1fr) var(--scope-task-rail-width);
  align-items: stretch;
  flex: 1;
  height: 100%;
  min-height: 0;
  min-width: 0;
  /* 工作区几何＝今日任务 .home-stage：内容上限 --content-max、两侧 --page-gutter。
     同一段可用宽度才会让中栏/右栏切出与今日任务相同的宽度。 */
  width: min(100%, var(--content-max));
  margin-inline: auto;
  padding-inline: var(--page-gutter);
  overflow: hidden;
  background: var(--canvas);
}
.session-shell.has-tasklist {
  grid-template-columns: var(--tasklist-width, 260px) minmax(0, 1fr) var(--scope-task-rail-width);
}
.session-shell:has(.side-workbench.is-collapsed) { grid-template-columns: minmax(0, 1fr) var(--workspace-result-rail-collapsed); }
.session-shell.has-tasklist:has(.side-workbench.is-collapsed) {
  grid-template-columns: var(--tasklist-width, 260px) minmax(0, 1fr) var(--workspace-result-rail-collapsed);
}
.session-shell.no-workbench { grid-template-columns: minmax(0, 1fr); }
.session-shell.has-tasklist.no-workbench { grid-template-columns: var(--tasklist-width, 260px) minmax(0, 1fr); }
.session-center {
  display: flex;
  flex-direction: column;
  padding: 4px 28px 24px 0;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}
.agent-task-list {
  position: relative;
  border-right: 1px solid var(--line);
  background: var(--chrome);
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  padding: 12px 10px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.tasklist-resizer {
  position: absolute;
  top: 0;
  right: 0;
  width: 14px;
  height: 100%;
  cursor: col-resize;
  z-index: 5;
  touch-action: none;
}
.tasklist-resizer::after {
  content: "";
  position: absolute;
  top: 12px;
  bottom: 12px;
  right: 5px;
  width: 1px;
  border-radius: 0;
  background: var(--border);
}
.tasklist-resizer:hover,
.agent-task-list.is-resizing .tasklist-resizer {
  background: color-mix(in srgb, var(--text) 6%, transparent);
}
.tasklist-resizer:hover::after,
.agent-task-list.is-resizing .tasklist-resizer::after {
  width: 1px;
  background: var(--border-strong);
}
.tasklist-refresh-hint {
  overflow: hidden;
  color: var(--muted);
  font-size: var(--font-xs);
  line-height: 28px;
  text-align: center;
  height: 0;
}
.tasklist-refresh-hint.is-on { color: var(--accent-text); }
.agent-task-scroll {
  flex: 1;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.agent-task-scroll::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}
.agent-task-list header {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.agent-task-list header strong { font-size: var(--font-ui); }
.agent-task-list header small {
  color: var(--accent-text);
  font-size: var(--font-xs);
}
.agent-task-list header input {
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 6px 8px;
  font: inherit;
  background: var(--canvas);
}
.agent-task-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}
.agent-task-filters button {
  border: 1px solid var(--line);
  background: var(--canvas);
  border-radius: var(--ds-radius-tag);
  padding: 2px 7px;
  font: inherit;
  font-size: var(--font-xs);
  color: var(--muted);
  cursor: pointer;
}
.agent-task-filters button.is-on {
  border-color: var(--accent);
  color: var(--accent-text);
  background: color-mix(in srgb, var(--accent) 8%, var(--canvas));
}
.agent-task-list ol { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }
.agent-task-list li a,
.agent-task-list li button {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  width: 100%;
  text-align: left;
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 8px;
  background: transparent;
  color: inherit;
  text-decoration: none;
  font: inherit;
  cursor: pointer;
}
.agent-task-list li.is-current a {
  border-color: color-mix(in srgb, var(--accent) 35%, var(--line));
  background: var(--canvas);
}
.agent-task-list li strong { font-size: var(--font-ui); line-height: 1.35; }
.agent-task-list li em { font-style: normal; color: var(--muted); font-size: var(--font-xs); }
.agent-task-list li small { color: var(--muted); font-size: var(--font-xs); }
.agent-task-list [data-mail-row] button {
  position: relative;
  padding-left: 18px;
}
.mail-skeleton-row {
  height: 58px;
  border-radius: var(--ds-radius-input);
  background: linear-gradient(90deg, #f3f4f6 0%, #eceff3 40%, #f3f4f6 80%);
  background-size: 220% 100%;
  animation: mail-skel 1.2s ease-in-out infinite;
}
@keyframes mail-skel {
  0% { background-position: 100% 0; }
  100% { background-position: 0 0; }
}
.agent-task-list [data-mail-row].is-unread button {
  background: color-mix(in srgb, var(--accent) 7%, var(--canvas));
}
.mail-unread-dot {
  position: absolute;
  left: 6px;
  top: 12px;
  width: 8px;
  height: 8px;
  border-radius: 99px;
  background: var(--warning);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--warning) 20%, transparent);
}
.sop-mail-block dd {
  display: grid;
  gap: 10px;
}
.sop-mail-md {
  width: 100%;
  min-width: 0;
  padding: 0;
  background: transparent;
}
.sop-mail-md small {
  color: var(--muted);
  font-size: var(--font-sm);
}
.sop-mail-icon {
  font-size: var(--ds-font-body);
  line-height: 1.4;
}
[data-compose-loop] [data-kind="email-card"] {
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid var(--line);
}

/* 2026 workbench visual pass
   Geometry is intentionally centralized here so the shell, conversation and
   composer share one rhythm without changing business behavior. */
:root {
  --left-width: 260px; /* ChatGPT desktop rail (--sidebar-width / w-[260px]); mobile drawers keep their own width */
  --page-gutter: clamp(16px, 2.4vw, 40px);
  --content-max: 1200px;
  --conversation-measure: 900px;
  /* DESIGN §10.2/§10.4：「在底部」的判定阈值，跟随逻辑与新内容提示共用同一个数。 */
  --feed-follow-threshold: 48px;
  --scrollbar-size: 6px;
  --layer-popover: 40;
  --layer-drawer: 60;
  --layer-modal: 80;
}

html,
body,
#root {
  min-width: 320px;
}

body {
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

.workbench {
  grid-template-columns: var(--left-width) minmax(0, 1fr);
}

.sidebar {
  width: var(--left-width);
  min-width: var(--left-width);
  padding: 12px 0 12px 16px;
  gap: 12px;
}

.session-stream,
.side-body,
.pipeline-drawer-body,
.kb-drawer-body,
.agent-task-scroll,
.work-panel .today-workbench,
.work-panel .task-catalog {
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--text) 28%, transparent) transparent;
}

.session-stream::-webkit-scrollbar,
.side-body::-webkit-scrollbar,
.pipeline-drawer-body::-webkit-scrollbar,
.kb-drawer-body::-webkit-scrollbar,
.agent-task-scroll::-webkit-scrollbar,
.work-panel .today-workbench::-webkit-scrollbar,
.work-panel .task-catalog::-webkit-scrollbar {
  width: var(--scrollbar-size);
  height: var(--scrollbar-size);
}

.session-stream::-webkit-scrollbar-track,
.side-body::-webkit-scrollbar-track,
.pipeline-drawer-body::-webkit-scrollbar-track,
.kb-drawer-body::-webkit-scrollbar-track,
.agent-task-scroll::-webkit-scrollbar-track,
.work-panel .today-workbench::-webkit-scrollbar-track,
.work-panel .task-catalog::-webkit-scrollbar-track {
  background: transparent;
}

.session-stream::-webkit-scrollbar-thumb,
.side-body::-webkit-scrollbar-thumb,
.pipeline-drawer-body::-webkit-scrollbar-thumb,
.kb-drawer-body::-webkit-scrollbar-thumb,
.agent-task-scroll::-webkit-scrollbar-thumb,
.work-panel .today-workbench::-webkit-scrollbar-thumb,
.work-panel .task-catalog::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, var(--text) 28%, transparent);
  border-radius: var(--radius-full);
}

.session-stream::-webkit-scrollbar-thumb:hover,
.side-body::-webkit-scrollbar-thumb:hover,
.pipeline-drawer-body::-webkit-scrollbar-thumb:hover,
.kb-drawer-body::-webkit-scrollbar-thumb:hover,
.agent-task-scroll::-webkit-scrollbar-thumb:hover,
.work-panel .today-workbench::-webkit-scrollbar-thumb:hover,
.work-panel .task-catalog::-webkit-scrollbar-thumb:hover {
  background: color-mix(in srgb, var(--text) 44%, transparent);
}

/* The task rail used to hide its scrollbar entirely; keep it discoverable while scrolling. */
.agent-task-scroll::-webkit-scrollbar {
  display: block;
  width: var(--scrollbar-size);
  height: var(--scrollbar-size);
}

.main > :not(.ontology-workspace):not(.perf-ant-app):not(.perf-workspace):not(.session-shell):not(.session-workspace):not(.home-pane):not(.admin-shell):not(.skill-catalog-page):not(.kbv-page):not(.tasks-page) {
  width: 100%;
  max-width: var(--content-max);
  margin-inline: auto;
  padding-inline: var(--page-gutter);
}

.session-shell {
  position: relative;
}

.session-center {
  /* 与今日任务工作台同一段中栏几何：外缘留白交给 shell 的 --page-gutter，
     中栏自己不出内边距（滚动区与 dock 各带 16px 右内边距）。 */
  padding: 0;
}

.task-detail-header {
  flex: 0 0 auto;
  padding: 4px 0 8px;
  margin: 0 0 8px;
  border-bottom: 1px solid var(--ds-border);
  background: var(--bg);
}

.session-stream.conversation {
  padding: 4px 16px 16px 0;
  scroll-padding-block: 8px;
}

.session-center .conversation-content {
  width: min(100%, var(--content-max));
  max-width: var(--content-max);
  margin-inline: auto;
  gap: 24px;
}

.session-center .message.is-user {
  max-width: min(42rem, 78%);
  border-radius: var(--ds-radius-section);
  padding: 10px 14px;
}

.session-center .message.result-card {
  border-radius: var(--radius-md);
  padding: var(--space-2) var(--space-3);
  box-shadow: var(--shadow-quiet);
}

.session-composer {
  padding: 0 var(--page-gutter) max(12px, env(safe-area-inset-bottom));
  border-top: 0;
  background: var(--bg);
}

.session-composer.prompt-input .composer.composer--workspace {
  width: min(100%, var(--content-max));
  margin-inline: auto;
  min-height: 88px;
  max-height: var(--composer-max-height, 420px);
  border-radius: 22px;
  padding: 12px 16px 10px;
  box-shadow: var(--shadow-quiet);
}

.session-composer.prompt-input .composer.composer--workspace textarea {
  min-height: 40px;
  font-size: var(--font-body);
  line-height: 24px;
}

.tier-control,
.composer-stop {
  min-width: 40px;
  min-height: 40px;
}

.composer-tool {
  min-width: 32px;
  min-height: 32px;
}

.composer-plus,
.send-arrow {
  width: 36px;
  height: 36px;
  min-width: 36px;
  min-height: 36px;
}

.composer textarea::placeholder {
  font-size: var(--font-body);
  line-height: 24px;
  color: #8a8a8a;
}

.admin-confirm-layer {
  z-index: var(--layer-modal);
  padding: 24px;
}

.admin-confirm {
  width: min(560px, 100%);
  max-height: calc(100dvh - 48px);
  overflow-y: auto;
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 18px 50px color-mix(in srgb, var(--text) 16%, transparent);
}

.admin-confirm-actions .btn {
  min-height: 44px;
}

/* 员工停用确认：紧凑三区（人员信息 / 影响说明 / 操作），宽度取弹窗小档。 */
[data-admin-confirm="user-deactivate"] .admin-confirm {
  width: min(var(--dialog-w-sm), 100%);
  gap: var(--space-4);
  padding: var(--dialog-pad-t) var(--dialog-pad-x) var(--dialog-pad-b);
}

[data-admin-confirm="user-deactivate"] .admin-confirm-person-card {
  display: grid;
  gap: var(--space-4);
}

[data-admin-confirm="user-deactivate"] .admin-confirm-person-card p {
  margin: 0;
}

[data-admin-confirm="user-deactivate"] .admin-confirm-identity,
[data-admin-confirm="user-deactivate"] .admin-confirm-impact {
  display: grid;
  gap: var(--space-1);
}

[data-admin-confirm="user-deactivate"] .admin-confirm-person,
[data-admin-confirm="user-deactivate"] .admin-confirm-scope-line {
  display: flex;
  align-items: baseline;
  gap: var(--space-2);
  margin: 0;
  font-size: var(--ds-font-body);
  line-height: var(--ds-line-body);
  overflow-wrap: anywhere;
}

[data-admin-confirm="user-deactivate"] .admin-confirm-person strong {
  font-weight: 600;
}

[data-admin-confirm="user-deactivate"] .admin-confirm-identity .muted,
[data-admin-confirm="user-deactivate"] .admin-confirm-impact .muted {
  font-size: var(--ds-font-sm);
  line-height: var(--ds-line-body);
}

[data-admin-confirm="user-deactivate"] .admin-confirm-actions .btn {
  min-height: var(--control-h-form);
}

@media (pointer: coarse) {
  [data-admin-confirm="user-deactivate"] .admin-confirm-actions .btn {
    min-height: 44px;
  }
}

.pipeline-drawer,
.kb-drawer,
.work-panel {
  z-index: var(--layer-drawer);
}

.pipeline-drawer,
.kb-drawer {
  width: min(440px, 94vw);
}

@media (max-width: 1199px) {
  /* 窄视口右栏改成抽屉：工作区铺满，不再保留 --page-gutter 与内容上限。 */
  .session-shell {
    width: 100%;
    padding-inline: 0;
  }

  .session-shell,
  .session-shell.has-tasklist {
    grid-template-columns: minmax(0, 1fr);
  }

  .session-shell:has(.side-workbench.is-collapsed),
  .session-shell.has-tasklist:has(.side-workbench.is-collapsed) {
    grid-template-columns: minmax(0, 1fr) var(--workspace-result-rail-collapsed);
  }

  /* 窄视口右栏改为抽屉（本页既有行为）：宽度与桌面收起档同源 token。 */
  .session-shell .side-workbench:not(.is-collapsed) {
    position: absolute;
    inset: 0 0 0 auto;
    width: min(440px, 92vw);
    z-index: var(--layer-drawer);
    box-shadow: -16px 0 36px color-mix(in srgb, var(--text) 12%, transparent);
  }

  .agent-task-list {
    display: none;
  }
}

@media (max-width: 720px) {
  :root {
    --page-gutter: 16px;
    --scrollbar-size: 4px;
  }

  .mobile-top {
    min-height: 48px;
    padding-inline: 12px;
  }

  .sidebar {
    top: 48px;
    /* Mobile drawer only — do not inherit the desktop 260 rail. */
    width: min(320px, calc(100vw - 24px));
    min-width: 0;
    max-width: none;
  }

  .session-center {
    padding: 4px 16px 16px 0;
  }

  .session-stream.conversation {
    padding: 4px 16px 16px 0;
    scroll-padding-block: 8px;
  }

  .task-detail-header {
    padding: 0 0 8px;
  }

  .session-head-row {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .session-center .message.is-user {
    max-width: 88%;
  }

  .session-center .message.result-card {
    padding: 16px;
    border-radius: var(--ds-radius-section);
  }

  .session-composer {
    padding-inline: var(--page-gutter);
    padding-bottom: max(10px, env(safe-area-inset-bottom));
  }

  .session-composer.prompt-input .composer.composer--workspace {
    min-height: 80px;
    border-radius: 20px;
    padding: 10px 12px 8px;
  }

  .composer-plus,
  .send-arrow {
    width: 40px;
    height: 40px;
    min-width: 40px;
    min-height: 40px;
  }

  .session-shell .side-workbench:not(.is-collapsed) {
    inset: 0 0 0 8%;
    width: 92%;
  }

  .admin-confirm-layer {
    place-items: end center;
    padding: 12px;
  }

  .admin-confirm {
    width: 100%;
    max-height: calc(100dvh - 24px);
    border-radius: var(--ds-radius-section);
    padding: 20px 16px max(20px, env(safe-area-inset-bottom));
  }

  .admin-confirm-actions {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .admin-confirm-actions .btn {
    width: 100%;
  }
}

