}
.side-body [data-tab] + [data-tab] {
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid var(--ds-border);
}
/* 右栏＝今日任务右栏同一套 token：aside 同时挂 .scope-task-rail /.is-collapsed，
   外缘 hairline、栏内留白、收起按钮几何直接复用 today-plan-board.css 的规则，
   这里只保留「一栏一条滚动轴」需要的 flex 链，不另写第二套尺寸。 */
.side-workbench {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  background: var(--bg);
}
.side-workbench.scope-task-rail {
  display: flex;
  flex-direction: column;
  padding: 4px 0 24px 8px;
  border-left: 1px solid var(--ds-border);
}
.side-workbench.scope-task-rail > .scope-task-rail-toggle {
  align-self: flex-start;
  width: var(--icon-btn);
  height: var(--icon-btn);
  min-width: var(--icon-btn);
  min-height: var(--icon-btn);
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  border: 0;
  border-radius: var(--radius-control);
  background: none;
  color: var(--text);
  cursor: pointer;
}
.side-workbench.scope-task-rail > .scope-task-rail-toggle:hover {
  background: var(--surface-hover);
}
.side-workbench.scope-task-rail > .scope-task-rail-toggle:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}
.side-workbench.scope-task-rail > .scope-task-rail-toggle > .scope-task-rail-toggle-icon {
  display: block;
  width: var(--icon-sm);
  height: var(--icon-sm);
  flex: 0 0 auto;
}
.side-workbench.scope-task-rail.is-collapsed {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 46px 6px 16px;
}
.artifact-toolbar { display: flex; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: var(--space-1); padding-bottom: var(--space-2); }
/* 栏首给右上角的收起按钮留出与今日任务一致的口子（--icon-btn + 间距）。 */
.side-workbench .artifact-toolbar { padding-right: calc(var(--icon-btn) + var(--space-1)); }
.icon-btn { border: 0; background: transparent; color: var(--muted); border-radius: 6px; padding: 5px 7px; text-decoration: none; cursor: pointer; font: inherit; font-size: var(--font-sm); white-space: nowrap; min-height: 36px; min-width: 36px; display: inline-flex; align-items: center; justify-content: center; box-sizing: border-box; }
.icon-btn:hover { color: var(--accent-text); background: var(--chrome-2); }
/* 右栏工具条按今日任务的控制尺寸：24px 图标按钮 + 面式 hover + 可见焦点环。 */
.side-workbench .icon-btn {
  min-height: var(--icon-btn);
  min-width: var(--icon-btn);
  padding: 0 var(--space-1);
  border-radius: var(--radius-control);
  color: var(--ds-text-dim);
  font-size: var(--ds-font-helper);
}
.side-workbench .icon-btn:hover { color: var(--text); background: var(--surface-hover); }
.side-workbench .icon-btn:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 2px; }
.share-status { font-size: var(--font-xs); color: var(--muted); background: var(--canvas); border: 1px solid var(--line); border-radius: 8px; padding: 6px 8px; margin-bottom: 8px; }
.share-url { width: 100%; margin-top: 6px; padding: 5px 7px; border: 1px solid var(--line); border-radius: 6px; background: var(--chrome); color: var(--text); font-size: var(--font-xs); }
.link-button { border: 0; background: none; color: var(--accent-text); cursor: pointer; margin-left: 5px; }
.side-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
}
.side-head .page-kicker {
  margin-bottom: 0;
  color: var(--ds-text-dim);
  font-size: var(--ds-font-helper);
  line-height: var(--ds-line-helper);
}
/* 任务状态的唯一表达处：形状 + 文案 + 颜色三条通道同时变（DESIGN §1 不变量 4）。 */
.side-status {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  margin: 6px 0 var(--space-2);
  padding: var(--space-2) var(--space-3);
  border: 1px solid var(--ds-border);
  border-radius: var(--ds-radius-section);
  background: var(--ds-surface);
  font-size: var(--ds-font-helper);
  line-height: var(--ds-line-helper);
  color: var(--text);
  font-family: var(--sans);
}
.side-status .side-status-copy { font-size: var(--ds-font-sm); }
.side-status .side-status-phase,
.side-status .side-status-hint { color: var(--ds-text-dim); flex-basis: 100%; }
.side-status .side-status-debug { flex-basis: 100%; margin-top: 0; }
.status-shape {
  flex: 0 0 auto;
  width: 20px;
  text-align: center;
  font-size: var(--ds-font-sm);
  line-height: var(--ds-line-helper);
  color: var(--ds-text-dim);
}
.status-shape.is-live { color: var(--accent); animation: breath-dot 1.8s ease-in-out infinite; }
.status-shape.is-confirm { color: var(--warning); }
.status-shape.is-done { color: var(--success); }
.status-shape.is-failed { color: var(--danger); }
@media (prefers-reduced-motion: reduce) {
  .status-shape.is-live { animation: none; }
}
/* 结果栏视图切换：只改右栏呈现，不改执行、确认或成果本身。 */
.rail-tabs {
  position: sticky;
  top: 0;
  z-index: 6;
  display: flex;
  gap: var(--workspace-tab-gap);
  margin: 0 0 var(--space-2);
  padding: 0 calc(var(--control-h-sm) + var(--space-1)) 0 0;
  border-bottom: 1px solid var(--border);
  background: var(--bg);
}
.rail-tabs button {
  min-height: var(--workspace-tab-h);
  padding: 0 0 var(--space-2);
  border: 0;
  border-bottom: var(--workspace-tab-indicator-h) solid transparent;
  border-radius: 0;
  background: transparent;
  color: var(--text-quiet);
  font: inherit;
  font-size: var(--ds-font-sm);
  line-height: var(--ds-line-sm);
  cursor: pointer;
  transition: color var(--duration-control), border-color var(--duration-control);
}
.rail-tabs button:hover:not(:disabled) { color: var(--text); }
.rail-tabs button[aria-selected="true"] {
