  font-size: var(--ds-font-xs);
}
.rail-tab-root { min-width: 0; }
.rail-panel { min-width: 0; }
.rail-status-quiet {
  display: grid;
  gap: var(--space-1);
  padding: var(--space-2) 0;
}
.rail-status-quiet strong {
  font-size: var(--ds-font-sm);
  line-height: var(--ds-line-sm);
}
.rail-status-quiet p {
  margin: 0;
  color: var(--text-quiet);
  font-size: var(--ds-font-sm);
  line-height: var(--ds-line-sm);
}
.rail-process {
  margin-top: var(--space-2);
  padding-top: var(--space-2);
  border-top: 1px solid var(--border);
}
.rail-process h3 {
  margin: 0 0 var(--space-1);
  color: var(--text-quiet);
  font-size: var(--ds-font-helper);
  line-height: var(--ds-line-helper);
  font-weight: 600;
}
.rail-process ol {
  display: grid;
  gap: var(--space-1);
  margin: 0;
  padding: 0;
  list-style: none;
}
.rail-process-row {
  display: flex;
  align-items: baseline;
  gap: var(--space-2);
  width: 100%;
  min-width: 0;
  padding: var(--space-1) 0;
  border: 0;
  background: none;
  color: var(--text);
  text-align: left;
  font: inherit;
  cursor: pointer;
}
.rail-process-row time {
  flex: 0 0 auto;
  color: var(--text-quiet);
  font-size: var(--ds-font-xs);
}
.rail-process-row span {
  min-width: 0;
  overflow-wrap: anywhere;
  font-size: var(--ds-font-sm);
  line-height: var(--ds-line-sm);
}
.rail-process-row:hover span { color: var(--accent-text); }
.rail-result-history {
  margin-top: var(--space-3);
  padding-top: var(--space-2);
  border-top: 1px solid var(--border);
}
.rail-result-history > summary {
  cursor: pointer;
  color: var(--accent-text);
  font-size: var(--ds-font-sm);
  line-height: var(--ds-line-sm);
}
.rail-result-history ol {
  display: grid;
  gap: var(--space-1);
  margin: var(--space-2) 0 0;
  padding: 0;
  list-style: none;
}
.rail-debug-list {
  display: grid;
  gap: var(--space-2);
  margin: 0;
}
.rail-debug-list div { display: grid; gap: 0; }
.rail-debug-list dt {
  color: var(--text-quiet);
  font-size: var(--ds-font-helper);
  line-height: var(--ds-line-helper);
}
.rail-debug-list dd {
  margin: 0;
  overflow-wrap: anywhere;
  font-size: var(--ds-font-sm);
  line-height: var(--ds-line-sm);
}
.scope-task-rail .result-tools {
  display: flex;
  justify-content: flex-end;
  margin: 0 0 var(--space-1);
  padding-right: calc(var(--control-h-sm) + var(--space-1));
}
.scope-task-rail .result-tools > summary {
  color: var(--text-quiet);
  font-size: var(--ds-font-helper);
  line-height: var(--ds-line-helper);
}
.side-body {
  flex: 1 1 auto;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
  min-height: 0;
}
.artifact {
  background: transparent;
  border: 0;
  padding: 0;
}
.artifact.mail-body h2 {
  margin: 0 0 12px;
  font-size: var(--font-title);
}
.mail-body-text {
  margin: 0;
  white-space: pre-wrap;
  font: inherit;
  line-height: 1.65;
}
.task-result header {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: var(--space-1) var(--space-2);
}
.task-result header h2 {
  margin: 0;
  font-size: var(--ds-font-sm);
  line-height: var(--ds-line-sm);
}
.task-result-summary {
  margin: 0;
  color: var(--text-quiet);
  font-size: var(--ds-font-sm);
  line-height: var(--ds-line-sm);
}
.result-metrics {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
  gap: var(--space-2);
  margin: var(--space-2) 0;
}
.result-metrics div {
  display: grid;
  gap: var(--space-1);
  padding: var(--space-2) var(--space-3);
  background: var(--canvas);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
}
.result-metrics dt { color: var(--muted); font-size: var(--font-xs); }
.result-metrics dd { margin: 0; color: var(--text); font-size: var(--font-title); font-weight: 600; }
.result-metrics small { color: var(--muted); }
.result-section, .result-actions { border-top: 1px solid var(--line); padding: var(--space-2) 0; }
.result-section h3, .result-actions h3 { margin: 0 0 var(--space-1); font-size: var(--ds-font-sm); line-height: var(--ds-line-sm); }
.result-section ul, .result-actions ol { margin: var(--space-1) 0 0; padding-left: 1.25em; }
.result-section li, .result-actions li { margin: var(--space-1) 0; line-height: var(--ds-line-sm); }
.result-section .md table {
  width: 100%;
