  line-height: var(--ds-line-sm);
}
.result-section .md th,
.result-section .md td {
  padding: var(--space-1) var(--space-2);
  border-bottom: 1px solid var(--border);
  text-align: left;
  vertical-align: top;
}
.result-section .md th {
  color: var(--text-quiet);
  font-weight: 500;
  background: var(--bg-subtle);
}
.result-section .md tr:last-child td { border-bottom: 0; }
.result-section .md { overflow-x: auto; }
.result-actions ol { list-style: none; padding-left: 0; display: flex; flex-wrap: wrap; gap: 8px; }
.result-actions button,
.result-actions a {
