}
.result-actions button:hover,
.result-actions a:hover {
  border-color: var(--control-border-hover);
}
.result-actions button.is-on,
.result-actions a.is-on,
.result-actions button[aria-pressed="true"] {
  background: color-mix(in srgb, var(--accent) 10%, var(--bg));
  color: var(--accent-text);
  border-color: var(--accent);
}
.result-actions li small { display: block; color: var(--muted); }

.crawl-artifact { display: grid; gap: 18px; }
.crawl-plan-card, .crawl-status-card, .crawl-results {
  border: 1px solid var(--border);
  border-radius: 0;
  padding: 14px 0;
  background: var(--bg);
  box-shadow: none;
}
.crawl-plan-card { display: grid; gap: 12px; }
.crawl-plan-card h2, .crawl-status-card h3, .crawl-results h3 { margin: 2px 0 0; font-size: var(--font-section); }
.crawl-plan-card > label { display: grid; gap: 6px; color: var(--muted); font-size: var(--font-xs); }
.crawl-plan-card select, .crawl-plan-card textarea {
  width: 100%;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--chrome);
  color: var(--text);
  padding: 8px 9px;
  font: inherit;
  resize: vertical;
}
.crawl-plan-card fieldset { margin: 0; padding: 0; border: 0; }
.crawl-plan-card legend { margin-bottom: 7px; color: var(--muted); font-size: var(--font-xs); }
.crawl-mode-options { display: flex; flex-wrap: wrap; gap: 7px; }
.crawl-mode-options label { display: flex; align-items: center; gap: 4px; padding: 6px 8px; border: 1px solid var(--line); border-radius: 7px; font-size: var(--font-sm); cursor: pointer; min-height: 36px; }
.crawl-validation { margin: 0; color: var(--danger); font-size: var(--font-xs); line-height: 1.45; }
.crawl-status-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; }
.crawl-job-meta { display: grid; gap: 8px; margin: 14px 0 0; }
.crawl-job-meta div { display: grid; grid-template-columns: 100px minmax(0, 1fr); gap: 8px; font-size: var(--font-xs); }
.crawl-job-meta dt { color: var(--muted); }
.crawl-job-meta dd { margin: 0; overflow-wrap: anywhere; }
.crawl-job-error dd { color: var(--danger); }
.crawl-event-list { margin: 12px 0 0; padding: 10px 10px 10px 28px; border-top: 1px solid var(--line); color: var(--muted); font-size: var(--font-xs); }
.crawl-event-list li { margin: 4px 0; }
.crawl-admin-actions { display: flex; flex-wrap: wrap; gap: 7px; margin-top: 10px; padding-top: 10px; border-top: 1px solid var(--line); }
.candidate-table-wrap { margin-top: 12px; overflow-x: auto; }
.candidate-table { width: 100%; min-width: 650px; border-collapse: collapse; font-size: var(--font-table); font-feature-settings: "tnum" 1; }
.candidate-table th { color: var(--muted); font-weight: 500; text-align: left; }
.candidate-table th, .candidate-table td { padding: 9px 7px; border-bottom: 1px solid var(--line); vertical-align: top; }
.candidate-table td small { display: block; margin-top: 3px; color: var(--muted); white-space: normal; }
.candidate-actions { display: flex; flex-wrap: wrap; gap: 4px; }
.candidate-actions button { border: 1px solid var(--line); border-radius: 6px; background: transparent; color: var(--accent-text); padding: 3px 6px; cursor: pointer; font: inherit; }
.crawl-results > .muted { margin: 10px 0 0; font-size: var(--font-xs); }

.hub-page { display: grid; gap: var(--space-4); max-width: none; width: 100%; }
.hub-chrome {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-4);
  flex-wrap: wrap;
}
.hub-modes {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  color: var(--text);
}
.hub-modes .hub-svg { color: var(--text); }
.hub-svg { width: 18px; height: 18px; flex: 0 0 18px; }
.hub-mode {
  font-size: var(--font-section);
  font-weight: 500;
  color: var(--text-muted);
  text-decoration: none;
}
.hub-mode.on { color: var(--text); font-weight: 600; }
.hub-lead { margin: 0; max-width: 40em; }
.hub-tools { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; }
.hub-search-wrap {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  width: 220px;
  border: 1px solid var(--border);
  border-radius: var(--ds-radius-tag);
  padding: 0 var(--space-3);
  background: var(--bg-elevated);
  color: var(--text-muted);
}
.hub-search-wrap svg { width: 14px; height: 14px; flex: 0 0 14px; }
.hub-search {
  flex: 1;
  min-width: 0;
