  align-items: center;
  gap: var(--space-2);
  border: 1px solid var(--border);
  background: var(--bg);
  color: var(--text);
  border-radius: var(--radius-sm);
  padding: 6px var(--space-3);
  font-size: var(--font-sm);
  text-decoration: none;
}
.hub-mine .hub-svg { width: 14px; height: 14px; }
.hub-mine.on, .hub-mine:hover { background: var(--bg-elevated); }
.hub-new {
  border: 0;
  background: var(--primary);
  color: var(--primary-fg);
  border-radius: var(--radius-sm);
  padding: 7px 14px;
