  background: var(--bg-elevated);
  border: 1px solid var(--border);
  flex: 0 0 40px;
}
.hub-tile-ico-letter { font-size: var(--font-sm); font-weight: 600; }
.hub-glyph { width: 20px; height: 20px; }
.hub-tile-body { min-width: 0; }
.hub-tile-name {
  font-size: var(--font-sm);
  font-weight: 600;
  display: flex;
  align-items: baseline;
  gap: var(--space-2);
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.hub-kind {
  font-size: var(--font-xs);
