.ticket-identity-card { width: min(480px, 100%); display: grid; gap: var(--space-3); padding: clamp(var(--space-4), 4vw, var(--space-6)); background: var(--bg); border: 1px solid var(--border); border-radius: var(--ds-radius-section); box-shadow: var(--shadow-quiet); }
