}
.settings-tabs { display: flex; gap: 4px; flex-wrap: nowrap; overflow-x: auto; border-bottom: 1px solid var(--line); margin-bottom: 18px; }
.settings-tabs.admin-tabs { flex-wrap: wrap; overflow: visible; }
.settings-tabs button { border: 0; border-bottom: 2px solid transparent; background: none; padding: 9px 12px; cursor: pointer; color: var(--muted); font: inherit; font-size: var(--font-ui); white-space: nowrap; min-height: 36px; }
.settings-tabs button.active { color: var(--accent-text); border-color: var(--accent); font-weight: 500; }
.settings-form { display: grid; gap: 14px; max-width: 780px; }
.ticket-binding-form { display: grid; grid-template-columns: minmax(14rem, 1fr) minmax(14rem, 1fr); gap: var(--space-3); align-items: end; margin-top: var(--space-3); max-width: 980px; }
