.check { display: flex; align-items: center; gap: 7px; font-size: var(--font-ui); }
.status-ok { color: var(--ok); font-size: var(--font-body); }
.section-head, .admin-header, .admin-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.memory-editor { display: grid; gap: 8px; border-top: 1px solid var(--line); padding-top: 14px; }
.summary-list { display: grid; gap: 1px; margin: 0; background: var(--line); border: 1px solid var(--line); }
.summary-list div { display: grid; grid-template-columns: 180px 1fr; background: var(--canvas); padding: 8px; }
.summary-list dt { color: var(--muted); }.summary-list dd { margin: 0; overflow-wrap: anywhere; }
.admin-header { margin-bottom: 14px; align-items: flex-start; }.admin-return { position: sticky; top: 8px; z-index: 5; }
.admin-header { gap: var(--space-3); margin-bottom: var(--space-3); align-items: center; }
.admin-shell h2 { font-size: var(--ds-font-ui); font-weight: 600; line-height: var(--ds-line-ui); }
.admin-shell .field { gap: var(--space-1); font-size: var(--ds-font-helper); line-height: var(--ds-line-helper); }
.admin-shell .field input,
.admin-shell .field textarea,
.admin-shell .field select {
  min-height: var(--control-h-lg);
