.admin-row { border-top: 1px solid var(--line); padding: 10px 0; }.admin-row p { margin: 3px 0; }
.shared-page { height: 100%; overflow: auto; width: min(800px, 100%); margin: auto; padding: 32px 24px; }
.shared-page .chat { margin-top: 24px; }

@media (max-height: 800px) {
  .home-stage { padding-top: 20px; }
  .composer--workspace { min-height: 72px; }
  .home-pane.is-composer-focused .composer--workspace { min-height: 80px; }
}
@media (max-width: 860px) {
  .mobile-top {
    display: flex;
    gap: 12px;
    align-items: center;
    padding: 10px 14px;
    background: var(--chrome);
    border-bottom: 1px solid var(--line);
    font-size: var(--font-sm);
    min-height: 40px;
  }
  .mobile-top a { color: var(--accent-text); min-height: 36px; display: inline-flex; align-items: center; }
  .workbench { grid-template-columns: 1fr; grid-template-rows: auto minmax(0, 1fr); }
  .sidebar { display: none; position: fixed; z-index: 100; top: 45px; bottom: 0; left: 0; height: auto; width: min(300px, 88vw); min-width: 0; max-width: none; box-shadow: var(--shadow-quiet); border-right: 1px solid var(--border); }
  .sidebar.mobile-open { display: flex; }
  .home-hero h1 { font-size: var(--font-title); margin: var(--space-2) 0 var(--space-3); }
  .home-stage { padding: 20px 16px 12px; }
  .kol-card-fields.is-compact {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .home-composer-dock { width: 100%; padding: 8px 16px 14px; }
  .composer--workspace { min-height: 80px; }
  .board { grid-template-columns: repeat(2, minmax(140px, 1fr)); }
  .pipeline-kv { grid-template-columns: 72px minmax(0, 1fr); }
  .pipeline-drawer { width: min(100vw, 420px); }
  .kb-drawer { width: min(100vw, 440px); }
  .list-page.kb-page.has-drawer { padding-right: 0; }
  .main { padding: 0; }
  .main > :not(.ontology-workspace):not(.perf-ant-app):not(.perf-workspace):not(.session-shell):not(.session-workspace):not(.home-pane):not(.admin-shell):not(.kbv-page):not(.tasks-page) { padding: 16px 14px 36px; }
  /* 管理面在窄视口与员工端同规则：导航走 .sidebar 抽屉（由 .mobile-top ☰ 打开），
     不再把导航压成横向顶条。 */
  .admin-body { padding: var(--space-3) var(--space-3) var(--space-5); }
  .session-shell,
  .session-shell.has-tasklist,
  .session-shell:has(.side-workbench.is-collapsed),
  .session-shell.has-tasklist:has(.side-workbench.is-collapsed) { grid-template-columns: minmax(0, 1fr) var(--workspace-result-rail-collapsed); }
  .agent-task-list { display: none; }
  .side-workbench:not(.is-collapsed) { position: absolute; z-index: 60; inset: 45px 0 0 12%; box-shadow: var(--shadow-quiet); }
  .composer-dock { padding: 8px 12px 16px; }
  .composer-shortcut { display: none; }
  .cascade-menu { width: min(270px, calc(100vw - 34px)); }
  .cascade-submenu { left: 0; bottom: calc(100% + 8px); width: min(310px, calc(100vw - 34px)); }
  .form-grid, .admin-grid { grid-template-columns: 1fr; }
  .admin-header { align-items: flex-start; }
  .admin-form-grid { grid-template-columns: 1fr; }
  .kol-portrait { grid-template-columns: minmax(0, 1fr); }
}

.kol-journey {
  margin: 8px 0 12px;
  padding: 0;
  width: 100%;
