/* Assistant-first followed-KOL result. This is a report stream, not a card wall. */
.followed-agent-report {
  inline-size: min(100%, 60rem);
  margin-inline: auto;
  padding: clamp(1rem, 2.4vw, 2rem) clamp(.25rem, 1.4vw, 1rem) clamp(2rem, 4vw, 3rem);
  color: var(--text);
  overflow-wrap: anywhere;
}
.agent-report-head {
  display: grid;
  gap: var(--space-2);
  padding-block-end: clamp(1rem, 2vw, 1.5rem);
  border-block-end: 1px solid var(--border);
}
.agent-report-agent-line,
.agent-report-complete {
  margin: 0;
  color: var(--text-muted);
  font-size: var(--font-sm);
  line-height: var(--leading-body);
}
.agent-report-glyph { margin-inline-end: var(--space-2); color: var(--text-muted); }
.agent-report-head .page-conclusion,
.agent-report-details h3,
.agent-report-next h3 {
  margin: 0;
  color: var(--text);
  font-weight: 500;
}
.agent-report-head .page-conclusion { font-size: 18px; line-height: var(--leading-tight); }
.agent-report-summary { margin: 0; font-size: var(--font-body); line-height: var(--leading-body); }
.agent-report-details { min-inline-size: 0; }
.agent-report-details > h3,
.agent-report-next > h3 { margin-block: clamp(1.25rem, 2.6vw, 2rem) var(--space-2); font-size: var(--font-section); }
.agent-report-entry {
  display: grid;
  gap: var(--space-2);
  min-inline-size: 0;
  margin-block: 0 var(--space-3);
  padding: 12px 14px;
  border: 1px solid #eee;
  border-radius: var(--ds-radius-section);
  background: var(--bg);
}
.agent-report-entry-head {
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr) auto;
  align-items: baseline;
  gap: var(--space-2);
  min-inline-size: 0;
}
.agent-report-index { color: var(--text-muted); font-variant-numeric: tabular-nums; }
.agent-report-avatar {
  display: inline-grid;
  place-items: center;
  inline-size: 1.75rem;
  block-size: 1.75rem;
  border-radius: 50%;
  background: var(--bg-elevated);
  color: var(--text-muted);
  font-size: var(--font-sm);
  font-weight: 600;
}
.agent-report-identity { display: grid; gap: 2px; min-inline-size: 0; }
.agent-report-identity strong { font-size: var(--font-body); font-weight: 600; overflow-wrap: anywhere; }
.agent-report-identity span,
.agent-report-count,
.agent-report-fact p,
.agent-report-tags p { color: var(--text-muted); font-size: var(--font-sm); line-height: var(--leading-body); }
.agent-report-count { white-space: nowrap; }
.agent-report-fact,
.agent-report-tags,
.agent-report-actions { padding-inline-start: clamp(3.5rem, 6vw, 4.5rem); }
.agent-report-fact { display: grid; gap: 2px; }
.agent-report-fact p,
.agent-report-tags p,
.agent-report-evidence { margin: 0; }
.agent-report-tags { display: grid; gap: 2px; }
.agent-report-tags p > span { color: var(--text-muted); }
.agent-report-evidence {
  color: var(--text-muted);
  font-size: var(--font-sm);
  line-height: 20px;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.agent-report-mail-link,
.agent-report-action,
.agent-report-detail-link,
.agent-report-waiting {
  min-block-size: 2rem;
  border: 0;
  padding: 0;
  background: transparent;
  color: var(--text-muted);
  font: inherit;
  font-size: var(--font-sm);
  font-weight: 400;
  line-height: var(--leading-body);
  cursor: pointer;
  text-decoration: none;
}
.agent-report-mail-link { min-block-size: auto; color: var(--text-muted); }
.agent-report-mail-link:hover,
.agent-report-action:hover,
.agent-report-detail-link:hover,
.agent-report-waiting:hover { color: var(--text); }
.agent-report-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1) var(--space-3);
  align-items: center;
}
.agent-report-action-primary { color: var(--accent-text); font-weight: 500; }
.agent-report-detail-link { color: var(--text-muted); text-decoration: underline; text-underline-offset: .15em; }
.agent-report-next { border-block-end: 1px solid var(--border); }
.agent-report-next-links { display: flex; flex-wrap: wrap; gap: var(--space-2) var(--space-4); }
.agent-report-waiting { margin-block: var(--space-2) var(--space-3); text-decoration: none; }
.agent-report-action:focus-visible,
.agent-report-detail-link:focus-visible,
.agent-report-mail-link:focus-visible,
.agent-report-waiting:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 2px; border-radius: var(--radius-sm); }
@media (max-width: 48rem) {
  .followed-agent-report { padding-inline: var(--space-2); }
  .agent-report-entry-head { grid-template-columns: auto auto minmax(0, 1fr); }
  .agent-report-count { grid-column: 3; white-space: normal; }
  .agent-report-fact,
  .agent-report-tags,
  .agent-report-actions { padding-inline-start: calc(2.25rem + var(--space-2)); }
  .agent-report-next-links { display: grid; gap: var(--space-1); }
}
.kol-journey-title h1 { margin: 0; font-size: var(--font-title); }
.session-stage-chip {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  border: 1px solid color-mix(in srgb, var(--accent) 28%, var(--border));
  background: color-mix(in srgb, var(--accent) 8%, var(--bg));
  color: var(--accent-text);
  border-radius: var(--ds-radius-tag);
  padding: 2px 10px;
  font-size: var(--font-meta);
  font-weight: 600;
  line-height: 1.5;
  white-space: nowrap;
}
.session-stage-chip small {
  color: var(--text-muted);
  font-weight: 500;
  font-size: var(--font-xs);
}
.journey-track { margin: 8px 0 0; }
.stage-track.is-phases.journey-track {
  display: grid;
  grid-template-columns: repeat(8, minmax(0, 1fr));
  align-items: start;
  gap: 6px 0;
  position: relative;
}
.stage-track.is-phases.journey-track::before {
  display: block;
  content: "";
  position: absolute;
  left: 6%;
  right: 6%;
  top: 5px;
  height: 2px;
  background: var(--border);
  z-index: 0;
}
.stage-track.is-phases.journey-track::after {
  content: "";
  position: absolute;
  left: 6%;
  top: 5px;
  height: 2px;
  width: calc((100% - 12%) * var(--phase-progress, 0));
  background: var(--accent-text);
  z-index: 0;
}
.stage-track.is-phases.journey-track li {
  flex: none;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  position: relative;
  z-index: 1;
}
.phase-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--ds-radius-tag);
  padding: 3px 6px;
  font-size: var(--font-xs);
  line-height: 1.4;
  border: 1px solid var(--border);
  background: var(--bg);
  color: var(--text-muted);
  white-space: nowrap;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
}
.phase-chip.is-done {
  border-color: color-mix(in srgb, var(--success) 35%, var(--border));
  color: var(--success);
  background: color-mix(in srgb, var(--success) 8%, var(--bg));
}
.phase-chip.is-current {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 10%, var(--bg));
  color: var(--accent-text);
  font-weight: 600;
}
.kol-portrait {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr);
  gap: var(--space-1) var(--space-3);
  align-items: start;
  padding: var(--space-2) var(--space-3);
  font-size: var(--font-sm);
}
.portrait-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-1);
  min-width: 0;
}
.portrait-value,
.portrait-chips {
  min-width: 0;
  font-size: var(--font-sm);
  line-height: 1.4;
}
.portrait-chips {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
}
.portrait-row.is-email .portrait-value {
  color: var(--text);
  word-break: break-all;
}
.portrait-row.is-tags {
  grid-column: 1 / -1;
}
.portrait-row.is-meta {
  color: var(--muted);
  font-size: var(--font-meta);
  gap: var(--space-1);
}
.portrait-sep { color: var(--muted); }
.draft-send-meta {
  display: grid;
  gap: 6px;
  margin: 0 0 10px;
}
.draft-send-meta > div {
  display: grid;
  grid-template-columns: 4.5rem minmax(0, 1fr);
  gap: 8px;
  align-items: start;
  font-size: var(--font-ui);
}
.draft-send-meta dt {
  margin: 0;
  color: var(--text-muted);
  font-size: var(--font-meta);
  line-height: 1.7;
}
.draft-send-meta dd {
  margin: 0;
  min-width: 0;
  word-break: break-word;
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  align-items: center;
}
.kol-stage-sop {
  margin: var(--space-2) 0 0;
  padding: 0;
  padding-inline: 0;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--chrome);
}
.kol-stage-sop > summary {
  cursor: pointer;
  list-style: none;
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: var(--space-2);
  padding: 6px var(--space-3);
  font-size: var(--font-sm);
  font-weight: 650;
  color: var(--text);
}
.kol-stage-sop > summary::-webkit-details-marker { display: none; }
.kol-stage-sop > summary::before {
  content: "▸";
