  gap: 12px;
}
.kol-mail-head time { font-size: var(--font-xs); white-space: nowrap; }
.kol-mail.is-out { margin-left: 28px; border-left: 3px solid var(--accent); }
.kol-mail.is-in { border-left: 3px solid var(--line); }
.kol-mail-body { margin: 0; white-space: pre-wrap; }

/* Final shared-frame overrides stay after the legacy Home media rules. */
.home-pane {
  box-sizing: border-box;
  width: 100%;
  --home-gutter: var(--page-gutter);
}

/* One workspace, one scroll container: the stage scrolls, the page header scrolls
   away with the content, and the board is plain flow inside it. */
.home-stage {
  box-sizing: border-box;
  width: min(100%, var(--content-max));
  margin-inline: auto;
  padding-inline: var(--page-gutter);
  overflow-x: hidden;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--text) 28%, transparent) transparent;
  overscroll-behavior: contain;
  /* 键盘/程序滚动停在卡片之间，不把对象卡切在页脚发丝线上。 */
  scroll-padding-block-end: var(--space-3);
}

.home-composer-dock {
  box-sizing: border-box;
  width: min(100%, var(--content-max));
  margin-inline: auto;
  padding-inline: var(--page-gutter);
  padding-bottom: max(12px, env(safe-area-inset-bottom));
}

.home-composer-dock > .composer-dock {
  width: 100%;
  margin-inline: auto;
}

/* Home desktop frame: one top inset and an explicit shared content cap.
   Do not restore the legacy width:100% / max-width:none exception here.
   DESIGN §27.2 agent-session geometry retains its more-specific discovery
   override in workspace-shell.css; independent session routes are unchanged. */
@media (min-width: 1101px) {
  .home-pane[data-home-workspace] .home-stage {
    width: min(100%, var(--content-max));
    max-width: var(--content-max);
    margin-inline: auto;
    padding-top: var(--space-1);
  }
}

.home-stage::-webkit-scrollbar {
  width: var(--scrollbar-size);
  height: var(--scrollbar-size);
}

.home-stage::-webkit-scrollbar-track {
  background: transparent;
}

.home-stage::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, var(--text) 28%, transparent);
  border-radius: var(--radius-full);
}

@media (max-width: 720px) {
  .home-stage {
    padding-top: 16px;
  }

  .home-composer-dock {
    padding-inline: var(--page-gutter);
    padding-bottom: max(10px, env(safe-area-inset-bottom));
  }
}

/* Last-wins desktop rail. Must stay after every .sidebar / .workbench width rule.
   Descendant (not only >) so the lock still wins if .sidebar is wrapped.
   Mobile drawers above (860 / 720) keep min(300px)/min(320px) and never get 260. */
@media (min-width: 861px) {
  .workbench:not(.sidebar-collapsed) {
    grid-template-columns: 260px minmax(0, 1fr) !important;
  }
  .workbench:not(.sidebar-collapsed) .sidebar {
    width: 260px !important;
    min-width: 260px !important;
    max-width: 260px !important;
    flex: 0 0 260px !important;
    padding-right: 0;
  }
  .workbench:not(.sidebar-collapsed) .sidebar-scroll {
    padding-right: 6px;
    scrollbar-gutter: auto;
    overflow-x: hidden;
    overflow-y: auto;
  }
  .workbench.sidebar-collapsed {
    --left-width: 56px;
    grid-template-columns: 56px minmax(0, 1fr);
  }
  .workbench.sidebar-collapsed .sidebar {
    width: 56px;
    min-width: 56px;
    max-width: 56px;
    overflow-x: hidden;
    padding-right: 0;
  }
  .workbench.sidebar-collapsed .sidebar-scroll {
    padding-right: 0;
    scrollbar-gutter: auto;
  }
  html,
  :root {
    font-family: var(--sans);
    font-size: var(--ds-font-section); /* match ChatGPT root font-size; :root must win over --font-body */
    font-weight: 400;
    color: #1a1a1a;
  }
  body {
    font-family: var(--sans);
    font-size: var(--ds-font-ui);
    font-weight: 400;
    color: var(--text);
  }
  .nav-link,
  .nav-combo,
  .nav-link .sidebar-label,
  .nav-combo a {
    font-size: var(--ds-font-body);
    font-weight: 400;
  }
  .nav-link.active,
  .nav-combo.active {
    font-weight: 500;
    background: var(--color-ash);
  }
  .home-hero h1,
  .page-conclusion,
  .agent-report-head .page-conclusion {
    font-size: 18px;
    font-weight: 500;
  }
  .home-pane h2,
  .task-group h2,
  .work-panel-head h2 {
    font-size: var(--ds-font-ui);
    font-weight: 500;
  }
  .account-name,
  .home-stats,
  [data-kol-scope] {
    font-size: var(--ds-font-sm);
    font-weight: 400;
    color: var(--ds-text-dim);
  }
  .account-name {
    font-weight: 500;
    color: var(--text);
  }
}

.cron-page {
  max-width: var(--content-max);
  gap: var(--space-3);
  min-width: 0;
}
.cron-toolbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-2);
  min-height: var(--control-h-lg);
}
.cron-toolbar h1 { margin: 0 auto 0 0; font-size: var(--ds-font-section); }
.cron-toolbar input, .cron-toolbar select,
.cron-editor input, .cron-editor select {
  min-height: var(--control-h-lg);
  padding: 0 var(--space-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-control);
  background: var(--bg);
  color: var(--text);
  font: inherit;
}
.cron-toolbar input { width: min(12rem, 100%); }
.cron-catalog { gap: 0; border-top: 1px solid var(--border); }
.cron-list-head {
  display: grid;
  grid-template-columns: minmax(12rem, 1fr) minmax(7rem, auto) minmax(13rem, auto) auto;
  gap: var(--space-3);
  padding: var(--space-1);
  color: var(--text-muted);
  font-size: var(--ds-font-helper);
  border-bottom: 1px solid var(--border);
}
.cron-row {
  display: grid;
  grid-template-columns: minmax(12rem, 1fr) minmax(7rem, auto) minmax(13rem, auto) auto;
  align-items: center;
  gap: var(--space-2);
  min-height: 64px;
  padding: var(--space-1);
  border-bottom: 1px solid var(--border);
  min-width: 0;
}
.cron-row-main {
  display: grid;
  gap: 2px;
  min-width: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
  color: inherit;
  text-decoration: none;
}
.cron-row-main strong, .cron-row-main .muted { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cron-row-main strong { font-size: var(--ds-font-body); }
.cron-row-main .muted, .cron-next small { font-size: var(--ds-font-helper); }
.cron-next { display: grid; gap: 2px; font-size: var(--ds-font-sm); }
.cron-next strong { font-weight: 500; }
.cron-next small { color: var(--text-muted); }
.cron-field-label { color: var(--text-muted); font-size: var(--ds-font-helper); }
.cron-status { display: flex; align-items: center; gap: var(--space-1); }
.cron-running-state { padding-inline-start: var(--space-1); border-inline-start: 1px solid var(--border); font-size: var(--ds-font-helper); }
.cron-status { flex-wrap: wrap; row-gap: var(--space-1); }
/* 终端运行状态强提醒：图标 + 文案 + 状态色三者缺一不可（DESIGN.md §3.1、不变量 4），不只靠颜色。 */
.cron-attention {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  min-height: var(--chip-h);
  padding-inline: var(--space-1);
  border-radius: var(--radius-chip-square);
  font-size: var(--ds-font-helper);
  line-height: var(--ds-line-helper);
  font-weight: 600;
  white-space: nowrap;
}
.cron-attention[data-attention="danger"] { color: var(--danger-text); background: color-mix(in srgb, var(--danger) 12%, var(--bg)); }
.cron-attention[data-attention="warning"] { color: var(--warning-text); background: color-mix(in srgb, var(--warning) 12%, var(--bg)); }
.cron-attention-icon { display: inline-flex; }
.cron-attention-link { font-size: var(--ds-font-helper); white-space: nowrap; }
.cron-timeline-item { display: flex; align-items: center; gap: var(--space-1); flex-wrap: wrap; }
.cron-empty { display: flex; align-items: center; gap: var(--space-2); padding-block: var(--space-3); }
.cron-empty p { margin: 0; }
.cron-row-actions { display: flex; gap: var(--space-1); }
.cron-row-actions .btn { white-space: nowrap; }
.cron-row-actions .btn { min-height: var(--control-h-lg); }
.cron-row-feedback { grid-column: 1 / -1; margin: 0; font-size: var(--ds-font-sm); }
.cron-skeleton { height: 72px; border-radius: 0; border-bottom: 1px solid var(--border); }
.cron-editor { display: grid; gap: var(--space-3); min-width: 0; }
.cron-editor > label, .cron-schedule label { display: grid; gap: var(--space-1); font-size: var(--ds-font-sm); }
.cron-editor > label input { max-width: 30rem; }
.cron-schedule { display: flex; flex-wrap: wrap; align-items: end; gap: var(--space-2); }
.cron-editor h3 { margin: 0; font-size: var(--ds-font-ui); }
.link-button { padding: 0; border: 0; background: none; color: var(--accent-text); text-decoration: underline; cursor: pointer; font: inherit; }
.cron-editor .composer .send:has(.composer-submit-label) { width: auto; padding-inline: var(--space-2); gap: var(--space-1); }
.composer-submit-label { font-size: var(--ds-font-sm); }
.cron-row :is(button, a, input, select):focus-visible,
.cron-toolbar :is(button, a, input, select):focus-visible,
.cron-editor :is(button, a, input, select):focus-visible { outline: var(--focus-ring-width) solid var(--focus-ring); outline-offset: var(--focus-ring-offset); }
.cron-template-form { display: grid; gap: var(--space-2); margin-top: var(--space-2); }
.cron-template-form > label { display: grid; gap: var(--space-1); font-size: var(--ds-font-sm); }
.cron-template-form input, .cron-template-form select, .cron-template-form textarea { max-width: 30rem; }
.cron-template-form :is(button, a, input, select, textarea):focus-visible { outline: var(--focus-ring-width) solid var(--focus-ring); outline-offset: var(--focus-ring-offset); }
.cron-template-actions { display: flex; align-items: center; gap: var(--space-2); margin-top: var(--space-2); }
.cron-hero { display: grid; gap: var(--space-2); }
.cron-hero h1 {
  margin: 0;
  font-size: var(--font-page-title);
  line-height: var(--leading-tight);
  font-weight: 600;
}
.cron-hero .muted { margin: 0; max-width: 40em; }
.cron-catalog {
  display: grid;
  gap: var(--space-3);
  min-width: 0;
}
.cron-card {
  display: grid;
  gap: 4px;
  text-align: left;
  width: 100%;
  min-width: 0;
  padding: var(--space-4);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg);
  color: inherit;
  cursor: pointer;
}
.cron-card h3,
.cron-detail h2,
.cron-receipt h3,
.cron-timeline h3 {
  margin: 0;
  font-size: var(--font-section);
  font-weight: 600;
}
.cron-card .muted,
.cron-detail .muted { margin: 0; }
.cron-card.is-selected { border-color: var(--text); }
.cron-card-head {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2) var(--space-3);
  align-items: baseline;
  justify-content: space-between;
}
.cron-status {
  font-size: var(--font-sm);
  color: var(--text-muted);
}
.cron-skeleton {
  height: 92px;
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--text) 6%, var(--bg));
}
.cron-detail,
.cron-receipt,
.cron-timeline {
  display: grid;
  gap: var(--space-3);
  min-width: 0;
}
.cron-detail-head {
  display: grid;
  gap: var(--space-3);
}
.cron-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}
.cron-contract,
.cron-receipt pre {
  margin: 0;
  white-space: pre-wrap;
  word-break: break-word;
  font: inherit;
}
.cron-contract h3 { margin: 0 0 var(--space-1); font-size: var(--ds-font-ui); color: var(--text); }
.cron-contract p { margin: 0 0 var(--space-1); }
.cron-timeline ol {
  margin: 0;
  padding-left: 1.2em;
}
.cron-timeline a { color: inherit; }
@media (min-width: 768px) {
  .cron-detail-head {
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: start;
  }
}
@media (max-width: 1000px) {
  .cron-list-head { display: none; }
  .cron-row { grid-template-columns: minmax(0, 1fr) auto; }
  .cron-status { grid-column: 2; grid-row: 1; }
  .cron-next { grid-column: 1 / -1; }
  .cron-row-actions { grid-column: 1 / -1; grid-row: auto; flex-wrap: wrap; justify-content: start; }
}
@media (max-width: 680px) {
  .cron-toolbar h1 { flex-basis: 100%; }
  .cron-toolbar input { flex: 1 1 12rem; }
  .cron-toolbar select { flex: 0 0 auto; }
  .cron-toolbar > .btn { flex: 1 0 100%; }
  .cron-row { grid-template-columns: minmax(0, 1fr) auto; }
  .cron-row-actions { grid-column: 1 / -1; grid-row: auto; justify-content: start; }
  .cron-row-actions .btn { min-height: 44px; }
  .cron-detail-head { gap: var(--space-2); }
  .cron-actions { gap: var(--space-1); }
  .cron-actions .btn { min-height: 44px; }
  .cron-empty { align-items: flex-start; flex-direction: column; }
}

/* Last-wins composer: rounded rect 22px, content-axis width, text model name, 15px placeholder. */
.composer,
.composer.composer--workspace,
.home-composer-dock .composer.composer--workspace,
.session-composer.prompt-input .composer.composer--workspace {
  border-radius: 22px;
  border-width: 1px;
  border-style: solid;
  box-shadow: none;
}
.home-composer-dock,
.home-composer-dock > .composer-dock,
.session-composer.prompt-input .composer.composer--workspace {
  width: min(100%, var(--content-max));
  margin-inline: auto;
}
/* AI发现 / Home ask box: one content column. The dock, its rows and the composer
   frame sit on the page content frame the cards use (same max-width and gutters),
   and the inner rows span the frame — the 4px insets on the condition / notice /
   template rows are what made the ask box look narrower than its frame. Scoped to
   the Home pane so every other page keeps its own composer geometry. */
.home-pane.is-composer-dock .home-composer-dock,
.home-pane.is-composer-dock .home-composer-dock > .composer-dock {
  width: min(100%, var(--content-max));
  max-width: none;
  margin-inline: auto;
}
.home-pane.is-composer-dock .home-composer-dock .composer.composer--workspace {
  width: 100%;
  max-width: none;
  padding-inline: 12px;
}

/* 矮窗口（≈780px 高度以下）纵向预算：提问框按 32dvh 让步之后，再收紧跟进面的
   留白，让「我跟进的红人」至少完整显示一张对象卡——而不是像 2026-09-22 评审那样，
   239px 的卡只在页脚发丝线上露出半行名字。 */
@media (max-height: 780px) {
  .home-pane .home-stage { padding-top: 8px; }
  .followed-brief { margin-bottom: 4px; }
  .followed-brief-stats { margin-bottom: 4px; }
  .followed-kol-column .followed-object-toolbar { margin-bottom: 4px; }
}
.home-pane.is-composer-dock .home-composer-dock .composer-chips,
.home-pane.is-composer-dock .home-composer-dock .composer-template-preview,
.home-pane.is-composer-dock .home-composer-dock .discovery-composer-conditions,
.home-pane.is-composer-dock .home-composer-dock .composer-override-hint {
  padding-inline: 0;
  margin-inline: 0;
}
.composer textarea,
.composer textarea::placeholder,
.home-composer-dock .composer textarea,
.home-composer-dock .composer textarea::placeholder,
.session-composer.prompt-input .composer textarea,
.session-composer.prompt-input .composer textarea::placeholder {
  font-size: var(--ds-font-ui);
  font-weight: 400;
  line-height: 24px;
}
.composer textarea::placeholder,
.home-composer-dock .composer textarea::placeholder,
.session-composer.prompt-input .composer textarea::placeholder {
  color: #8a8a8a;
}
.tier-control,
.composer .tier-control,
.home-composer-dock .tier-control {
  min-width: 0;
  min-height: 0;
  background: transparent;
  border: 0;
  border-radius: 0;
  padding: 0;
}

/* Last-wins ChatGPT sidebar scrollbar. Must beat earlier dark-thumb / Windows-arrow rules.
   Desktop 260 rail lock above stays intact. Thumb sits at the rail edge (~255), not ~235. */
.sidebar,
.sidebar-scroll {
  scrollbar-width: thin;
  scrollbar-color: #c7c7c7 transparent;
  scrollbar-gutter: auto !important;
}
.sidebar::-webkit-scrollbar,
.sidebar-scroll::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
.sidebar::-webkit-scrollbar-track,
.sidebar-scroll::-webkit-scrollbar-track {
  background: transparent;
}
.sidebar::-webkit-scrollbar-thumb,
.sidebar-scroll::-webkit-scrollbar-thumb {
  background: #c7c7c7;
  border-radius: 99px;
}
.sidebar::-webkit-scrollbar-button,
.sidebar-scroll::-webkit-scrollbar-button {
  display: none;
  width: 0;
  height: 0;
}

