.mail-box-card:hover { border-color: color-mix(in srgb, var(--text) 18%, var(--border)); }
.mail-box-card.is-active {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 7%, var(--bg));
  box-shadow: inset 0 0 0 1px var(--accent);
}
.mail-box-card.is-error { color: var(--text-muted); }
.mail-box-dot {
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  border-radius: 50%;
  background: var(--text-muted);
}
.mail-box-dot.is-ok { background: var(--color-success-vivid); }
.mail-box-dot.is-error { background: var(--text-muted); }
.mail-box-label {
  grid-column: 2;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 600;
}
.mail-box-card .mail-count-pill { grid-column: 3; }
.mail-box-addr {
  grid-column: 2 / -1;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--font-xs);
}
.mail-list,
.mail-thread,
.mail-side {
  min-width: 0;
  height: 100%;
  overflow-x: hidden;
  overflow-y: auto;
}
.mail-list-tools {
  display: grid;
  gap: var(--space-2);
  margin-bottom: var(--space-2);
}
.mail-search-row {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  min-width: 0;
}
.mail-search-wrap {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  flex: 1 1 auto;
  min-width: 0;
  padding: 7px 14px;
  border: 1px solid var(--border);
  border-radius: var(--radius-inputs);
  background: var(--bg-elevated);
  cursor: text;
}
.mail-search-wrap svg {
  width: 16px;
  height: 16px;
  color: var(--text-muted);
  flex-shrink: 0;
}
.mail-search {
  width: 100%;
  min-width: 0;
  padding: 0;
  border: none;
  outline: none;
  background: transparent;
  color: var(--text);
  font: inherit;
  font-size: var(--font-sm);
}
.mail-filter-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  flex: 0 0 36px;
  border: 1px solid var(--border);
  border-radius: var(--radius-inputs);
  background: var(--bg-elevated);
  color: var(--text-muted);
  cursor: pointer;
}
.mail-filter-btn:hover { border-color: color-mix(in srgb, var(--text) 18%, var(--border)); }
.mail-filter-btn.is-on {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 7%, var(--bg));
  color: var(--accent-text);
}
.mail-ico {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}
.mail-list-tabs {
  display: flex;
  flex-wrap: nowrap;
  gap: 2px;
  border-bottom: 1px solid var(--border);
}
.mail-list-tabs button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-1);
  flex: 1 1 0;
  border: 0;
  border-bottom: 2px solid transparent;
  background: none;
  margin-bottom: -1px;
  padding: 6px 2px 7px;
  color: var(--text-muted);
  font: inherit;
  font-size: var(--font-sm);
  white-space: nowrap;
  cursor: pointer;
}
.mail-list-tabs button[aria-selected="true"] {
  color: var(--text);
  border-bottom-color: var(--accent);
  font-weight: 500;
}
.mail-list {
  display: grid;
  align-content: start;
  gap: 6px;
}
.mail-count-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  justify-self: end;
  min-width: 20px;
  padding: 1px 7px;
  border: 1px solid color-mix(in srgb, var(--accent) 30%, transparent);
  border-radius: var(--ds-radius-tag);
  background: color-mix(in srgb, var(--accent) 14%, var(--bg));
  color: var(--accent-text);
  font-size: var(--font-tag);
  font-weight: 600;
  line-height: 1.5;
}
.mail-count-pill.is-solid {
  border-color: transparent;
  background: var(--accent-text);
  color: var(--accent-fg);
}
.mail-row {
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr) auto;
  gap: 2px 12px;
  align-items: center;
  width: 100%;
  min-width: 0;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg);
  color: inherit;
  text-align: left;
  cursor: pointer;
  font: inherit;
}
.mail-row.is-selected {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 7%, var(--bg));
}
.mail-row.is-unread { font-weight: 500; }
.mail-row-avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--bg-elevated);
  color: var(--text-muted);
  font-size: var(--font-sm);
  font-weight: 500;
  line-height: 1;
}
.mail-avatar-t0 {
  background: color-mix(in srgb, #C2185B 14%, var(--bg));
  color: color-mix(in srgb, #C2185B 60%, var(--text));
}
.mail-avatar-t1 {
  background: color-mix(in srgb, #1A73E8 14%, var(--bg));
  color: color-mix(in srgb, #1A73E8 60%, var(--text));
}
.mail-avatar-t2 {
  background: color-mix(in srgb, #137333 14%, var(--bg));
  color: color-mix(in srgb, #137333 60%, var(--text));
}
.mail-avatar-t3 {
  background: color-mix(in srgb, #B26A00 14%, var(--bg));
  color: color-mix(in srgb, #B26A00 60%, var(--text));
}
.mail-avatar-t4 {
  background: color-mix(in srgb, #7B1FA2 14%, var(--bg));
  color: color-mix(in srgb, #7B1FA2 60%, var(--text));
}
.mail-avatar-t5 {
  background: color-mix(in srgb, #0277BD 14%, var(--bg));
  color: color-mix(in srgb, #0277BD 60%, var(--text));
}
.mail-row-main {
  display: grid;
  gap: 2px;
  min-width: 0;
}
.mail-row-head,
.mail-thread-head {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 12px;
  align-items: baseline;
  justify-content: space-between;
  min-width: 0;
}
.mail-row-subject,
.mail-row-preview,
.mail-row-head strong,
.mail-message-summary {
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
}
.mail-row-subject {
  display: block;
  margin: 0;
  font-size: var(--font-ui);
  white-space: nowrap;
}
.mail-row-preview,
.mail-message-summary {
  display: block;
  margin: 0;
  color: var(--muted);
  font-size: var(--font-sm);
  white-space: nowrap;
}
.mail-row-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.mail-row-counts {
  display: block;
  margin: 2px 0 0;
  font-size: var(--font-xs);
  color: var(--muted);
}
.mail-row-addresses {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 8px;
  margin-top: 2px;
  font-size: var(--font-xs);
  color: var(--muted);
  min-width: 0;
}
.mail-row-addr {
  min-width: 0;
  overflow-wrap: anywhere;
  word-break: break-all;
}
.mail-conversation-list {
  padding-left: 12px;
  border-left: 2px solid var(--border);
  margin-left: 6px;
}
.mail-chip {
  font-size: var(--font-tag);
  color: var(--muted);
  border: 1px solid var(--border);
  border-radius: var(--ds-radius-tag);
  padding: 1px 8px;
}
.mail-chip.is-unread { color: var(--text); }
.mail-thread {
  display: grid;
  align-content: start;
  gap: var(--space-3);
  padding: 4px 0 0;
}
.mail-thread-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2);
}
.mail-thread-actions .btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.mail-digest,
.mail-message,
.mail-unbound {
  display: grid;
  gap: 6px;
  min-width: 0;
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
}
.mail-digest.is-model { border-color: color-mix(in srgb, var(--accent) 35%, var(--border)); }
.mail-digest-body,
.mail-message-body p {
  margin: 0;
  white-space: pre-wrap;
  word-break: break-word;
}
.mail-timeline {
  display: grid;
  gap: var(--space-3);
  min-width: 0;
}
.mail-message.is-out { border-left: 3px solid var(--accent); }
.mail-message.is-in { border-left: 3px solid var(--line); }
.mail-message {
  background: var(--bg);
  cursor: pointer;
  box-shadow: var(--shadow-quiet);
}
.mail-message.is-current {
  border-color: color-mix(in srgb, var(--accent) 45%, var(--border));
  box-shadow: var(--shadow-quiet), inset 0 0 0 1px color-mix(in srgb, var(--accent) 45%, var(--border));
}
.mail-message-head {
  display: flex;
  align-items: flex-start;
  gap: var(--space-3);
  min-width: 0;
}
.mail-message-head .mail-row-avatar {
  flex: 0 0 40px;
  margin-top: 2px;
}
.mail-message-who {
  display: grid;
  gap: 1px;
  flex: 1 1 auto;
  min-width: 0;
}
.mail-message-who strong {
  font-size: var(--font-ui);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mail-message-who .muted {
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--font-sm);
}
.mail-message-head time {
  flex: 0 0 auto;
  margin-top: 3px;
  font-size: var(--font-xs);
  white-space: nowrap;
}
.mail-msg-more {
  position: relative;
  flex: 0 0 auto;
}
.mail-thread-more {
  position: relative;
}
.mail-more-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: none;
  color: var(--text-muted);
  cursor: pointer;
}
.mail-more-btn:hover,
.mail-more-btn[aria-expanded="true"] {
  border-color: var(--border);
  background: var(--bg-elevated);
  color: var(--text);
}
.mail-popover {
  position: absolute;
  top: calc(100% + 4px);
  right: 0;
  z-index: 80;
  min-width: 160px;
  padding: 6px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg);
  box-shadow: var(--shadow-quiet);
  display: grid;
}
.mail-popover button {
  border: 0;
  background: none;
  color: var(--text);
  text-align: left;
  font: inherit;
  font-size: var(--font-sm);
  padding: 7px 9px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  min-height: 32px;
}
.mail-popover button:hover:not(:disabled) { background: color-mix(in srgb, var(--text) 6%, transparent); }
.mail-popover button:disabled { color: var(--text-muted); cursor: default; }
.mail-message-body {
  margin: 0;
  font-size: var(--font-body);
  line-height: var(--leading-body);
}
.mail-star {
  border: 0;
  background: none;
  padding: 0 4px;
  color: var(--text-muted);
  font: inherit;
  font-size: var(--font-page-title);
  line-height: 1;
  cursor: pointer;
  vertical-align: middle;
}
.mail-star:hover,
.mail-star.is-starred { color: var(--accent-text); }
.mail-thread-actions {
  padding-top: var(--space-1);
}
.mail-side {
  display: grid;
  align-content: start;
  gap: var(--space-3);
}
.mail-side-card {
  display: grid;
  gap: var(--space-2);
  min-width: 0;
  padding: 14px 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg);
  box-shadow: var(--shadow-quiet);
}
.mail-side-card-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
  min-width: 0;
}
.mail-side-card-head strong {
  font-size: var(--font-section);
  font-weight: 600;
}
.mail-side-tag {
  padding: 1px 8px;
  border-radius: var(--ds-radius-tag);
  background: color-mix(in srgb, var(--accent) 10%, var(--bg));
  color: var(--accent-text);
  font-size: var(--font-tag);
  line-height: 1.5;
}
.mail-side-body {
  min-width: 0;
  font-size: var(--font-sm);
  line-height: 1.6;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.mail-side-body p { margin: 0 0 var(--space-2); }
.mail-side-body p:last-child { margin-bottom: 0; }
.mail-copy-btn {
  border: 1px solid var(--border);
  border-radius: var(--ds-radius-tag);
  background: var(--bg);
  color: var(--text-muted);
  font: inherit;
  font-size: var(--font-xs);
  padding: 3px 10px;
  cursor: pointer;
  min-height: 28px;
}
.mail-copy-btn:hover:not(:disabled) {
  color: var(--accent-text);
  border-color: var(--accent);
}
.mail-copy-btn:disabled { opacity: 0.5; cursor: default; }
.mail-mobiletabs { display: none; }
.mail-mobile-panel { display: none; }
@media (max-width: 768px) {
  .mail-split { grid-template-columns: minmax(0, 1fr); }
  .mail-side { display: none; }
  .mail-mobiletabs {
    display: flex;
    gap: 2px;
    border-bottom: 1px solid var(--border);
  }
  .mail-mobiletabs button {
    flex: 1 1 0;
    border: 0;
    border-bottom: 2px solid transparent;
    background: none;
    margin-bottom: -1px;
    padding: 8px 2px 9px;
    color: var(--text-muted);
    font: inherit;
    font-size: var(--font-body);
    cursor: pointer;
  }
  .mail-mobiletabs button[aria-selected="true"] {
    color: var(--text);
    border-bottom-color: var(--accent);
    font-weight: 500;
  }
  .mail-mobile-panel { display: block; }
  .mail-thread .mail-hide-narrow { display: none; }
}
.mail-skeleton {
  height: 88px;
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--text) 6%, var(--bg));
}
button.today-brief-primary-btn {
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  font: inherit;
  color: var(--accent-text);
  font-weight: 600;
}
button.today-brief-primary-btn:hover:not(:disabled) {
  text-decoration: underline;
}
button.today-brief-primary-btn:disabled {
  opacity: 0.6;
  cursor: default;
}
.sidebar-version {
  padding: 0 6px 4px;
  font-size: var(--ds-font-tag);
  color: var(--text-muted, var(--ds-text-dim));
  user-select: all;
}

/* =====================================================   今日任务 vivid pink redesign (mockup pass)
   ============================================================ */
:root[data-theme="dark"] {
  --color-page-bg: #101216;
  --color-text-dim: #a2a8b2;
  --color-warning-tint: #3d2c10;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --color-page-bg: #101216;
    --color-text-dim: #a2a8b2;
    --color-warning-tint: #3d2c10;
  }
}

/* Sidebar — pink active state */
.nav-link.active,
.nav-combo.active {
  background: color-mix(in srgb, var(--accent) 14%, var(--bg));
  color: var(--accent-text);
  border-color: transparent;
  box-shadow: none;
  font-weight: 500;
}
.nav-link.active .nav-ico,
.nav-combo.active .nav-ico {
  color: var(--accent-text);
}
.sidebar-brand-sub {
  display: block;
  font-size: var(--ds-font-helper);
  font-weight: 400;
  color: var(--text-muted);
  line-height: 1.3;
}
.sidebar-foot {
  border-top-color: var(--border);
}

/* Home — page canvas + hero */
.home-pane {
  background: var(--color-page-bg);
}
.home-hero h1 {
  font-size: 18px;
  font-weight: 500;
  color: #1a1a1a;
  margin: var(--space-2) 0 6px;
}
:root[data-theme="dark"] .home-hero h1 {
  color: var(--text);
}
.home-stats {
  font-size: var(--ds-font-sm);
  color: var(--color-text-dim);
}
.home-mode-tabs {
  border-bottom-color: #ececf0;
}
.home-mode-tabs button[role="tab"] {
  color: var(--color-text-dim);
  border-bottom: 3px solid transparent;
  border-radius: 3px 3px 0 0;
  font-weight: 400;
}
.home-mode-tabs button[role="tab"][aria-selected="true"] {
  color: #1a1a1a;
  border-bottom-color: var(--accent);
  font-weight: 600;
}
:root[data-theme="dark"] .home-mode-tabs button[role="tab"][aria-selected="true"] {
  color: var(--text);
}
.home-mode-count {
  color: var(--accent-text);
  font-size: var(--ds-font-tag);
  font-weight: 500;
  margin-left: 0;
}

/* 优化结论 card (restyle of .today-brief in today mode) */
.today-brief-card {
  background: color-mix(in srgb, var(--accent) 7%, var(--bg));
  border: 1px solid #f6dce8;
  border-radius: var(--ds-radius-section);
  padding: 16px 20px;
  box-shadow: 0 1px 2px rgba(16, 24, 40, 0.04);
}
:root[data-theme="dark"] .today-brief-card {
  border-color: #4a1e32;
}
.today-brief-head {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 8px;
}
.today-brief-badge {
  flex: 0 0 auto;
  width: 28px;
  height: 28px;
  border-radius: var(--ds-radius-input);
  background: var(--accent-text);
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.today-brief-badge svg {
  width: 15px;
  height: 15px;
  display: block;
}
.today-brief-title {
  font-size: var(--ds-font-ui);
  font-weight: 600;
  color: #1a1a1a;
}
:root[data-theme="dark"] .today-brief-title {
  color: var(--text);
}
.today-brief-meta {
  margin-left: auto;
  font-size: var(--ds-font-helper);
  color: var(--color-text-dim);
}
.today-brief-card .today-brief-lead {
  font-weight: 400;
  color: #374151;
  line-height: 1.6;
}
:root[data-theme="dark"] .today-brief-card .today-brief-lead {
  color: var(--text);
}
.today-brief-card .today-brief-note {
  margin: 6px 0 0;
  font-size: var(--ds-font-sm);
  color: var(--color-text-dim);
  line-height: 1.55;
}
.today-brief-card .today-brief-primary {
  margin: 8px 0 0;
  color: var(--accent-text);
  font-size: var(--ds-font-sm);
  font-weight: 500;
}

/* Dark-mode legibility for the today workspace */
:root[data-theme="dark"] .task-board {
  background: var(--bg);
  border-color: var(--border);
}
:root[data-theme="dark"] .task-board-title,
:root[data-theme="dark"] .task-board-head h2 {
  color: var(--text);
}
:root[data-theme="dark"] .task-board-search {
  background: var(--bg-elevated);
  color: var(--text);
}
:root[data-theme="dark"] .task-board-table th {
  border-bottom-color: var(--border);
}
:root[data-theme="dark"] .task-board-table td {
  border-bottom-color: var(--border);
}
:root[data-theme="dark"] .task-board-row:hover td {
  background: var(--bg-elevated);
}
:root[data-theme="dark"] .task-board-open {
  background: transparent;
  border: 0;
  color: var(--accent-text);
}
:root[data-theme="dark"] .task-board-edit {
  background: var(--bg);
  border-color: var(--border);
  color: var(--text-muted);
}
:root[data-theme="dark"] .today-plan-title,
:root[data-theme="dark"] .today-plan-step-label,
:root[data-theme="dark"] .today-plan-summary-lead {
  color: var(--text);
}
/* The stream's accents and the reasoning block are otherwise light-on-dark. */
:root[data-theme="dark"] .today-plan-lead,
:root[data-theme="dark"] .today-plan-summary-note,
:root[data-theme="dark"] .today-plan-summary-stats {
  color: var(--text-muted);
}
:root[data-theme="dark"] .today-plan-step.is-running .today-plan-step-label,
:root[data-theme="dark"] .today-plan-step.is-running .today-plan-step-mark {
  color: #C4B5FD;
}
:root[data-theme="dark"] .today-plan-step.is-failed .today-plan-step-label,
:root[data-theme="dark"] .today-plan-step.is-failed .today-plan-step-mark,
:root[data-theme="dark"] .today-plan-step-reason {
  color: #FCA5A5;
}
:root[data-theme="dark"] .today-plan-state.is-live {
  background: color-mix(in srgb, #9333EA 22%, transparent);
  color: #C4B5FD;
}
:root[data-theme="dark"] .today-plan-state.is-failed {
  background: color-mix(in srgb, #DC2626 22%, transparent);
  color: #FCA5A5;
}
:root[data-theme="dark"] .today-plan-step-op,
:root[data-theme="dark"] .today-plan-meta,
:root[data-theme="dark"] .today-plan-finished,
:root[data-theme="dark"] .today-plan-toggle {
  color: var(--text-muted);
}
:root[data-theme="dark"] .today-plan {
  --plan-accent: #A78BFA;
  --plan-accent-soft: #4C1D95;
  --plan-think-bg: color-mix(in srgb, #9333EA 16%, transparent);
}
:root[data-theme="dark"] .today-plan-think {
  border-left-color: #7C3AED;
}
:root[data-theme="dark"] .discovery-stream-panel {
  --plan-accent: #A78BFA;
  --plan-accent-soft: #4C1D95;
  --plan-think-bg: color-mix(in srgb, #9333EA 16%, transparent);
}
:root[data-theme="dark"] .discovery-think {
  border-left-color: #7C3AED;
}
:root[data-theme="dark"] .today-plan-think-label,
:root[data-theme="dark"] .today-plan-summary-label {
  color: var(--text-muted);
}
:root[data-theme="dark"] .today-plan-summary {
  border-top-color: var(--border);
}

.sidebar-brand-copy {
  display: grid;
  gap: 1px;
  min-width: 0;
}
.sidebar-brand-copy .brand-name {
  font-size: var(--ds-font-section);
  font-weight: 600;
  color: #1a2b4a;
  line-height: 1.25;
}
:root[data-theme="dark"] .sidebar-brand-copy .brand-name {
  color: var(--text);
}

/* === Skill Catalog Page === */
/* 技能目录页（/skills）。依据 docs/DESIGN.md 的「员工端实施细则」（实施细则，非基本法）：
   密度档 data-dense-dashboard（列表行本身就是内容，不做卡片墙）、§控件尺寸、§三轴适配、
   §不变量 1/3/4、§验收矩阵。
   规则：尺寸 / 圆角 / 命中区只走命名 token（--control-h* / --radius-control / --radius-card /
   --chip-h / --badge-h / --hit-min）；内容列上限走 --content-max，页面留白走 --page-gutter；
   同一视口 0–1 个实底主 CTA；状态不靠颜色单独表达；焦点环由壳层 :focus-visible 统一提供。 */
.skill-catalog-page {
  /* 图标阶梯：本页只有两档（控件内图标 / 图标砖内图标），不出现第三种尺寸。 */
  --icon-sm: 14px;
  --icon-md: 18px;

  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
}

/* ── 栏头：技能目录 + 计数（住在栏 2 里，不再是横跨 2/3/4 栏的页头行） ─────────
   2026-09-23 UI/UX 裁定：栏头只回答「这一栏是什么 + 现在有多少项」。横跨三栏的独立页头行
   既占高度，又把筛选条与它描述的列表隔开；计数跟着筛选与搜索实时变。
   ≥1280 的纵向左栏里它吸顶（见 media 段），口径组与阶段组从它下面滑过。 */
.skill-catalog-title {
  display: flex;
  align-items: baseline;
  gap: var(--space-2);
  flex-shrink: 0;
  /* 横向档：筛选条是 flex-end 对齐的一排 tab，栏头按行高居中，不与 tab 抢基线。 */
  align-self: center;
  padding-right: var(--space-4);
}

/* 栏标题走壳层页标题档（--ds-font-block-title）：本页是登录后的工作台，
   不用营销落地页的 display 尺寸与负字距。 */
.skill-catalog-title h1 {
  margin: 0;
  font-size: var(--ds-font-block-title);
  line-height: var(--ds-line-block-title);
  /* 与 Home / 知识库的页标题同档：500，不是 600（此前整页标题偏重）。 */
  font-weight: 500;
  letter-spacing: 0;
  white-space: nowrap;
}

/* 计数（「51 项」）：跟随筛选与搜索实时变化，是栏头唯一的信息增量。 */
.skill-catalog-count {
  color: var(--text-muted);
  font-size: var(--ds-font-helper);
  line-height: var(--lh-control-sm);
  white-space: nowrap;
}

/* 搜索行：栏 3 顶部，sticky 贴在列表列的滚动口上（「搜索 → 结果」是一组）。
   选择器带父级：它是 `> *` 那条「宽度上限 --content-max + 居中」的例外，必须比它更具体。 */
.skill-catalog-content > .skill-search-row {
  position: sticky;
  top: 0;
  z-index: 2;
  /* 必须自带上色：列表行从它下面滚过时不能透视。 */
  background: var(--bg);
  /* 铺满栏宽：用负外边距抵消内容列的左右留白，并且不吃 --content-max 宽度上限 ——
     底色与底缘发丝线因此横贯整栏，组头只能从它**下面**滑过，不会在它上方露出半截字。 */
  margin-inline: calc(-1 * var(--skill-content-pad));
  padding-inline: var(--skill-content-pad);
  /* `> *` 那条给的是 width:100%（= 内容盒宽），配负外边距只会往左溢；这里必须 auto，
     让宽度 = 内容盒 + 两侧留白 = 整栏的 padding box。 */
  width: auto;
  max-width: none;
  padding-block: 0 var(--space-2);
  border-bottom: 1px solid var(--border);
  /* 与下方分组的视觉间距定为 --space-2（比容器 gap 小一档，搜索框才贴得住第一组），
     多出来的部分用负外边距扣掉；扣多少跟着容器 gap 变，所以两者共用一个变量。 */
  margin-bottom: calc(var(--space-2) - var(--skill-content-gap));
}

/* 底色铺满整栏，不等于输入框要拉到 2560 屏那么宽：它仍住在内容列上限里。 */
.skill-search-row .skill-search-wrap {
  max-width: var(--content-max);
  margin-inline: auto;
}

/* 搜索框：单体控件自带 ≥3:1 的 --control-border 描边（成组控件才用容器填色），
   聚焦时边框转 --text。 */
.skill-search-wrap {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: 0 var(--space-3);
  height: var(--control-h-lg);
  min-width: 240px;
  border: 1px solid var(--control-border);
  border-radius: var(--radius-control);
  background: transparent;
}

.skill-search-wrap:focus-within {
  border-color: var(--text);
}

.skill-search-wrap svg {
  width: var(--icon-sm);
  height: var(--icon-sm);
  color: var(--text-muted);
  flex-shrink: 0;
}

/* 搜索框的清除入口：只在有输入时出现，方形命中区走 --control-h-sm。 */
.skill-search-clear {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  width: var(--control-h-sm);
  height: var(--control-h-sm);
  padding: 0;
  border: 0;
  border-radius: var(--radius-control);
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
}

.skill-search-clear:hover {
  background: var(--surface-hover);
  color: var(--text);
}

.skill-search {
  border: none;
  background: transparent;
  outline: none;
  font: inherit;
  font-size: var(--ds-font-sm);
  line-height: var(--lh-control);
  /* 命中区下限：输入框自身不得低于 --hit-min。 */
  min-height: var(--hit-min);
  width: 100%;
  color: var(--text);
}

/* ── 筛选条：与 Home 四模式、设置页、邮件页同一套写法 ──────────────────
   发丝底线 + 选中项 2px 底线。此前是「浅面胶囊容器里浮一个白胶囊 + 投影」，
   那是落地页候选分析（Cal.com）的 nav-pill-group 签名交互，员工端其它页面都不用。 */
.skill-tabs {
  grid-area: tabs;
  display: flex;
  flex-wrap: nowrap;
  align-items: flex-end;
  gap: var(--space-2) var(--space-5);
  padding: var(--space-2) var(--page-gutter) 0;
  border-bottom: 1px solid var(--border);
  overflow-x: auto;
  scrollbar-width: none;
  flex-shrink: 0;
}

.skill-tabs::-webkit-scrollbar {
  display: none;
}

.skill-tabs-list {
  display: flex;
  flex-wrap: nowrap;
  align-items: flex-end;
  gap: var(--space-4);
  flex-shrink: 0;
}

/* 使用范围与业务场景是两组可组合筛选；分隔线只区分筛选用途，不表示阶段递进。 */
.skill-tabs-list[data-kind="stage"] {
  align-self: stretch;
  padding-left: var(--space-4);
  border-left: 1px solid var(--border);
}

/* 选中态三重信号：2px 底线（形状）+ 字重 500 + 品牌色文字；
   aria-pressed 暴露程序化状态（§不变量 4：状态不能只靠颜色表达）。 */
.skill-tab {
  display: inline-flex;
  align-items: center;
  margin-bottom: -1px;
  padding: 6px 0 8px;
  border: 0;
  border-bottom: 2px solid transparent;
  border-radius: 0;
  background: none;
  font: inherit;
  font-size: var(--ds-font-sm);
  line-height: var(--lh-control-sm);
  color: var(--text-muted);
  min-height: var(--control-h-lg);
  cursor: pointer;
  white-space: nowrap;
  min-width: 0;
  transition: color var(--duration-control), border-color var(--duration-control);
}

.skill-tab:hover {
  color: var(--text);
}

.skill-tab.on {
  color: var(--accent-text);
  border-bottom-color: var(--accent);
  font-weight: 500;
}

/* 阶段递进分隔符：纯装饰，不参与 tab 顺序与键盘焦点。
   垂直居中于词（父容器 flex-end 会把 line-height:1 的小盒贴到 tab 下内边距上，看起来像上标）；
   字号与 tab 同档，不再比词小一号。 */
.skill-tab-sep {
  align-self: center;
  color: var(--text-muted);
  font-size: var(--ds-font-sm);
  line-height: 1;
  user-select: none;
}

/* 窄屏下筛选条会横向滚动：右缘渐隐是「还有内容」的可视信号。
   sticky 让它贴在滚动容器右缘；宽屏放得下时它只盖在背景上，不产生视觉噪声。 */
.skill-tabs-fade {
  position: sticky;
  right: 0;
  flex: 0 0 auto;
  align-self: stretch;
  width: var(--space-5);
  margin-left: calc(-1 * var(--space-5));
  pointer-events: none;
  background: linear-gradient(to right, transparent, var(--bg) 72%);
}

/* ── 页面状态：加载暴露 busy、失败给恢复入口（§不变量 3） ───────────── */
.skill-state {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-3) var(--page-gutter);
  border-bottom: 1px solid var(--border);
  flex-shrink: 0;
}

.skill-state .error,
.skill-state .muted {
  margin: 0;
}

/* ── 主区：筛选栏 + 内容列 + 详情列 ──────────────────────────────────
   基础（<1280）：筛选条横跨一整行，下一行是「列表列 + 详情列」——与改造前的两栏形态一致。
   用 grid 而不是 flex column：详情列必须与列表并排（列宽按**列表列**的实际宽度收敛 ——
   1024 视口下列表列只剩约 400px，标记列要按容器查询收起，见下面的 @container 段）。
   行用 minmax(0, 1fr) 给第二行一个确定高度，列表列自己滚，不把整页撑高。 */
.skill-catalog-main {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas:
    "tabs tabs"
    "content pane";
  flex: 1;
  min-height: 0;
  overflow: hidden;
}

.skill-catalog-content {
  grid-area: content;
  min-width: 0;
  overflow-y: auto;
  /* 列内左右留白：搜索行要按它做全栏铺满（见 .skill-search-row），两者共用一个变量，
     换断点时（≤640 收窄）才不会各自漂移。 */
  --skill-content-pad: var(--page-gutter);
  padding: var(--space-4) var(--skill-content-pad) var(--space-5);
  display: flex;
  flex-direction: column;
  /* 列间距：搜索行要在它的基础上再扣掉多余部分（见 .skill-search-row），
     两者共用一个变量，换断点时才不会各自漂移。 */
  --skill-content-gap: var(--ds-section-gap);
  gap: var(--skill-content-gap);
}

/* 内容列上限走 --content-max（§三轴适配 · 宽度轴），与壳层其它页面同轴。 */
.skill-catalog-content > * {
  width: 100%;
  max-width: var(--content-max);
  margin-inline: auto;
}

/* ── 分组 ─────────────────────────────────────────────────────────── */
.skill-group {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.skill-group-header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2);
}

.skill-group-icon {
  width: var(--control-h-sm);
  height: var(--control-h-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-text);
}

.skill-group-svg {
  width: var(--icon-md);
  height: var(--icon-md);
  color: var(--accent-text);
}

/* 组名与 tab、行标题同档（13px / 500），不再比内容大一号还加粗：层级由分组间距、
   图标与提示语承担（2026-09-23 UI/UX 裁定）。墨色走 --text：辅助色不用于分区标题
   （§颜色 职责表里辅助色只有选中态 / 图标砖与字形 / 行内可点强调 / 信息性标记），
   蓝色标题还会被读成可点链接。 */
.skill-group-header h2 {
  margin: 0;
  white-space: nowrap;
  font-size: var(--ds-font-sm);
  font-weight: 500;
  color: var(--text);
}

.skill-group-hint {
  color: var(--text-muted);
  font-size: var(--ds-font-helper);
  margin-left: var(--space-2);
}

/* 「查看全部」是可点标签：13px + 常驻下划线 + 自撑命中区。 */
.skill-group-more {
  margin-left: auto;
  white-space: nowrap;
  display: inline-flex;
  align-items: center;
  min-height: var(--hit-min);
  color: var(--text-muted);
  font-size: var(--ds-font-sm);
  line-height: var(--lh-control-sm);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.skill-group-more:hover {
  color: var(--text);
}

/* ── 列表：行本身就是内容 ─────────────────────────────────────────────
   组容器只画上下两条发丝线，行与行之间一条发丝线；不套卡片、不给每行底色与圆角。
   列：图标砖 / 名称 / 摘要 / 标记。行内不再有动作：填技能只剩详情列的实底主 CTA。 */
.skill-list {
  display: flex;
  flex-direction: column;
  gap: 0;
  border-block: 1px solid var(--border);
}

.skill-row {
  position: relative;
  display: grid;
  grid-template-columns: var(--control-h-lg) minmax(80px, 0.8fr) minmax(0, 1.8fr) auto;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-2) var(--space-3);
  border-bottom: 1px solid var(--border);
  cursor: pointer;
  transition: background-color var(--duration-control);
}

.skill-row:last-child {
  border-bottom: 0;
}

.skill-row:hover,
.skill-row:focus-within {
  background: var(--surface-hover);
}

/* 选中：--ds-selected-bg 底 + 左侧 3px 形状信号（非颜色信号，§不变量 4）。 */
.skill-row.is-selected {
  background: var(--ds-selected-bg);
  box-shadow: inset 3px 0 0 var(--ds-selected-border);
}

.skill-row-icon {
  grid-column: 1;
  width: var(--control-h-lg);
  height: var(--control-h-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  /* 图标砖走「类别」色（docs/DESIGN.md §颜色 第 4 职责）：淡底 / 描边 / 砖内字形三件套由
     data-tone 决定；没有 data-tone 时回落辅助色配方（与 Home、知识库的淡色砖同一配方）。 */
  border: 1px solid var(--tile-line, color-mix(in srgb, var(--accent) 18%, var(--border)));
  background: var(--tile-bg, color-mix(in srgb, var(--accent) 8%, var(--bg)));
  border-radius: var(--radius-control);
  color: var(--tile-ink, var(--accent-text));
  flex-shrink: 0;
}

.skill-row-icon[data-tone="library"] {
  --tile-ink: var(--cat-library-text);
  --tile-bg: var(--cat-library-tile);
  --tile-line: var(--cat-library-line);
}

.skill-row-icon[data-tone="assistant"] {
  --tile-ink: var(--cat-assistant-text);
  --tile-bg: var(--cat-assistant-tile);
  --tile-line: var(--cat-assistant-line);
}

.skill-row-icon[data-tone="crawl"] {
  --tile-ink: var(--cat-crawl-text);
  --tile-bg: var(--cat-crawl-tile);
  --tile-line: var(--cat-crawl-line);
}

.skill-row-icon[data-tone="builtin"] {
  --tile-ink: var(--cat-builtin-text);
  --tile-bg: var(--cat-builtin-tile);
  --tile-line: var(--cat-builtin-line);
}

.skill-row-svg {
  width: var(--icon-md);
  height: var(--icon-md);
}

/* 异步作业：虚线描边＝形状信号（与 L3 的实线不同形状），线色取砖内字形档保证可见。
   文字标签已按 2026-09-23 UI/UX 裁定移除，这是列表行上唯一的异步行级信号；
   完整异步口径（进度 / 取消 / 重试）仍在详情列与执行面。 */
.skill-row.is-async .skill-row-icon {
  border-style: dashed;
  border-color: currentColor;
}

/* 名称是行选择的键盘可达入口，用 aria-pressed 暴露选中态；允许省略号。 */
.skill-row-name {
  grid-column: 2;
  /* 冷墨：由正文墨色与辅助色混出，比纯 --text 轻一档（对白 13.88:1，仍远超正文要求）。 */
  --row-title-ink: color-mix(in srgb, var(--text) 82%, var(--accent));
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  min-width: 0;
  overflow: hidden;
  border: 0;
  background: none;
  padding: 0;
  font: inherit;
  /* 与描述同号同重（13px / 400）：名与描述只靠墨色区分，不靠字重（2026-09-23 UI/UX 裁定）。 */
  font-size: var(--ds-font-sm);
  line-height: var(--lh-control);
  font-weight: 400;
  /* 行高只有 20px，命中区靠 min-height 补到 --hit-min。 */
  min-height: var(--hit-min);
  color: var(--row-title-ink);
  cursor: pointer;
  text-align: left;
}

/* 名称文字承担省略号：★ 不参与收缩，长名字不会把星挤出可视区。 */
.skill-row-name-text {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.skill-row-name:hover {
  text-decoration: underline;
}

.skill-row-desc {
  grid-column: 3;
  margin: 0;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: var(--text-muted);
  font-size: var(--ds-font-sm);
  line-height: var(--lh-control-sm);
}

.skill-row-marks {
  grid-column: 4;
  display: flex;
  flex-wrap: nowrap;
  gap: var(--space-1);
  white-space: nowrap;
}

/* 常用：属「例外」信号，用形状（★）+ 辅助色并行；跟在名称后面，不再压在行的左上角。
   星标是信息性标记而不是状态，走辅助色（§颜色：语义色只表达状态，不得代替辅助色）。 */
.skill-row-star {
  flex: 0 0 auto;
  color: var(--accent-text);
  font-size: var(--ds-font-tag);
  line-height: 1;
}

/* ── 标记（badge）：只标例外（L2 草稿 / L3 需确认 / 异步契约） ───────── */
.skill-mark {
  display: inline-flex;
  align-items: center;
  height: var(--badge-h);
  padding: 0 var(--space-2);
  border: 1px solid var(--control-border);
  border-radius: var(--radius-control);
  font-size: var(--ds-font-helper);
  font-weight: 500;
  line-height: var(--lh-control-sm);
  color: var(--text-muted);
  white-space: nowrap;
}

/* L3「需确认」：语义色 + 文字并行，不是仅颜色。 */
.skill-mark.is-write {
  border-color: var(--warning);
  background: color-mix(in srgb, var(--warning) 10%, var(--bg));
  color: var(--text);
}

/* 异步作业：虚线边框是形状信号（与文字「异步 · 可取消」并行）。 */
.skill-mark.is-async {
  border-style: dashed;
}

/* ── 动作 ─────────────────────────────────────────────────────────── */
.skill-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-1);
  height: var(--control-h);
  padding: 0 var(--space-3);
  border-radius: var(--radius-control);
  border: 1px solid var(--control-border);
  background: transparent;
  color: var(--text);
  font: inherit;
  font-size: var(--ds-font-sm);
  line-height: var(--lh-control);
  white-space: nowrap;
  cursor: pointer;
  transition: background var(--duration-control), color var(--duration-control),
    border-color var(--duration-control);
}

.skill-btn:hover {
  background: var(--surface-hover);
}

/* 本页唯一的实底主 CTA（§不变量 1）：其余动作一律降到描边或链接式。 */
.skill-btn-primary {
  background: var(--primary);
  color: var(--primary-fg);
  border-color: var(--primary);
  font-weight: 500;
}

.skill-btn-primary:hover {
  background: var(--primary-hover);
  border-color: var(--primary-hover);
}

.skill-btn-outline {
  background: transparent;
  color: var(--text);
  border-color: var(--control-border);
  font-weight: 500;
}

.skill-btn-outline:hover {
  background: var(--surface-hover);
  border-color: var(--text-muted);
}

.skill-btn-large {
  height: var(--control-h-lg);
  padding: 0 var(--space-4);
}

/* 禁用态：L1 实底 CTA 被禁用时（内部技能）降饱和、不响应 hover。 */
.skill-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
.skill-btn:disabled:hover {
  background: var(--primary);
  border-color: var(--primary);
}

/* L3 文字按钮（docs/DESIGN.md §4.2）：行内次级动作 —— 本页用于「展开/收起说明书」。
   无边框无底色，hover 走辅助色 8% 淡底；不得升级为描边/实底。 */
.skill-text-btn {
  display: inline-flex;
  align-items: center;
  height: var(--btn-text-h);
  padding: 0 var(--btn-text-pad-x);
  border: 0;
  border-radius: var(--radius-control);
  background: transparent;
  color: var(--accent-text);
  font: inherit;
  font-size: var(--ds-font-sm);
  cursor: pointer;
}
.skill-text-btn:hover {
  background: var(--btn-text-hover-bg);
}

/* 内部技能提示行：muted 小字，不做成横幅 —— 它是列表的脚注，不是警告。 */
.skill-internal-note {
  margin: 0;
  padding: var(--space-2) 0;
  color: var(--text-muted);
  font-size: var(--ds-font-helper);
  text-align: center;
}

/* 说明书折叠区内的「示例」小标题：沿用正文 h4 的字阶，弱化一级。 */
.skill-doc-subhead {
  margin: var(--space-3) 0 var(--space-1);
  font-size: var(--ds-font-helper);
  font-weight: 600;
  color: var(--text-muted);
}

/* ── 第四栏：技能详情 ────────────────────────────────────────────────
   内容按技能逐项设计，每一项都指回该技能自己的 SKILL.md（口径 = `employee_quick` /
   `employee_agent`，说明书 = `## 员工口径`，示例 = `employee_example`）—— 页面不再手抄一份。
   骨架三段式：`.skill-detail-head` / `.skill-detail-body` / `.skill-detail-footer`。 */
.skill-detail-pane {
  grid-area: pane;
  width: clamp(var(--workspace-result-rail-min), 26vw, 420px);
  border-left: 1px solid var(--border);
  background: var(--bg);
  overflow: hidden;
  flex-shrink: 0;
  transition: width var(--duration-enter);
}

.skill-detail-pane.is-wide {
  width: clamp(420px, 40vw, 620px);
}

.skill-detail {
  display: flex;
  flex-direction: column;
  height: 100%;
}

/* 展开 / 关闭：方形图标按钮走 --control-h-sm + --radius-control；必须带 aria-label。
   两个按钮住在详情列头部那一行的右端（.skill-detail-head），不再另起一条标题带。 */
.skill-detail-toggle,
.skill-detail-close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  width: var(--control-h-sm);
  height: var(--control-h-sm);
  padding: 0;
  border: 1px solid var(--control-border);
  border-radius: var(--radius-control);
  background: transparent;
  font: inherit;
  font-size: var(--ds-font-sm);
  line-height: var(--lh-control-sm);
  color: var(--text-muted);
  cursor: pointer;
}

.skill-detail-toggle {
  margin-left: auto;
}

.skill-detail-toggle:hover,
.skill-detail-close:hover {
  background: var(--surface-hover);
  color: var(--text);
}

.skill-detail-toggle-svg,
.skill-detail-close-svg {
  width: var(--icon-sm);
  height: var(--icon-sm);
}

/* 关闭按钮只在窄屏覆盖态出现（≥900px 时详情列常驻）。 */
.skill-detail-close {
  display: none;
}

/* 详情列三段式：头（身份 + 标签，固定）/ 正文（自己滚）/ 底（唯一实底 CTA，固定），
   段与段之间各一条发丝线。正文滚动时头与底不动 —— 长说明不再把工具名与主 CTA 顶出视口。 */
.skill-detail-head {
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  padding: var(--space-4) var(--space-4) var(--space-3);
  border-bottom: 1px solid var(--border);
}

/* 头部一行：图标砖 + 技能名 + 两个图标按钮。不再有「技能详情」标题条与摘要句
   —— 两者都是中栏选中行的逐字重复（2026-09-23 UI/UX 裁定）。 */
.skill-detail-title {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

/* 详情列头的图标砖比列表行小一档（--control-h = 28px）：与下方标记行的缩进对齐。 */
.skill-detail-head .skill-row-icon {
  width: var(--control-h);
  height: var(--control-h);
}

/* 技能名占满剩余宽度（长名字走省略号），两个按钮因此始终贴右端。 */
.skill-detail-head h2 {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  margin: 0;
  font-size: var(--ds-font-ui);
  line-height: var(--lh-control);
  font-weight: 500;
  color: var(--text);
}

/* 标记行缩进到与标题左对齐：缩进量 = 图标砖一档 + head 的 gap。 */
.skill-detail-marks {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
  margin-left: calc(var(--control-h) + var(--space-3));
}

/* 正文段间距 20px（比 --space-5 紧一档），小节内 8px：一屏里能多看两节。
   正文基准 13px / 400 墨色（`.skill-detail-value`），chips 12px / 400。 */
.skill-detail-body {
  flex: 1;
  overflow-y: auto;
  padding: var(--space-4);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.skill-detail-section {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.skill-detail-section h4 {
  margin: 0;
  /* 小节标题降为 12px / 500 / --text-muted：它只是分节标签，不与正文抢层级
     （此前 13px / 600 / 冷墨，整列小节标题比内容还重；2026-09-23 UI/UX 裁定）。 */
  font-size: var(--ds-font-helper);
  font-weight: 500;
  color: var(--text-muted);
  letter-spacing: 0.01em;
}

/* 正文：13px / 400 墨色。 */
.skill-detail-value {
  margin: 0;
  font-size: var(--ds-font-sm);
  line-height: var(--lh-control);
  font-weight: 400;
  color: var(--text);
}

/* 标签 + 值同行（label 12px muted、value 13px ink）：不再一 label 一 value 竖排两行。
   label 列给固定下限，同一节里的值左缘对齐。 */
.skill-detail-field {
  display: flex;
  align-items: baseline;
  gap: var(--space-3);
  margin: 0;
}

.skill-detail-field-label {
  flex: 0 0 auto;
  min-width: 3em;
  font-size: var(--ds-font-helper);
  line-height: var(--lh-control-sm);
  color: var(--text-muted);
}

/* 一行提示：前缀一个小图标（--icon-sm），替代原先的大块浅底 callout。 */
.skill-detail-hint {
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  margin: 0;
  font-size: var(--ds-font-helper);
  line-height: var(--lh-control-sm);
  color: var(--text-muted);
}

.skill-detail-hint-svg {
  width: var(--icon-sm);
  height: var(--icon-sm);
  flex-shrink: 0;
  /* 与首行文字视觉居中：图标 14px + 行盒 16px。 */
  margin-top: 1px;
  color: var(--text-muted);
}

/* chips：12px / 400、描边而非实底（标签是信息，不是控件）。 */
.skill-detail-tags {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
}

.skill-detail-chip {
  display: inline-flex;
  align-items: center;
  height: var(--badge-h);
  padding: 0 var(--space-2);
  border: 1px solid var(--control-border);
  border-radius: var(--radius-control);
  font-size: var(--ds-font-helper);
  font-weight: 400;
  line-height: var(--lh-control-sm);
  white-space: nowrap;
  color: var(--text-muted);
  background: transparent;
}

/* 技能类别 / 来源两枚：来源与类别是身份信息，走极浅面把自己与「标签」区分开。 */
.skill-detail-chip.is-kind,
.skill-detail-chip.is-source {
  border-color: transparent;
  background: var(--ds-surface);
  color: var(--text);
}

.skill-detail-chip.is-source {
  color: var(--text-muted);
}

/* 示例：逐条成行。 */
.skill-detail-examples {
  margin: 0;
  padding-left: 22px;
  color: var(--text);
  font-size: var(--ds-font-sm);
  line-height: var(--lh-control);
}

.skill-detail-examples li {
  padding: 3px 0;
}

/* 说明书（来自技能文件的 `## 员工口径`）：段落 / `-` 列表 / `###` 小标题，都用正文档。 */
.skill-doc-heading {
  margin: 0;
  font-size: var(--ds-font-helper);
  font-weight: 500;
  line-height: var(--lh-control-sm);
  color: var(--text-muted);
}

.skill-doc-para {
  margin: 0;
  font-size: var(--ds-font-sm);
  line-height: var(--lh-control);
  color: var(--text);
}

.skill-doc-list {
  margin: 0;
  padding-left: 22px;
  font-size: var(--ds-font-sm);
  line-height: var(--lh-control);
  color: var(--text);
}

.skill-detail-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  padding: var(--space-5);
  color: var(--text-muted);
  font-size: var(--ds-font-helper);
  line-height: var(--lh-control-sm);
  text-align: center;
}

.skill-detail-footer {
  display: flex;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-4);
  border-top: 1px solid var(--border);
  flex-shrink: 0;
}

.skill-detail-footer .skill-btn {
  flex: 1 1 0;
  min-width: 0;
  justify-content: center;
  white-space: nowrap;
  height: var(--control-h-lg);
  font-size: var(--ds-font-sm);
}

/* 执行契约：分区线 + 工具行边框都走发丝线（装饰），文字走文字档。 */
.skill-detail-steps {
  margin: 0;
  padding-left: 22px;
  color: var(--text);
}

.skill-detail-steps li {
  padding: 3px 0;
}

.skill-execution-details {
  margin-top: var(--space-3);
  border-top: 1px solid var(--border);
  padding-top: var(--space-3);
}

.skill-execution-details summary {
  cursor: pointer;
  color: var(--text);
  /* 折叠区标题不再加粗：本页除页标题外没有 600 档（2026-09-23 UI/UX 裁定）。 */
  font-weight: 500;
  line-height: var(--lh-control);
}

.skill-execution-list {
  display: grid;
  gap: 6px;
}

/* 调用工具 / 所需权限条目：一行一个（名称 + 风险档 chip），一行一条发丝线。 */
.skill-execution-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: var(--space-2);
  align-items: center;
  padding: var(--space-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-control);
  font-size: var(--ds-font-sm);
}

.skill-execution-row-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text);
}

/* 窄屏遮罩：只在覆盖态出现。显式声明透明底，避免 <button> 带 UA 默认灰。 */
.skill-detail-scrim {
  display: none;
  background: transparent;
}

/* ── 三轴适配（宽度 / 高度 / 输入模态分别处理） ─────────────────────── */

/* 宽度轴 ≥1280：四栏（左栏 190px / 栏 3 列表 / 栏 4 详情）。
   1024 这类宽度上，顶部筛选条 + 并排详情列会把列表列挤到约 400px（得靠容器查询收标记列）；
   1280 起把筛选条整条搬到左栏 —— 腾出的横向空间还给列表，扫描列数也从「一排等权胶囊」
   变成有分区（口径 / 阶段）的纵向清单。栏 2/3、栏 3/4 之间各一条发丝线，不用间隙，
   三栏顶部对齐同一 y（同一 grid 行）。 */
@media (min-width: 1280px) {
  .skill-catalog-main {
    grid-template-columns: 190px minmax(0, 1fr) auto;
    grid-template-rows: minmax(0, 1fr);
    grid-template-areas: "tabs content pane";
  }
  .skill-tabs {
    width: 190px;
    flex-direction: column;
    align-items: stretch;
    gap: var(--space-1);
    /* 上内边距搬到吸顶的栏头里：它吸住时上下留白才不会跳。 */
    padding: 0 var(--space-3) var(--space-3);
    border-bottom: 0;
    border-right: 1px solid var(--border);
    overflow-y: auto;
  }
  /* 栏 2 顶部标题吸顶：口径组与阶段组从它下面滑过，栏头始终说明「这一栏是什么 / 多少项」。
     底色必须自带，否则滑过去的 tab 会从字缝里透出来。 */
  .skill-catalog-title {
    position: sticky;
    top: 0;
    left: auto;
    z-index: 1;
    align-self: stretch;
    /* 左内边距对齐 tab 的词：tab 是 2px 选中线 + 8px 内边距，栏头跟着走才不会看着歪。 */
    padding: var(--space-3) 0 var(--space-2) calc(var(--space-2) + 2px);
    margin-right: 0;
    background: var(--bg);
  }
  .skill-tabs-list {
    flex-direction: column;
    align-items: stretch;
    gap: 2px;
  }
  /* 口径组与阶段组分上下两区：横线替代横向档的竖线。 */
  .skill-tabs-list[data-kind="stage"] {
    border-left: 0;
    padding-left: 0;
    margin-top: var(--space-2);
    padding-top: var(--space-2);
    border-top: 1px solid var(--border);
  }
  /* 纵向顺序本身已表达「建联 → 内容发布」的递进，› 分隔符收掉。 */
  .skill-tab-sep {
    display: none;
  }
  /* 整行可点：命中区是整行宽度，选中信号从横向档的 2px 底线挪到左侧 2px 竖线
     （底线宽度归 0，不渲染；形状 + 底色 + 字重三重信号保留，状态不只靠颜色）。 */
  .skill-tab {
    width: 100%;
    justify-content: flex-start;
    padding: 6px var(--space-2);
    border-bottom: 0;
    border-left: 2px solid transparent;
    min-height: var(--control-h-lg);
    margin-bottom: 0;
  }
  .skill-tab:hover {
    background: var(--surface-hover);
  }
  .skill-tab.on {
    border-left-color: var(--accent);
    background: var(--ds-selected-bg);
    color: var(--accent-text);
    font-weight: 500;
  }
  /* 右缘渐隐只在横向滚动条上有意义。 */
  .skill-tabs-fade {
    display: none;
  }
  .skill-catalog-content {
    min-width: 0;
  }
}

/* 宽度轴 ≤900：详情列改覆盖层，不把交互内容藏掉；浮层边界靠遮罩 + 发丝线表达。 */
@media (max-width: 900px) {
  .skill-detail-pane {
    display: none;
  }
  /* 覆盖态宽度必须同时容纳 is-wide，否则「展开」在这个区间点了没反应。 */
  .skill-detail-pane.is-open {
    display: block;
    position: fixed;
    inset: 0 0 0 auto;
    width: min(100%, 480px);
    z-index: var(--layer-popover);
    border-left: 1px solid var(--border);
  }
  /* 覆盖态下「展开」= 占满全宽。 */
  .skill-detail-pane.is-open.is-wide {
    width: 100%;
  }
  .skill-detail-close {
    display: inline-flex;
    align-items: center;
  }
  .skill-detail-scrim.is-open {
    display: block;
    position: fixed;
    inset: 0;
    z-index: calc(var(--layer-popover) - 1);
    border: 0;
    padding: 0;
    background: rgba(0, 0, 0, 0.32);
    cursor: pointer;
  }
}

@media (max-width: 768px) {
  /* 搜索框已在中栏顶部：窄屏让它占满中栏宽度，不再有 240px 下限。 */
  .skill-search-wrap {
    width: 100%;
    min-width: 0;
  }
}

/* 宽度轴：行内列宽按**列表列的实际宽度**收敛（容器查询），不按视口。
   详情列与列表并排，视口宽 ≠ 列表宽：1024 视口下列表列只剩约 400px，
   按视口判断会把「标记」挤出可视区（实测 1024×589 被裁掉）。
   docs/DESIGN.md §不变量 5：绝不允许溢出被 overflow:hidden 静默裁切。 */
.skill-list {
  container-type: inline-size;
}

@container (max-width: 415px) {
  /* 先收标记列：风险档与异步契约在详情列里仍有完整交代。
     阈值按列表列实测取（三栏改造后重新量过）：≥1280 起左栏占 190px，最窄的三栏场景
     （1280 视口）列表列约 436px —— 标记要留住；1024 视口（筛选条在顶部、详情列并排）
     只剩约 395px —— 再放标记就会挤掉描述列。边界取两者中间。 */
  .skill-row {
    grid-template-columns: var(--control-h-lg) minmax(96px, 0.9fr) minmax(120px, 1.4fr);
  }
  .skill-row-marks {
    display: none;
  }
  /* 标记列收起后 L3 仍要看得见（§不变量 2 的 L1/L2/L3 分档可见）：实线＝执行前确认，
     暖色底＝受控动作；与异步的虚线不同形状，不只靠颜色。
     （异步的虚线砖已是全宽度信号，见基础规则 .skill-row.is-async .skill-row-icon。） */
  .skill-row.is-write .skill-row-icon {
    border: 1px solid var(--warning);
    background: color-mix(in srgb, var(--warning) 10%, var(--bg));
    color: color-mix(in srgb, var(--warning) 72%, var(--text));
  }
}

@container (max-width: 399px) {
  /* 再窄就折成两行两列：名称在第一行第 2 列，摘要占满第二行。 */
  .skill-row {
    grid-template-columns: var(--control-h-lg) minmax(0, 1fr);
    grid-template-rows: auto auto;
    gap: var(--space-1) var(--space-2);
    padding-block: var(--space-2);
  }
  .skill-row-name {
    grid-column: 2;
    grid-row: 1;
  }
  .skill-row-desc {
    grid-column: 2;
    grid-row: 2;
  }
}

/* 页级留白：窄屏收紧（与列表列宽无关，走视口宽度）。改的是内容列的留白变量，
   搜索行的全栏铺满（负外边距）跟着一起收，不会多出一截。 */
@media (max-width: 640px) {
  .skill-catalog-content {
    --skill-content-pad: var(--space-3);
  }
  /* 分组提示只是辅助说明，窄屏让位给标题与「查看全部」。 */
  .skill-group-hint {
    display: none;
  }
}

/* 输入模态轴：触摸设备命中区提到 44px。与宽度无关 —— 触摸笔记本走桌面布局 + 触摸命中区。 */
@media (pointer: coarse) {
  .skill-tab {
    min-height: 44px;
  }
  .skill-row-name,
  .skill-group-more {
    min-height: 44px;
  }
  /* 提问框的 + 菜单行与档位触发器：桌面 40/32px，触摸提到 44px（docs/DESIGN.md §控件尺寸）。 */
  .composer-menu-section > button,
  .tier-trigger,
  .tier-panel .tier-panel-more a {
    min-height: 44px;
  }
  /* 首页快捷入口、任务筛选与任务操作：触摸模态只扩命中区至 44px。 */
  .home-quick-tasks button,
  .task-board-tab,
  .task-board-attention-filter,
  .task-board-refresh,
  .task-board-clear-filter,
  .task-board-open,
  .task-board-edit {
    min-height: 44px;
  }
  /* 账户块分段与图标按钮：触摸模态命中区 44px（docs/DESIGN.md §控件尺寸）。 */
  .surface-switch {
    height: auto;
  }
  .surface-switch-seg,
  .account-icon-btn {
    min-width: 44px;
    min-height: 44px;
  }
}

/* 高度轴：矮窗收紧节奏。与宽度无关 —— 1280×800 这类笔记本宽度够但高度不够。 */
@media (max-height: 900px) {
  .skill-catalog-content {
    /* 搜索行按这个变量扣多余间距（见 .skill-search-row），换档时必须跟着走。 */
    --skill-content-gap: var(--space-4);
    gap: var(--skill-content-gap);
    padding-block: var(--space-3) var(--space-4);
  }
}

@media (prefers-reduced-motion: reduce) {
  .skill-row {
    transition: none;
  }
}

/* ── T6：Result toolbar + Creator lead row（框线稿 §页面结构 3/4、§组件、§Auto Layout） ── */
.discovery-run-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--ds-space-3) var(--ds-space-4);
}
.discovery-run-count { font-size: var(--ds-font-body); font-weight: 600; color: var(--text); }
.discovery-run-sort { font-size: var(--ds-font-helper); line-height: var(--ds-line-helper); color: var(--ds-text-dim); }

/* 候选列表：Vertical gap 0，以 1px 分隔线区分，不给每行套独立卡片。 */
.discovery-candidate-list {
  display: flex;
  flex-direction: column;
  gap: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}
.discovery-follow-quiet { display: inline-flex; align-items: center; min-height: var(--control-h-sm); margin: 0; padding: 0 var(--space-1); border: 0; border-radius: var(--radius-control); background: transparent; color: var(--accent-text); font: inherit; font-size: var(--ds-font-helper); line-height: var(--ds-line-helper); text-decoration: none; cursor: pointer; }
.discovery-follow-quiet:hover:not(:disabled) { background: var(--btn-text-hover-bg); }
.discovery-follow-quiet:focus-visible { outline: var(--focus-ring-width) solid var(--focus-ring); outline-offset: var(--focus-ring-offset); }
.discovery-follow-quiet[data-discovery-followup][aria-pressed="true"] { font-weight: 600; }
.discovery-follow-quiet:disabled { opacity: .45; cursor: not-allowed; }
.discovery-follow-quiet.is-disabled, .discovery-follow-quiet[aria-disabled="true"] { color: var(--text-muted); cursor: not-allowed; }
@media (pointer: coarse) { .discovery-follow-quiet { min-height: var(--touch-hit-min); } }

/* ── T7：成功态暗色 / 对比度 ── */
:root {
  /* 成功色只给 AI发现 状态卡用；暗色下换亮一档，别改全局 --success。 */
  --discovery-success: var(--color-success-vivid);
}
:root[data-theme="dark"] { --discovery-success: #4bb99f; }
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) { --discovery-success: #4bb99f; }
}
/* 成功状态：绿点 + 绿字 + 状态文案三者并存（不靠颜色单独传达）。 */
.discovery-status-card.is-ok .discovery-status-dot { background: var(--discovery-success); }
.discovery-status-card.is-ok .discovery-status-copy,
.discovery-status-card.is-ok .discovery-status-state { color: var(--discovery-success); }

/* ── 全局视觉 token（Design System v1） ──────────────────────────────────
   一套尺度给全站用：间距走 8px 网格，圆角按层级分档，颜色/字号只从这里取。
   页面不要各自写死 px，直接引用 --ds-*；新页面必须先落 token 再落样式。
   密度分两档：默认（宽屏）与紧凑（窄屏或矮窗，见文末 media），紧凑档只收紧间距与控件高度，
   不动颜色和字号层级——同一套结构，两种呼吸感。 */
:root {
  /* 间距：8px 网格 */
  --ds-space-1: 4px;
  --ds-space-2: 8px;
  --ds-space-3: 12px;
  --ds-space-4: 16px;
  --ds-space-5: 20px;
  --ds-space-6: 24px;
  --ds-space-8: 32px;
  --ds-space-12: 48px;

  /* 页面与分区 */
  --ds-page-pad-x: 48px;
  --ds-section-gap: var(--ds-space-8);
  --ds-row-gap: var(--ds-space-5);

  /* 圆角层级：容器略大、输入与普通状态标签统一紧凑；身份头像可单独使用满圆角。 */
  --ds-radius-page: 20px;
  --ds-radius-section: 8px;
  --ds-radius-input: 6px;
  --ds-radius-chip: 6px;
  --ds-radius-tag: 6px;

  /* 控件尺寸 */
  --ds-control-h: 44px;
  --ds-control-w: 180px;
  --ds-label-w: 120px;
  --ds-chip-h: 40px;
  --ds-chip-gap: var(--ds-space-2);

  /* 中性色：品牌色仍然只引用既有 --color-primary */
  --ds-border: #e5e7eb;
  --ds-surface: #f7f8f8;
  --ds-surface-hover: #f1f2f3;
  /* 选中态三档权重：底色 10% / 描边 35% / 文字 100%。
     按 docs/DESIGN.md §颜色：选中属「辅助」→ 由 --accent（蓝）派生，不再用品牌粉
     （粉只留给唯一的主行动 CTA）。 */
  --ds-selected-bg: color-mix(in srgb, var(--accent) 10%, #fff);
  --ds-selected-border: color-mix(in srgb, var(--accent) 35%, transparent);

  /* 文字四档：从「最重」到「最弱」，页面里所有文字颜色都从这里取。
     strong 标题/强调 · text 正文 · dim 次要说明 · muted 最弱（计数、占位、次要元信息）。
     dim 直接挂在既有的 --text-muted 上，暗色自动跟随，不再各页写一套灰。 */
  --ds-text-strong: var(--text);
  --ds-text: var(--text);
  --ds-text-dim: var(--text-muted);
  --ds-text-muted: #9ca3af;
  /* 旧名保留一个版本，避免遗漏的引用断掉 */
  --ds-text-secondary: var(--ds-text-dim);

  /* 字号阶梯：页面 → 块标题 → 分区 → 正文界面 → 正文字段 → 小字 → 辅助 → 标签。
     13px 是全站最常见的界面字号（表格、chip、元信息），15px 是正文界面字号，
     14px 留给表单控件，12.5/11.5/10.5 这类半像素值一律归到最近的档。 */
  --ds-font-title: 28px;       --ds-line-title: 36px;       --ds-weight-title: 700;
  --ds-font-block-title: 20px; --ds-line-block-title: 28px; --ds-weight-block-title: 600;
  --ds-font-desc: 15px;        --ds-line-desc: 24px;
  --ds-font-section: 16px;     --ds-line-section: 24px;     --ds-weight-section: 600;
  --ds-font-ui: 15px;          --ds-line-ui: 24px;
  --ds-font-body: 14px;        --ds-line-body: 20px;
  --ds-font-label: 14px;       --ds-line-label: 20px;       --ds-weight-label: 500;
  --ds-font-sm: 13px;          --ds-line-sm: 20px;
  --ds-font-helper: 12px;      --ds-line-helper: 18px;
  --ds-font-tag: 11px;         --ds-line-tag: 16px;
}
:root[data-theme="dark"] {
  --ds-border: #2f3134;
  --ds-surface: #1f2124;
  --ds-surface-hover: #26282b;
  --ds-text-strong: #ffffff;
  --ds-text-muted: #77808c;
  --ds-selected-bg: color-mix(in srgb, var(--accent) 22%, transparent);
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --ds-border: #2f3134;
    --ds-surface: #1f2124;
    --ds-surface-hover: #26282b;
    --ds-text-strong: #ffffff;
    --ds-text-muted: #77808c;
    --ds-selected-bg: color-mix(in srgb, var(--accent) 22%, transparent);
  }
}

/* AI发现 页的内容列与左右留白都取 token：1920 屏下内容宽 1200；1440 屏受 260 侧栏所限，
   内容宽 1180 − 2×留白（留白本身仍是响应式的，上限 48）。 */
[data-home][data-home-active-mode="discovery"] {
  --content-max: 1280px;
  --page-gutter: clamp(var(--ds-space-5), 2.4vw, var(--ds-page-pad-x));
}

/* ── 紧凑密度档：窄屏（<1440）或矮窗（<=900）──────────────────────────
   1280×800 这类笔记本上，宽屏那套节奏（chip 40 / 行距 20 / 分区距 32）会让检索区
   比可见区域还高，整页要滚动才能看完，读起来就「散」。这里只收紧间距与控件高度：
   颜色、字号层级、圆角一律不动，所以两个档位看起来仍是同一个产品。 */
@media (max-width: 1439px), (max-height: 900px) {
  :root {
    --ds-space-4: 12px;
    --ds-space-5: 10px;
    --ds-space-6: 16px;
    --ds-space-8: 20px;
    --ds-page-pad-x: 32px;
    --ds-section-gap: 16px;
    --ds-row-gap: 8px;
    --ds-label-w: 96px;
    --ds-control-h: 40px;
    --ds-chip-h: 32px;
    --ds-font-block-title: 18px;
    --ds-line-block-title: 26px;
  }
  /* 数值框跟着列宽走，窄屏下不再留一截空档。 */
  .ai-discovery-card .ai-discovery-input.is-number {
    flex: 1 1 0;
    width: auto;
    max-width: 200px;
  }
}

/* Tablet 1024：并排的两项收成一列；候选行只留一级字段
   （隐藏二级指标：播放中位数/稳定度/采集时间/在库状态）。 */
@media (max-width: 1024px) {
  .ai-discovery-rows.is-pair { grid-template-columns: minmax(0, 1fr); }
}

/* ── 邮箱通讯：三栏（左邮箱树 / 中人机互动 / 右邮件详情） ──────────────────
   分栏照应用基线（docs/DESIGN.md）：一条 1px 发丝线、gap 0、无外框卡片、
   无圆角、无阴影，页面底统一 --canvas；三栏各自滚动，右栏不用魔法 max-height。 */
.mail-page { background: var(--canvas); }

.mail-split {
  grid-template-columns: minmax(280px, 320px) minmax(0, 1fr) clamp(360px, 30%, 440px);
  gap: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  overflow: visible;
  align-items: stretch;
}
/* 列边界只有一条 1px 发丝线：由每栏自己的 border-left 画，避免 2px 双线。 */
.mail-interact {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  border-left: 1px solid var(--ds-border);
  padding: var(--space-3) var(--space-4);
}
.mail-detail {
  border-left: 1px solid var(--ds-border);
  padding: var(--space-3) var(--space-4) var(--space-4);
}
.mail-interact,
.mail-detail {
  min-width: 0;
  height: 100%;
  overflow-x: hidden;
  overflow-y: auto;
}
/* 页级面板切换：桌面三栏同屏，只在单栏档出现。 */
.mail-panes {
  display: none;
  gap: 2px;
  border-bottom: 1px solid var(--ds-border);
}
.mail-panes button {
  flex: 1 1 0;
  margin-bottom: -1px;
  padding: 7px 2px 8px;
  border: 0;
  border-bottom: 2px solid transparent;
  background: none;
  color: var(--ds-text-dim);
  font: inherit;
  font-size: var(--ds-font-sm);
  white-space: nowrap;
  cursor: pointer;
}
.mail-panes button[aria-pressed="true"] {
  color: var(--text);
  border-bottom-color: var(--accent);
  font-weight: 500;
}

.mail-interact-feedback {
  display: grid;
  gap: var(--space-2);
  min-width: 0;
  padding-top: var(--space-2);
  border-top: 1px solid var(--ds-border);
}
.mail-interact-feedback > .error,
.mail-interact-feedback > .muted { margin: 0; font-size: var(--ds-font-helper); }
.mail-interact-dock { margin-top: auto; }
.mail-interact .composer-dock { padding: 0; background: transparent; }
/* 通讯页阶段变更：绑定红人的当前阶段 + 目标阶段入口，紧贴提问框上方。 */
.mail-stage-change {
  display: grid;
  gap: var(--space-2);
  padding: var(--space-2) 0;
  border-top: 1px solid var(--ds-border);
}
.mail-stage-change > .mail-pane-label { margin: 0; }
.mail-stage-change-row { display: flex; align-items: center; gap: var(--space-1); flex-wrap: wrap; font-size: var(--ds-font-helper); }
.mail-stage-kol {
  border: 1px solid var(--ds-border);
  border-radius: var(--ds-radius-sm);
  background: var(--ds-surface);
  color: var(--accent);
  font-size: var(--ds-font-helper);
  padding: 2px 8px;
  cursor: pointer;
}
.mail-stage-kol:hover { border-color: var(--accent); }
.mail-stage-target { display: flex; align-items: center; gap: var(--space-2); font-size: var(--ds-font-helper); }
.mail-stage-target > span { flex: none; }
.mail-stage-target select {
  flex: 1;
  min-width: 0;
  border: 1px solid var(--ds-border);
  border-radius: var(--ds-radius-sm);
  background: var(--ds-surface);
  color: var(--text);
  font-size: var(--ds-font-helper);
  padding: 4px 8px;
}
.mail-stage-change > .muted { margin: 0; font-size: var(--ds-font-helper); }

@media (max-width: 1439px) {
  .mail-split { grid-template-columns: minmax(260px, 300px) minmax(0, 1fr) clamp(320px, 32%, 400px); }
}
/* ≤1100px 收成一栏，列边界随之消失；三块面板由 .mail-panes 切换，
   选邮件自动切到详情，所以正文与 data-mail-mobiletabs 都够得着。 */
@media (max-width: 1100px) {
  .mail-split { grid-template-columns: minmax(0, 1fr); }
  .mail-panes { display: flex; }
  .mail-split .mail-interact,
  .mail-split .mail-detail { border-left: 0; }
  .mail-split:not(.mail-pane-skeleton) .mail-list,
  .mail-split:not(.mail-pane-skeleton) .mail-interact,
  .mail-split:not(.mail-pane-skeleton) .mail-detail { display: none; }
  .mail-split[data-mail-pane-active="list"] .mail-list { display: grid; }
  .mail-split[data-mail-pane-active="interact"] .mail-interact { display: flex; }
  .mail-split[data-mail-pane-active="detail"] .mail-detail { display: block; }
}

/* ── 页头一行：标题 + 邮箱切换器 + 收取 + 同步/未读 meta ─────────────────── */
.mail-hero {
  align-items: center;
  justify-content: flex-start;
  gap: var(--space-2) var(--space-3);
}
.mail-hero-title {
  margin: 0;
  font-size: var(--ds-font-block-title);
  font-weight: 600;
  line-height: var(--leading-tight);
}
.mail-hero-meta {
  margin: 0;
  color: var(--ds-text-dim);
  font-size: var(--ds-font-helper);
}
.mail-unbound-line {
  margin: 0;
  font-size: var(--ds-font-sm);
}
.mail-switcher { margin-bottom: 0; gap: var(--space-2); }
.mail-switcher-current {
  flex: 0 1 auto;
  max-width: none;
  gap: 6px;
  padding: 0 10px;
  height: 30px;
  border: 1px solid var(--ds-border);
  border-radius: var(--radius-control);
  background: var(--bg);
  font-size: var(--ds-font-sm);
}
.mail-switcher-addr {
  overflow: visible;
  text-overflow: clip;
  font-size: var(--ds-font-sm);
  white-space: nowrap;
}
.mail-switcher-caret { margin-left: 0; color: var(--ds-text-muted); font-size: var(--ds-font-tag); }
.mail-switcher-menu {
  border: 1px solid var(--ds-border);
  border-radius: var(--radius-card);
  background: var(--bg);
  box-shadow: var(--shadow-quiet);
}
.mail-switcher-title { margin: 2px 6px 4px; font-size: var(--ds-font-helper); }
.mail-switcher-option { padding: 6px 8px; border-radius: var(--radius-control); }
.mail-switcher-option:hover { background: var(--ds-surface-hover); }
.mail-switcher-option.is-active { background: var(--ds-selected-bg); }
.mail-switcher-option-main strong { font-size: var(--ds-font-sm); font-weight: 600; }
.mail-switcher-option-main .muted { font-size: var(--ds-font-helper); }
.mail-switcher-option .mail-count-pill,
.mail-switcher-current .mail-count-pill { font-size: var(--ds-font-helper); }
.mail-switcher-foot { border-top: 1px solid var(--ds-border); }
.mail-switcher-foot .btn { height: 28px; font-size: var(--ds-font-helper); }

/* ── 左栏三级树：L1 对方邮箱 + 主题数 / L2 主题 + 邮件数 / L3 标题 + 已读 + 收发时间 ── */
.mail-list { gap: 0; }
.mail-list-tools { gap: var(--space-2); margin-bottom: var(--space-2); padding: var(--space-2) var(--space-3) 0; }
.mail-search-row { gap: var(--space-2); }
.mail-search-wrap {
  gap: 6px;
  height: 30px;
  padding: 0 8px 0 10px;
  border: 1px solid var(--ds-border);
  border-radius: var(--radius-control);
  background: var(--ds-surface);
}
.mail-search-wrap .mail-ico { width: 14px; height: 14px; }
.mail-search { height: 100%; font-size: var(--ds-font-sm); }
.mail-filter-btn {
  width: 30px;
  height: 30px;
  flex: 0 0 30px;
  border: 1px solid var(--ds-border);
  border-radius: var(--radius-control);
  background: var(--bg);
  font-size: var(--ds-font-sm);
}
.mail-filter-btn .mail-ico { width: 14px; height: 14px; }
.mail-list-tabs button { padding: 5px 2px 6px; font-size: var(--ds-font-sm); }
.mail-empty-list { margin: 0; padding: var(--space-3); font-size: var(--ds-font-sm); }

.mail-row {
  grid-template-columns: 10px minmax(0, 1fr) auto auto;
  gap: 0 var(--space-2);
  align-items: center;
  padding: 7px var(--space-3);
  border: 0;
  border-bottom: 1px solid var(--ds-border);
  border-left: 3px solid transparent;
  border-radius: 0;
  background: transparent;
}
.mail-row:hover { background: var(--ds-surface); }
.mail-row:last-child { border-bottom: 0; }
.mail-row-caret {
  color: var(--ds-text-muted);
  font-size: var(--ds-font-tag);
  line-height: var(--ds-line-ui);
}
.mail-correspondent.is-open .mail-row-caret { color: var(--accent-text); }
.mail-row-addr,
.mail-row-subject {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--ds-font-body);
}
.mail-correspondent .mail-row-addr { font-weight: 500; }
.mail-conversation { padding-left: var(--space-5); }
.mail-conversation .mail-row-subject { font-size: var(--ds-font-sm); }
.mail-conversation.is-current .mail-row-subject { color: var(--accent-text); font-weight: 500; }
.mail-row-count-tag {
  color: var(--ds-text-dim);
  font-size: var(--ds-font-helper);
  white-space: nowrap;
}
.mail-conversation-list { padding-left: 0; margin-left: 0; border-left: 0; }

.mail-timeline {
  position: relative;
  gap: 2px;
  padding: 0 0 var(--space-2);
  background: transparent;
}
.mail-timeline::before { display: none; }
.mail-timeline-empty { margin: 0; padding: 4px var(--space-3) var(--space-2) 40px; font-size: var(--ds-font-helper); }
.mail-timeline-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 2px;
  width: 100%;
  padding: 6px var(--space-3) 6px 40px;
  border: 0;
  border-left: 3px solid transparent;
  background: none;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.mail-timeline-item::before { display: none; }
.mail-timeline-item:hover { background: var(--ds-surface); }
.mail-timeline-item.is-selected {
  background: var(--ds-selected-bg);
  border-left-color: var(--accent);
}
.mail-timeline-item.is-selected .mail-timeline-subject { color: var(--accent-text); font-weight: 500; }
.mail-timeline-subject {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--ds-font-sm);
}
.mail-timeline-meta { display: flex; align-items: center; gap: var(--space-2); }
.mail-timeline-meta time { font-size: var(--ds-font-helper); }
.mail-read-tag { color: var(--ds-text-dim); font-size: var(--ds-font-helper); }
.mail-read-tag.is-unread { color: var(--accent-text); font-weight: 600; }

/* ── 中栏：邮件任务 chip（上）+ 提问框（下） ─────────────────────────────── */
.mail-interact-tasks { display: grid; gap: var(--space-2); }
.mail-pane-label { margin: 0; color: var(--ds-text-dim); font-size: var(--ds-font-helper); }
.mail-task-chips { display: flex; flex-wrap: wrap; gap: var(--space-1); }
.mail-task-chip,
.mail-task-more {
  height: 28px;
  padding: 0 10px;
  border: 1px solid var(--ds-border);
  border-radius: var(--radius-control);
  background: var(--bg);
  color: var(--text);
  font: inherit;
  font-size: var(--ds-font-sm);
  white-space: nowrap;
  cursor: pointer;
}
.mail-task-disclosure { display: inline-flex; align-items: center; }
.mail-task-disclosure > summary {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 28px;
  padding: 0 2px;
  border: 0;
  background: transparent;
  color: var(--accent-text);
  font: inherit;
  font-size: var(--ds-font-sm);
  white-space: nowrap;
  cursor: pointer;
  list-style: none;
}
.mail-task-disclosure > summary::-webkit-details-marker { display: none; }
.mail-task-disclosure > summary:hover { text-decoration: underline; }
.mail-accordion-icon { color: var(--ds-text-muted); font-size: var(--ds-font-helper); line-height: 1; }
.mail-task-chip:hover { border-color: var(--accent); color: var(--accent-text); }

/* ── 右栏：往来摘要 / 中文翻译 / 原文 三个折叠 ──────────────────────────── */
.mail-detail-head {
  display: grid;
  gap: var(--space-1);
  padding-bottom: var(--space-2);
  border-bottom: 1px solid var(--ds-border);
}
.mail-thread-head {
  display: flex;
  flex-wrap: wrap;
  gap: 2px 10px;
  align-items: baseline;
  justify-content: start;
  min-width: 0;
}
.mail-thread-head h2 {
  margin: 0;
  min-width: 0;
  font-size: var(--ds-font-section);
  font-weight: 600;
  line-height: var(--ds-line-section);
}
.mail-thread-head p { margin: 0; min-width: 0; font-size: var(--ds-font-helper); }
.mail-fold { padding: var(--space-3) 0; border-bottom: 1px solid var(--ds-border); }
.mail-fold:last-child { border-bottom: 0; padding-bottom: 0; }
.mail-fold-head {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
}
.mail-fold-toggle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  padding: 0;
  border: 0;
  background: none;
  color: var(--text);
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.mail-fold-caret { color: var(--ds-text-muted); font-size: var(--ds-font-tag); }
.mail-fold-head .mail-side-title { font-size: var(--ds-font-sm); font-weight: 600; }
.mail-side-action {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-left: auto;
  height: 28px;
  padding: 0 9px;
  border: 1px solid var(--ds-border);
  border-radius: var(--radius-control);
  background: var(--bg);
  color: var(--ds-text-dim);
  font: inherit;
  font-size: var(--ds-font-helper);
  white-space: nowrap;
  cursor: pointer;
}
.mail-side-action:hover:not(:disabled) { border-color: var(--accent); color: var(--accent-text); }
.mail-side-action:disabled { cursor: wait; opacity: .65; }
.mail-side-action .mail-ico { width: 14px; height: 14px; }
.mail-fold-body { display: grid; gap: var(--space-2); padding-top: var(--space-2); }
.mail-fold-body[hidden] { display: none; }
.mail-fold-inner { display: grid; gap: var(--space-2); }
.mail-side-tag {
  padding: 1px 6px;
  border: 1px solid var(--ds-border);
  border-radius: var(--ds-radius-tag);
  background: var(--ds-surface);
  color: var(--ds-text-dim);
  font-size: var(--ds-font-helper);
}
.mail-side-count { margin: 0; color: var(--ds-text-dim); font-size: var(--ds-font-helper); }
.mail-side-hint { margin: 0; font-size: var(--ds-font-helper); }
.mail-side-body { font-size: var(--ds-font-sm); line-height: 1.65; color: var(--text); }
.mail-side-body.is-clamped {
  display: -webkit-box;
  -webkit-line-clamp: 6;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.mail-more-toggle {
  justify-self: start;
  padding: 0;
  border: 0;
  background: none;
  color: var(--accent-text);
  font: inherit;
  font-size: var(--ds-font-helper);
  cursor: pointer;
}
.mail-more-toggle:hover { text-decoration: underline; }
.mail-detail .mail-content {
  display: grid;
  gap: var(--space-2);
  padding: 0;
  border-left: 0;
  background: transparent;
}
.mail-content-meta { display: flex; align-items: center; gap: 10px; }
.mail-content-who { display: grid; gap: 1px; min-width: 0; }
.mail-content-body { white-space: pre-wrap; word-break: break-word; }
.mail-content-body p { margin: 0; }
.mail-detail .mail-content-who strong { font-size: var(--ds-font-sm); }
.mail-detail .mail-content-who .muted { font-size: var(--ds-font-helper); }
.mail-detail .mail-content-meta time { font-size: var(--ds-font-helper); }
.mail-detail .mail-content-body { font-size: var(--ds-font-body); line-height: 1.7; }
.mail-thread-actions {
  position: static;
  gap: 6px;
  margin-top: var(--space-2);
  padding-top: var(--space-3);
  border-top: 1px solid var(--ds-border);
  background: transparent;
}
.mail-thread-actions .btn { height: 30px; padding: 0 12px; font-size: var(--ds-font-sm); }
.mail-thread-actions .mail-ico { width: 14px; height: 14px; }
.mail-thread-actions .mail-more-btn { width: 30px; height: 30px; }

/* ── 骨架：同一条三栏发丝线，只有形状没有内容 ───────────────────────────── */
.mail-pane-skeleton .mps-search,
.mail-pane-skeleton .mps-row,
.mail-pane-skeleton .mps-line,
.mail-pane-skeleton .mps-chip {
  background: var(--ds-surface);
  border-radius: var(--radius-control);
  animation: mps-pulse 1.6s ease-in-out infinite;
}
.mail-pane-skeleton .mps-search { height: 30px; margin: var(--space-2) var(--space-3) var(--space-2); }
.mail-pane-skeleton .mps-row { height: 38px; margin: 0 var(--space-3) var(--space-1); }
.mail-pane-skeleton .mps-chip-row { display: flex; gap: var(--space-1); margin-bottom: var(--space-3); }
.mail-pane-skeleton .mps-chip { height: 28px; width: 76px; }
.mail-pane-skeleton .mps-line { height: 10px; margin-bottom: var(--space-2); }
.mail-pane-skeleton .mps-line.is-meta { height: 12px; width: 46%; }
.mail-pane-skeleton .mps-line.is-subject { height: 16px; width: 68%; margin-bottom: var(--space-3); }
.mail-pane-skeleton .mps-line.is-block { height: 54px; margin-bottom: var(--space-3); }
@keyframes mps-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.55; } }

.mail-unbound {
  display: grid;
  gap: var(--space-3);
  justify-items: start;
  padding: var(--space-4);
  border: 1px solid var(--ds-border);
  border-radius: var(--radius-card);
  background: var(--bg);
}
/* The workbench wants a fixed 330/540/350 frame: lift the shared 1360px page
   cap and trim the gutter for this page only (same move as skill-catalog).
   The shared rule is  with a
   higher specificity, so this override has to out-weigh it explicitly. */
.main > .list-page.mail-page.mail-page.mail-page {
  width: 100% !important;
  max-width: none !important;
  padding-left: 8px !important;
  padding-right: 8px !important;
}

/* ── 字号与控件收敛：内容 14/13、meta 12、页标题 20，全部走 --ds-* token ───
   半像素字号（10.5/11.5/12.5/13.5）与裸灰阶（#ECECF0/#F7F7F8/#F5F5F7/#9AA0A8）
   在本页一律不再出现；控件 28–32px 高、圆角 --radius-control。 */
.mail-page .btn,
.mail-page .mail-filter-btn {
  height: 30px;
  padding: 0 12px;
  border-radius: var(--radius-control);
  gap: 6px;
  font-size: var(--ds-font-sm);
}
.mail-page .mail-hero .btn.work { height: 30px; padding: 0 14px; }
.mail-page .mail-ico { width: 14px; height: 14px; }
.mail-page .mail-thread-actions .mail-ico { width: 14px; height: 14px; }

.mail-page .mail-star {
  /* WCAG 2.2 SC 2.5.8：星标是独立按钮，命中区不小于 24×24。 */
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 24px;
  min-height: 24px;
  padding: 0;
  font-size: var(--ds-font-section);
  color: var(--ds-text-muted);
}
.mail-page .mail-count-pill { padding: 1px 6px; font-size: var(--ds-font-helper); }
.mail-page .mail-chip { padding: 1px 6px; font-size: var(--ds-font-helper); }
.mail-page .mail-row-avatar {
  width: 28px;
  height: 28px;
  font-size: var(--ds-font-helper);
  line-height: 28px;
}
.mail-page .mail-popover button { font-size: var(--ds-font-sm); }
.mail-page .mail-timeline-item time { font-size: var(--ds-font-helper); }
.mail-page .mail-content-meta time { font-size: var(--ds-font-helper); }
.mail-page .mail-content-body { font-size: var(--ds-font-body); line-height: 1.7; }

/* ── 邮箱通讯：四栏独立工作台（侧栏 / 邮箱 / 提问 / 详情） ────────────────
   邮箱页不再占用跨栏标题行；第二栏承担邮箱选择与同步状态，三块内容栏各自
   管理滚动，和「新工作任务」的工作台壳层保持同一独立列模型。 */
.main > .list-page.mail-page.mail-page.mail-page {
  height: 100% !important;
  min-height: 0;
  padding: 0 !important;
  overflow: hidden !important;
}
.mail-page { gap: 0; }
.mail-split {
  min-height: 0;
  overflow: hidden;
}
.mail-list {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  align-content: stretch;
  gap: 0;
  min-height: 0;
  overflow: hidden;
}
.mail-list-top { min-width: 0; }
.mail-list-top .mail-switcher {
  position: relative;
  display: block;
  margin: 0;
  padding: var(--space-3) var(--space-3) 0;
}
.mail-list-top .mail-switcher-current {
  width: 100%;
  min-width: 0;
  justify-content: flex-start;
}
.mail-list-top .mail-switcher-addr {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.mail-list-top .mail-switcher-caret {
  margin-left: auto;
}
.mail-list-top .mail-switcher-menu {
  position: absolute;
  z-index: 10;
  top: calc(100% + var(--space-1));
  left: var(--space-3);
  min-width: min(280px, calc(100vw - (2 * var(--space-3))));
}
.mail-list-top .mail-list-tools {
  margin: 0;
  padding: var(--space-2) var(--space-3) var(--space-2);
}
.mail-list-scroll {
  min-width: 0;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
}
.mail-list-footer {
  display: grid;
  gap: var(--space-2);
  min-width: 0;
  padding: var(--space-2) var(--space-3) var(--space-3);
  border-top: 1px solid var(--ds-border);
}
.mail-list-footer > .error,
.mail-list-footer > .muted {
  margin: 0;
  font-size: var(--ds-font-helper);
}
.mail-list-statusbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
  min-width: 0;
}
.mail-list-statusbar .mail-hero-meta {
  min-width: 0;
  margin: 0;
  overflow: hidden;
  font-size: var(--ds-font-helper);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mail-list-sync {
  flex: 0 0 auto;
  height: var(--control-h-sm);
  min-height: var(--control-h-sm);
  padding: 0 var(--space-2);
  border: 1px solid var(--ds-border);
  border-radius: var(--radius-control);
  background: var(--bg);
  color: var(--text);
  font: inherit;
  font-size: var(--ds-font-helper);
  cursor: pointer;
}
.mail-list-sync:hover:not(:disabled) {
  border-color: var(--accent);
  color: var(--accent-text);
}
.mail-list-sync:disabled { cursor: wait; color: var(--ds-text-dim); }
.mail-interact,
.mail-detail {
  min-height: 0;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
}
.mail-pane-skeleton .mail-list {
  grid-template-rows: none;
  align-content: start;
}
.mail-list-loading-meta {
  margin: var(--space-3) var(--space-3) 0;
  font-size: var(--ds-font-helper);
}
/* Final Today workspace geometry. Keep these after legacy composer rules so
   the compact empty state remains compact in every desktop bundle order. */
@media (min-width: 1101px) {
  .home-pane[data-home-workspace] {
    position: relative;
  }
  .home-pane[data-home-workspace] .home-stage {
    height: 100%;
    flex: 1 1 auto;
    padding-bottom: 0;
  }
  .home-pane[data-home-workspace] .home-composer-dock .composer.composer--workspace {
    min-height: 76px;
    max-height: 420px;
    padding: 12px 16px 8px;
  }
  .home-pane[data-home-workspace] .home-composer-dock .composer.composer--workspace textarea {
    min-height: 28px;
  }
  .home-pane[data-home-workspace] .scope-task-rail {
    height: 100%;
    min-height: 0;
    overflow-y: auto;
    scrollbar-gutter: stable;
  }
}

/* Generic task workspace: the center column owns its process scroll and its
   complete interaction dock (quick tasks + composer); the result rail scrolls
   independently. These rules intentionally supersede the transitional
   absolute-positioned Today composer above. */
.home-quick-tasks { display: flex; flex-wrap: nowrap; width: 100%; min-width: 0; gap: var(--workspace-tab-gap); align-items: end; overflow-x: auto; padding: 0; border-bottom: 1px solid var(--border); }
.home-quick-tasks button { flex: 0 0 auto; min-height: var(--filter-tab-h); padding: 0 var(--space-1); border: 0; border-bottom: var(--workspace-tab-indicator-h) solid transparent; border-radius: 0; background: transparent; color: var(--text-muted); font: inherit; font-size: var(--ds-font-sm); line-height: var(--ds-line-sm); white-space: nowrap; cursor: pointer; }
.home-mode-label { display: block; min-width: 0; white-space: nowrap; }
.home-quick-tasks button:hover { color: var(--accent-text); }
.home-quick-tasks button[aria-selected="true"] { border-bottom-color: var(--accent); color: var(--accent-text); font-weight: 600; }
.home-quick-tasks button:focus-visible { outline: var(--focus-ring-width) solid var(--focus-ring); outline-offset: var(--focus-ring-offset); }
@media (pointer: coarse) { .home-quick-tasks button { min-height: var(--touch-hit-min); } }
/* 芯片行与中栏内容同一条左缘轴：composer.css 给 .home-composer-dock 设了
   align-items:center，这里在工作台上下文改回左对齐（标题/步骤/推理块全部贴左，
   芯片不再悬在列中间），首尾 2px 内边距一并归零。 */
.home-pane[data-home-workspace] .scope-workspace-center-content > .home-composer-dock {
  align-items: flex-start;
}
.home-pane[data-home-workspace] .home-composer-dock .home-quick-tasks {
  padding-left: 0;
  padding-right: 0;
}
/* 中栏滚动区外包一层定位锚点：「回到底部」按钮钉在滚动视口的右下角，
   不随内容滚动。滚动容器本身仍是 .scope-workspace-center-scroll。 */
.home-pane[data-home-workspace] .scope-workspace-center-scroll-wrap {
  position: relative;
  min-width: 0;
}
.scope-scroll-jump {
  position: absolute;
  right: 24px; /* 避开右侧 scrollbar-gutter 与内容 16px 右内边距 */
  bottom: 12px;
  z-index: 6;
  display: inline-grid;
  /* 与 Home AI 提问框的发送箭头同一紧凑圆形控件尺寸；不要把“查看最新”
     做成更大的悬浮主动作。触摸命中区由输入模态规则单独放大。 */
  width: var(--workspace-arrow-button-size);
  height: var(--workspace-arrow-button-size);
  min-width: var(--workspace-arrow-button-size);
  min-height: var(--workspace-arrow-button-size);
  place-items: center;
  padding: 0;
  border: 1px solid color-mix(in srgb, var(--line) 82%, transparent);
  border-radius: 999px;
  background: var(--canvas);
  box-shadow: 0 2px 8px rgb(15 23 42 / 8%);
  color: var(--text);
  cursor: pointer;
  transition: background-color 160ms ease, border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
}
.scope-scroll-jump::after {
  position: absolute;
  right: 50%;
  bottom: calc(100% + 8px);
  z-index: 1;
  width: max-content;
  max-width: 180px;
  padding: 7px 10px;
  border-radius: 8px;
  background: #191919;
  color: #fff;
  content: attr(data-tooltip);
  font-size: var(--font-sm);
  font-weight: 600;
  line-height: 1.2;
  opacity: 0;
  pointer-events: none;
  transform: translate(50%, 4px);
  transition: opacity 140ms ease, transform 140ms ease;
  white-space: nowrap;
}
.scope-scroll-jump svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.75;
}
.scope-scroll-jump:hover {
  border-color: color-mix(in srgb, var(--text) 20%, var(--line));
  background: var(--chrome-2);
  box-shadow: 0 4px 12px rgb(15 23 42 / 14%);
  transform: translateY(-1px);
}
.scope-scroll-jump:hover::after,
.scope-scroll-jump:focus-visible::after {
  opacity: 1;
  transform: translate(50%, 0);
}
.scope-scroll-jump:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}
@media (min-width: 1101px) {
  .home-pane[data-home-workspace] .home-stage {
    overflow: hidden;
  }
  .home-pane[data-home-workspace] .home-board {
    flex: 1 1 auto;
    min-height: 0;
    padding-bottom: 0;
  }
  .home-pane[data-home-workspace] .scope-workspace {
    height: 100%;
    min-height: 0;
    overflow: hidden;
  }
  .home-pane[data-home-workspace] .today-center-hero {
    padding-right: 16px;
  }
  .home-pane[data-home-workspace] .scope-workspace-center-scroll-wrap {
    display: flex;
    flex-direction: column;
    min-height: 0;
    /* 显式落第 2 行：发现/公海/我的红人没有 header 元素时，自动排布会把
       dock 挤进中间的 1fr 行（0 高），提问框随 flex-end 溢出到流上方悬浮。 */
    grid-row: 2;
  }
  .home-pane[data-home-workspace] .scope-workspace-center-scroll-wrap > .scope-workspace-center-scroll {
    flex: 1 1 auto;
  }
  .home-pane[data-home-workspace] .scope-workspace-center-scroll {
    min-height: 0;
    padding: 4px 16px 16px 0;
    overflow-y: auto;
    overscroll-behavior: contain;
    scrollbar-gutter: stable;
  }
  .home-pane[data-home-workspace] .scope-workspace-center-scroll-content {
    min-height: 100%;
    overflow-anchor: none;
  }
  .home-pane[data-home-workspace] .scope-task-rail {
    height: auto;
    padding-bottom: 16px;
    overscroll-behavior: contain;
  }
}

@media (max-width: 1100px) {
  .home-quick-tasks {
    padding-bottom: 6px;
  }
}

/* Scope statistics live in the result rail; the center header owns only its title. */
.home-pane[data-home-workspace] .today-center-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-items: baseline;
  gap: var(--space-2) var(--space-3);
  padding-top: 4px;
  padding-bottom: 8px;
  padding-right: var(--space-4);
}
.home-pane[data-home-workspace] .scope-workspace-center-content {
  container: home-workspace-center / inline-size;
}
.home-pane[data-home-workspace] .today-center-hero h1 {
  margin: 0;
  overflow-wrap: break-word;
}

/* A shortcut changes context, not the composer geometry. Keep the interaction
   surface stable; real textarea content may still grow naturally. */
.home-pane.is-composer-focused .home-composer-dock .composer.composer--workspace {
  min-height: var(--composer-idle-min, 96px);
}

/* 提问框只占「一行输入 + 工具行」＝ 105px（产品要求 2026-09-22）：编辑器地板 22px，
   多行时由行内 height 撑开、盒子长到 --composer-max-height。 */
.home-pane.is-composer-dock .home-composer-dock .composer.composer--workspace {
  min-height: var(--composer-idle-min, 96px);
}
.home-pane.is-composer-dock .home-composer-dock .composer.composer--workspace textarea {
  min-height: 22px;
}

/* 五个模式入口与提问框共用底部 dock；中栏变窄时改列数，不挤压工作区列宽。 */

/* The Today center owns one width axis: hero, process stream, quick tasks and
   the composer box are sibling rows of the same content grid (auto / 1fr / auto).
   All four start at the grid's left edge and span it — the stage supplies the
   single page gutter, so the dock must never add a second one. The rail only
   resizes the grid's second column; it never touches any row individually. */
@media (min-width: 1101px) {
  .home-pane[data-home-workspace] .scope-workspace-center {
    display: block;
    min-width: 0;
    min-height: 0;
    padding: 0;
    overflow: hidden;
  }
  .home-pane[data-home-workspace] .scope-workspace-center-content {
    container: home-workspace-center / inline-size;
    display: grid;
    grid-template-rows: auto minmax(0, 1fr) auto;
    width: 100%;
    height: 100%;
    min-width: 0;
    min-height: 0;
    overflow: hidden;
  }
  .home-pane[data-home-workspace] .scope-workspace-center-content > .home-composer-dock {
    position: static;
    width: 100% !important;
    max-width: none !important;
    min-width: 0;
    margin: 0 !important;
    padding: 8px 16px 14px 0 !important;
    box-sizing: border-box;
    /* 显式落第 3 行（auto）：没有 header 的模式里也不许它掉进 1fr 行。 */
    grid-row: 3;
  }
  .home-pane[data-home-workspace] .scope-workspace-center-content > .home-composer-dock > .composer-dock,
  .home-pane[data-home-workspace] .scope-workspace-center-content > .home-composer-dock .composer.composer--workspace {
    width: 100% !important;
    max-width: none !important;
    min-width: 0;
    margin: 0 !important;
    box-sizing: border-box;
  }
}

/* Same axis invariant when the workspace stacks at or below 1100px: the rail follows the center but
   hero / quick tasks / composer still share one left edge; the stage gutter is
   the only inset, so the dock must not add a second one. */
@media (max-width: 1100px) {
  .home-pane[data-home-workspace] .scope-workspace-center-content > .home-composer-dock {
    padding-inline: 0;
  }
  .home-pane[data-home-workspace] .scope-workspace-center-content .home-quick-tasks {
    padding-left: 0;
  }
}

.nav-loading {
  width: 12px;
  height: 12px;
  margin-left: auto;
  border: 2px solid currentColor;
  border-right-color: transparent;
  border-radius: 50%;
  animation: nav-spin .7s linear infinite;
}
@keyframes nav-spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) {
  .nav-loading { animation: none; }
}

/* 加载态兜底：8 秒还没落地就换成可点的「刷新」（旧标签页 + 新构建时的恢复入口）。
   文本入口不占实底 CTA（docs/DESIGN.md §不变量 1）。 */
.nav-refresh,
.link-reload {
  margin-left: auto;
  padding: 0 6px;
  border: 1px solid var(--control-border);
  border-radius: var(--radius-control);
  background: transparent;
  color: var(--text-muted);
  font: inherit;
  font-size: var(--ds-font-tag);
  line-height: var(--lh-control-sm);
  cursor: pointer;
}
.nav-refresh:hover,
.link-reload:hover { color: var(--text); border-color: var(--control-border-hover); }
.nav-refresh:focus-visible,
.link-reload:focus-visible {
  outline: var(--focus-ring-width) solid var(--focus-ring);
  outline-offset: var(--focus-ring-offset);
}

.route-loading {
  padding: 24px;
}

/* 懒加载路由/CSS 拿不到时的恢复入口：有原因、有动作，不留白屏也不留无限转圈。 */
.route-error {
  max-width: var(--content-max);
  margin: var(--space-5) auto;
  padding: var(--space-5);
  border: 1px solid var(--border);
  border-radius: var(--radius-card);
  background: var(--bg-elevated);
}
.route-error h2 {
  margin: 0 0 var(--space-2);
  font-size: var(--ds-font-section);
  font-weight: 500;
}
.route-error p {
  margin: 0 0 var(--space-4);
  font-size: var(--ds-font-sm);
  line-height: var(--lh-control);
}
/* 公海线索挑选：密集工作台列表，保持公开字段边界与领取确认契约。 */
.pool-compact-pane {
  --pool-action: var(--accent-text);
  --pool-danger-bg: color-mix(in srgb, var(--danger) 9%, var(--bg));
  --pool-row-selected: color-mix(in srgb, var(--text) 4%, var(--bg));
  width: 100%;
  color: var(--text);
  font-size: var(--ds-font-sm);
  line-height: var(--ds-line-sm);
}
.pool-compact-header {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  margin: 0 0 var(--space-2);
}
.pool-compact-header h2 {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  margin: 0;
  font-size: var(--ds-font-section);
  line-height: var(--ds-line-section);
  font-weight: 600;
}
.pool-total {
  display: inline-flex;
  align-items: center;
  min-height: var(--badge-h);
  padding: 0 7px;
  border-radius: var(--radius-control);
  background: var(--ds-surface);
  color: var(--text-muted);
  font-size: var(--ds-font-helper);
  line-height: var(--ds-line-helper);
  font-weight: 500;
  font-variant-numeric: tabular-nums;
}
.pool-compact-header [data-pool-selected-count] {
  color: var(--text-muted);
  font-size: var(--ds-font-helper);
  line-height: var(--ds-line-helper);
}
.pool-compact-toolbar {
  display: grid;
  grid-template-columns: minmax(13rem, 1fr) auto auto auto auto;
  align-items: center;
  gap: var(--space-2);
  margin-bottom: var(--space-2);
  padding: var(--space-2) 0 var(--space-3);
  border-bottom: 1px solid var(--border);
}
.pool-search,
.pool-select-all {
  min-width: 0;
}
.pool-search {
  position: relative;
  display: block;
}
.pool-search .pool-inline-icon {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-muted);
  pointer-events: none;
}
.pool-compact-toolbar input[type="search"],
.pool-compact-toolbar select {
  height: var(--control-h-lg);
  min-height: var(--control-h-lg);
  border: 1px solid var(--control-border);
  border-radius: var(--radius-control);
  background: var(--bg);
  color: var(--text);
  font: inherit;
  font-size: var(--ds-font-body);
  line-height: var(--lh-control);
  padding: 0 10px;
  box-sizing: border-box;
}
.pool-search input {
  width: 100%;
  padding-left: 32px;
}
.pool-select-all {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: var(--control-h-lg);
  color: var(--text-muted);
  font-size: var(--ds-font-sm);
  line-height: var(--ds-line-sm);
  white-space: nowrap;
  cursor: pointer;
}
.pool-select-all:has(input:disabled) {
  cursor: default;
}
.pool-compact-pane input[type="checkbox"] {
  width: 16px;
  height: 16px;
  margin: 0;
  accent-color: var(--accent-text);
}
.pool-compact-list {
  display: block;
  width: 100%;
}
.pool-inline-icon {
  width: var(--icon-sm);
  height: var(--icon-sm);
  flex: none;
}
.pool-claim-confirm {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin-top: var(--space-1);
  padding: var(--space-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-card);
  background: var(--ds-surface);
  color: var(--text-muted);
  font-size: var(--ds-font-sm);
  line-height: var(--ds-line-sm);
}
.pool-claim-confirm [data-claim-object] {
  flex: 1 1 13rem;
}
.pool-claim-confirm button {
  height: var(--control-h);
  min-height: var(--control-h);
  padding: 0 9px;
  border: 1px solid var(--control-border);
  border-radius: var(--radius-control);
  background: var(--bg);
  color: var(--text);
  cursor: pointer;
  font: inherit;
  font-size: var(--ds-font-sm);
  line-height: var(--lh-control);
}
.pool-claim-confirm [data-claim-follow-yes] {
  border-color: var(--accent-text);
  color: var(--accent-text);
  font-weight: 600;
}
.pool-claim-confirm [data-claim-follow-error] {
  width: 100%;
  margin: 0;
  color: var(--danger);
}
.pool-claim-undo {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  min-height: 24px;
  margin: 0 0 var(--space-2);
  color: var(--text-muted);
  font-size: var(--ds-font-sm);
  line-height: var(--ds-line-sm);
}
.pool-claim-undo button {
  border: 0;
  padding: 0;
  background: transparent;
  color: var(--accent-text);
  font: inherit;
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 2px;
}
.pool-claim-undo-error {
  margin-left: var(--space-1);
  color: var(--danger);
}
.pool-sync-error {
  width: 100%;
  margin: var(--space-1) 0 0;
  color: var(--danger);
  font-size: var(--ds-font-sm);
  line-height: var(--ds-line-sm);
}
.pool-compact-pane :is(input, select, button, a):focus-visible {
  outline: var(--focus-ring-width) solid var(--focus-ring);
  outline-offset: var(--focus-ring-offset);
}
@media (max-width: 900px) {
  .pool-compact-toolbar {
    grid-template-columns: minmax(12rem, 1fr) auto auto;
  }
  .pool-select-all {
    justify-self: start;
  }
}
@media (max-width: 620px) {
  .pool-compact-toolbar {
    grid-template-columns: minmax(0, 1fr);
  }
  .pool-select-all {
    width: 100%;
  }
  .pool-select-all {
    justify-content: flex-start;
  }
}
@media (pointer: coarse) {
  .pool-compact-pane :is(button, a, input, select) {
    min-height: 44px;
  }
  .pool-select-all {
    min-height: 44px;
  }
}

/* 公海行紧凑改版（2026-10-07）：三行 64px 起，决策行优先；领取降为 L3 文字按钮。
   以 .pool-compact-pane 作用域覆盖，不动 .pool-kol-row 基线（DiscoveryRuntimeCandidate 共用）。 */
/* D2：行内重复出现（每行都有）的动作一律 L3（DESIGN.md §4.2，不变量 8）；
   R3 合规由行内确认（ClaimFollowConfirm）＋ 4s 撤销回执保证。 */
/* D5：领取确认条收紧为 helper 字号，确认 L2 / 取消 L3，减少行高跳动。 */
.pool-compact-pane .pool-claim-confirm {
  margin-top: var(--space-1);
  padding: var(--space-1) var(--space-2);
  font-size: var(--ds-font-helper);
  line-height: var(--ds-line-helper);
}
.pool-compact-pane .pool-claim-confirm button { height: 28px; min-height: 28px; font-size: var(--ds-font-helper); }
.pool-compact-pane .pool-claim-confirm [data-claim-follow-no] {
  border: 0;
  background: transparent;
  color: var(--text-muted);
}

/* Public-pool focus pass: the object list is the working surface, not a narrow result rail. */
.scope-workspace.is-result-focus .scope-workspace-center-scroll {
  padding: var(--ds-space-4) var(--ds-space-5) var(--ds-space-4) 0;
}
.scope-workspace.is-result-focus .home-composer-dock {
  padding-right: var(--ds-space-5) !important;
}
.scope-workspace.is-result-focus .pool-compact-pane {
  min-height: 100%;
  padding: var(--ds-space-5);
  border: 1px solid var(--ds-border);
  border-radius: var(--ds-radius-section);
  background: var(--bg);
  box-sizing: border-box;
}
.pool-compact-header {
  align-items: end;
  justify-content: space-between;
  gap: var(--space-3);
  margin-bottom: var(--space-3);
}
.pool-eyebrow {
  margin: 0 0 2px;
  color: var(--text-muted);
  font-size: var(--ds-font-helper);
  font-weight: 600;
  letter-spacing: .08em;
  line-height: var(--ds-line-helper);
  text-transform: uppercase;
}
.pool-summary {
  max-width: 28rem;
  margin: 0;
  color: var(--text-muted);
  font-size: var(--ds-font-sm);
  line-height: var(--ds-line-sm);
  text-align: right;
  text-wrap: pretty;
}
.pool-compact-toolbar {
  grid-template-columns: minmax(16rem, 1fr) auto auto auto auto;
  margin-bottom: var(--space-3);
  padding: var(--space-2);
  border: 1px solid var(--ds-border);
  border-radius: var(--ds-radius-section);
  background: var(--ds-surface);
}
.pool-compact-list {
  border-top: 1px solid var(--ds-border);
}
@media (max-width: 900px) {
  .pool-summary { display: none; }
}
@media (max-width: 620px) {
  .scope-workspace.is-result-focus .scope-workspace-center-scroll { padding-right: 0; }
  .scope-workspace.is-result-focus .pool-compact-pane {
    padding: var(--ds-space-3);
    border-right: 0;
    border-left: 0;
    border-radius: 0;
  }
  .pool-compact-header { align-items: start; }
}

/* Reference-driven public-pool density pass: a scan-first lead queue, not a set of profile cards. */
.pool-compact-pane {
  --pool-status-new-bg: #f3f4f6;
  --pool-status-new-text: #666;
  --pool-status-overdue-bg: #fff1f1;
  --pool-status-overdue-text: #d74646;
}
.scope-workspace.is-result-focus .pool-compact-pane {
  padding: var(--ds-space-4) var(--ds-space-5);
}
.pool-compact-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  margin-bottom: var(--space-3);
}
.pool-header-title {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  min-width: max-content;
}
.pool-compact-header h2 {
  font-size: 18px;
  line-height: 24px;
}
.pool-selected-summary {
  color: var(--text-muted);
  font-size: var(--ds-font-helper);
  line-height: var(--ds-line-helper);
  font-variant-numeric: tabular-nums;
}
.pool-compact-toolbar {
  display: flex;
  flex: 0 1 auto;
  align-items: center;
  justify-content: flex-end;
  gap: var(--space-2);
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
}
.pool-search {
  width: clamp(176px, 20vw, 224px);
}
.pool-compact-toolbar input[type="search"],
.pool-compact-toolbar select {
  height: 32px;
  min-height: 32px;
  font-size: var(--ds-font-sm);
}
.pool-select-all {
  min-height: 32px;
  font-size: var(--ds-font-helper);
}
.pool-compact-list {
  border-top: 1px solid var(--border-subtle, var(--ds-border));
}
@media (max-width: 1100px) {
  .pool-compact-header {
    align-items: flex-start;
    flex-direction: column;
  }
  .pool-compact-toolbar {
    width: 100%;
    justify-content: flex-start;
  }
  .pool-search {
    flex: 1 1 180px;
    width: auto;
  }
}
@media (max-width: 720px) {
  .pool-compact-toolbar {
    flex-wrap: wrap;
  }
  .pool-search {
    flex-basis: 100%;
  }
}
@media (max-width: 420px) {
  .scope-workspace.is-result-focus .pool-compact-pane {
    padding: var(--ds-space-3);
  }
  .pool-header-title {
    min-width: 0;
  }
  .pool-compact-toolbar > :not(.pool-search) {
    flex: 1 1 auto;
  }
}

/* The status is the single public-sea reason, so it must scan with—not away from—the identity. */

/* 公海恢复为对象工作台右栏：中栏永远留给人机协作与提问框。 */
.scope-task-rail [data-result-rail="pool"] {
  height: 100%;
}
.scope-task-rail .pool-compact-pane {
  min-width: 0;
  padding: 0 0 var(--ds-space-4);
}
.scope-task-rail .pool-compact-header {
  align-items: flex-start;
  flex-direction: column;
  gap: var(--ds-space-2);
  margin-bottom: var(--ds-space-3);
  padding-right: calc(var(--icon-btn) + var(--ds-space-2));
}
.scope-task-rail .pool-header-title {
  width: 100%;
  min-width: 0;
  justify-content: space-between;
}
.scope-task-rail .pool-compact-header h2 {
  font-size: var(--ds-font-section);
  line-height: var(--ds-line-section);
}
.scope-task-rail .pool-compact-toolbar {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  width: 100%;
  gap: var(--ds-space-2);
}
.scope-task-rail .pool-search {
  grid-column: 1 / -1;
  width: 100%;
}
.scope-task-rail .pool-select-all {
  grid-column: 1 / 2;
  justify-self: start;
}
.scope-task-rail .pool-compact-list {
  border-top-color: var(--ds-border);
}
@media (max-width: 1100px) {
.scope-task-rail .pool-compact-header {
  padding-right: calc(var(--icon-btn) + var(--ds-space-2));
}
}

/* 公海右栏是高密度线索表。状态标签已完整表达入海状态，不重复再写「公海原因」。
   L3 保留确认语义，但视觉尺寸回到工作台的 24 / 28px 控件阶梯。 */
.scope-task-rail .pool-claim-confirm {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: var(--ds-space-1);
  margin-top: var(--ds-space-1);
  padding: var(--ds-space-1) var(--ds-space-2);
  font-size: var(--ds-font-helper);
  line-height: var(--ds-line-helper);
}
.scope-task-rail .pool-claim-confirm [data-claim-object] {
  grid-column: 1 / -1;
}
.scope-task-rail .pool-claim-confirm button {
  min-height: var(--control-h-sm);
  height: var(--control-h-sm);
  padding-inline: var(--ds-space-2);
  font-size: var(--ds-font-sm);
  line-height: var(--lh-control-sm);
}
.scope-task-rail .pool-claim-confirm [data-claim-follow-yes] {
  grid-column: 2;
}
.scope-task-rail .pool-claim-confirm [data-claim-follow-no] {
  grid-column: 3;
}

/* 公海桌面行保持原有动作与头像尺度；资料维护另占一行，避免挤压领取动作。 */
.scope-task-rail .pool-claim-confirm button {
  min-height: var(--control-h);
  height: var(--control-h);
  padding-inline: var(--ds-space-2);
  font-size: var(--ds-font-sm);
  line-height: var(--lh-control);
}
.pool-jev-badge {
  display: inline-flex;
  align-items: center;
  min-height: var(--badge-h);
  padding-inline: 6px;
  border: 1px solid var(--control-border);
  border-radius: var(--radius-control);
  font-size: var(--ds-font-helper);
  font-weight: 500;
  line-height: var(--ds-line-helper);
  white-space: nowrap;
}
.pool-jev-badge.is-potential {
  color: var(--success);
}
.pool-jev-badge.is-risk {
  color: var(--danger);
}
.pool-maintenance {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--ds-space-1) var(--ds-space-2);
  margin: 0 0 var(--ds-space-2);
  color: var(--text-muted);
  font-size: var(--ds-font-helper);
  line-height: var(--ds-line-helper);
}
.pool-maintenance > button,
.pool-cleanup-confirm button {
  min-height: var(--control-h-sm);
  height: var(--control-h-sm);
  padding: 0 var(--ds-space-2);
  border: 1px solid var(--control-border);
  border-radius: var(--radius-control);
  background: var(--bg);
  color: var(--text);
  font: inherit;
  font-size: var(--ds-font-sm);
  line-height: var(--lh-control-sm);
  cursor: pointer;
}
.pool-maintenance > button:hover:not(:disabled),
.pool-cleanup-confirm button:hover:not(:disabled) {
  border-color: var(--control-border-hover);
  background: var(--ds-surface);
}
.pool-maintenance > button:disabled,
