/* Configurable connector runtime extension: mirrors the existing admin density and tokens. */
.runtime-settings { display: grid; gap: var(--space-4); min-width: 0; }
.runtime-settings-panel { max-width: 1040px; }
.runtime-section-heading { display: flex; gap: var(--space-3); justify-content: space-between; align-items: flex-start; }
.runtime-section-heading h2, .runtime-section-heading h3 { margin: 0; font-size: var(--font-section); }
.runtime-section-heading p { margin: var(--space-1) 0 0; }
.runtime-config-form, .runtime-import-block, .runtime-tool-governance, .runtime-activity { border-top: 1px solid var(--line); padding-top: var(--space-4); }
.runtime-config-form fieldset { min-width: 0; border: 0; margin: 0; padding: 0; display: grid; gap: var(--space-3); }
.runtime-config-form legend { color: var(--text); font-weight: 600; padding: 0; }
