.runtime-form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-3); }
.runtime-radio-row, .runtime-save-row, .admin-actions { display: flex; align-items: center; flex-wrap: wrap; gap: var(--space-2); }
.runtime-check-field { align-self: end; min-height: 40px; color: var(--text); }
.runtime-editor-field textarea, .runtime-config-form textarea { min-height: 84px; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: var(--font-sm); line-height: 1.45; resize: vertical; }
.runtime-form-hint, .runtime-l3-notice, .runtime-discovery-note { margin: 0; font-size: var(--font-sm); line-height: var(--leading-body); }
.runtime-l3-notice { color: var(--danger); }
.runtime-notice { margin: 0; padding: var(--space-2) var(--space-3); border: 1px solid color-mix(in srgb, var(--success) 32%, var(--line)); border-radius: var(--radius-sm); background: var(--bg-elevated); color: var(--text); }
.runtime-state { display: flex; flex-wrap: wrap; gap: var(--space-2); align-items: center; padding: var(--space-3); border: 1px solid var(--line); border-radius: var(--radius-sm); background: var(--bg-elevated); }
.runtime-state strong { color: var(--text); }
.runtime-state span { color: var(--text-muted); font-size: var(--font-sm); }
.runtime-state-error { border-color: color-mix(in srgb, var(--danger) 45%, var(--line)); }
.runtime-tools-list, .skill-binding-list { display: grid; gap: var(--space-2); }
.runtime-tool-row, .skill-binding-connector { border: 1px solid var(--line); border-radius: var(--radius-sm); padding: var(--space-3); display: grid; gap: var(--space-3); background: var(--bg); }
.runtime-tool-row { grid-template-columns: minmax(0, 1fr) minmax(180px, 250px); }
.runtime-tool-main { min-width: 0; }
.runtime-tool-main p { margin: var(--space-1) 0 0; font-size: var(--font-sm); overflow-wrap: anywhere; }
.runtime-tool-name { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; }
.runtime-risk { font-size: var(--font-xs); }
.runtime-tool-controls { display: grid; align-content: start; gap: var(--space-2); }
.runtime-compact-field { font-size: var(--font-xs); }
.runtime-compact-field select { min-height: 34px; }
.runtime-schema { margin-top: var(--space-2); }
.runtime-schema summary { cursor: pointer; color: var(--text-muted); font-size: var(--font-sm); }
.runtime-schema pre { max-height: 220px; overflow: auto; margin: var(--space-2) 0 0; padding: var(--space-2); border: 1px solid var(--line); border-radius: var(--radius-sm); background: var(--bg-elevated); font-size: var(--font-xs); white-space: pre-wrap; overflow-wrap: anywhere; }
.runtime-hash { display: block; margin-top: var(--space-2); color: var(--text-muted); font-size: var(--font-xs); overflow-wrap: anywhere; }
.runtime-preview, .runtime-probe-result { display: grid; gap: var(--space-2); margin-top: var(--space-3); padding: var(--space-3); border: 1px solid var(--line); border-radius: var(--radius-sm); background: var(--bg-elevated); }
.runtime-preview ul, .runtime-warning-list ul { margin: 0; padding-left: 1.25rem; display: grid; gap: var(--space-1); }
.runtime-warning-list { color: var(--text-muted); font-size: var(--font-sm); }
.runtime-history-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-3); margin-top: var(--space-3); }
.runtime-history-list { list-style: none; margin: var(--space-2) 0 0; padding: 0; display: grid; gap: 1px; background: var(--line); border: 1px solid var(--line); }
