.skill-tool-choice-copy { display: grid; gap: 2px; min-width: 0; }
.skill-tool-choice-copy small { color: var(--text-muted); font-size: var(--font-xs); overflow-wrap: anywhere; }
.runtime-inline-error { margin: 0; }
.runtime-tool-scope { grid-column: 1 / -1; min-width: 0; padding-top: var(--space-2); border-top: 1px solid var(--line); }
