  padding: 0;
  flex-direction: column;
  gap: 8px;
}
.scope-task-rail.is-collapsed .scope-task-rail-toggle-icon {
  flex: 0 0 auto;
}

/* 跟进名单工具区：找谁与排序在第一行，全选和批量动作固定在第二行左侧。 */
