  .ticket-binding-action { justify-content: stretch; }
  .ticket-binding-action .btn { width: 100%; }
}

.task-work-order-create {
  display: grid;
  grid-template-columns: minmax(14rem, 1.2fr) minmax(18rem, 2fr) minmax(9rem, .7fr) minmax(10rem, .8fr) auto;
  gap: .75rem;
