.task-work-order-task-list,
.task-center-system-section { margin-bottom: var(--space-4, 16px); }
.task-work-order-kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--space-3, 12px); margin: var(--space-4, 16px) 0; }
