.task-work-order-kpis span, .task-work-order-kpis small, .task-work-order-template-table small, .task-work-order-task-table small, .task-work-order-child-table small { display: block; color: var(--text-muted); font-size: var(--ds-font-helper, 12px); line-height: var(--ds-line-helper, 16px); }
.task-work-order-kpis strong { display: block; margin: 3px 0; color: var(--text); font-size: 1.45rem; line-height: 1.2; }
.task-work-order-template-wrap { overflow-x: auto; border-top: 1px solid var(--ds-border, var(--border)); padding-top: var(--space-3, 12px); }
.task-work-order-template-wrap h3, .task-work-order-detail-panel h3 { margin: 0 0 var(--space-2, 8px); font-size: var(--ds-font-body, 14px); }
.task-work-order-template-table, .task-work-order-task-table, .task-work-order-child-table { width: 100%; border-collapse: collapse; font-size: var(--ds-font-sm, 13px); line-height: var(--ds-line-body, 20px); }
.task-work-order-template-table th, .task-work-order-template-table td, .task-work-order-task-table th, .task-work-order-task-table td, .task-work-order-child-table th, .task-work-order-child-table td { padding: 9px 8px; border-bottom: 1px solid var(--ds-border, var(--border)); text-align: left; vertical-align: top; }
.task-work-order-template-table th, .task-work-order-task-table th, .task-work-order-child-table th { color: var(--text-muted); font-size: var(--ds-font-helper, 12px); font-weight: 500; }
.task-work-order-template-table strong, .task-work-order-task-table strong, .task-work-order-child-table strong { display: block; color: var(--text); font-weight: 600; }
