.task-work-order-task-table > tbody > tr:first-child > td { border-top: 1px solid var(--ds-border, var(--border)); }
.task-work-order-task-table .is-expanded > td { background: color-mix(in srgb, var(--accent) 5%, var(--bg)); }
.task-work-order-row-actions { display: flex; gap: 6px; align-items: center; white-space: nowrap; }
