.status-alert { color: var(--danger, #c2410c) !important; }
.task-center-system-toggle { display: flex; width: 100%; align-items: center; justify-content: space-between; gap: var(--space-3, 12px); border: 0; background: transparent; color: var(--text); padding: 0; text-align: left; cursor: pointer; font: inherit; }
.task-center-system-toggle strong, .task-center-system-toggle small { display: block; }
.task-center-system-toggle small { margin-top: 2px; color: var(--text-muted); font-size: var(--ds-font-helper, 12px); }
