/* User-directed compact typography outside shared KOL cards.
   DESIGN §24.6 cards own their approved text/helper/icon token tiers; do not
   flatten their 12px helper text or 14px icons back to the shell's 13px reset.
   Other workbench surfaces and the documented mono face are unchanged. */
#root .workbench:not(.ontology-shell), #root .workbench:not(.ontology-shell) :where(:not(svg):not(svg *):not(.kol-card-row):not(.kol-card-row *)) {
  font-size: var(--ds-font-sm) !important;
  font-family: var(--sans) !important;
}
#root .workbench :is(pre, code, .mono) {
  font-family: var(--mono) !important;
}
/* DESIGN §9.2／§5：数据面的统计数值是全站唯一允许的字号例外（--stat-value-font 20px）。
   上面那条通配覆盖带 !important，页面在不反打的情况下表达不出这一档；
   因此在 shell 层开出例外，由数值元素自己声明语义钩子——字号数值仍只有 styles.css 一处来源。 */
#root .workbench :where([data-ds-stat-value]) { font-size: var(--stat-value-font) !important; }
#root .workbench :where([data-ds-stat-label]) { font-size: var(--stat-label-font) !important; }
#root .workbench :where([data-ds-stat-delta]) { font-size: var(--stat-delta-font) !important; }
.workbench :is(h1, h2, h3, h4, h5, h6) {
  line-height: var(--ds-line-body);
  font-weight: 600;
}
.session-center { position: relative; }
/* header 与 composer 固定在滚动区之外；矮视口下标题区先让位，既不压没 feed，也不会把输入框顶出视口（§10.1/§10.6）。 */
.session-center > .task-detail-header {
  max-height: 42vh;
  overflow-y: auto;
  overflow-x: clip;
  scrollbar-width: thin;
}
.session-stream.conversation {
  flex: 1 1 0;
  overflow-anchor: auto;
  padding-bottom: calc(var(--workspace-arrow-button-size) + var(--space-4));
}
/* A flex feed must not shrink its messages into its viewport: that truncates
   scroll geometry and can make the final action unreachable. */
.session-stream.conversation > * { flex-shrink: 0; }
.session-composer { flex-shrink: 0; }
.session-scroll-control {
  position: relative;
  height: 0;
  flex-shrink: 0;
  z-index: 2;
}
/* 时间流里的卡片：智能体产出的结果、草稿、阶段确认与业务动作按时间排在中栏。 */
.stream-artifact { min-width: 0; scroll-margin-block: var(--space-3); }
.stream-artifact > .artifact { margin: 0; }
[data-stream-entry].is-located { outline: 2px solid var(--accent); outline-offset: var(--space-1); border-radius: var(--radius-md); }
.stream-superseded { padding: var(--space-2) var(--space-3); }
.stream-superseded > summary { cursor: pointer; color: var(--text-muted); font-size: var(--ds-font-sm); line-height: var(--ds-line-sm); }
