/* 右栏结果目录：标题 + 时间，点击定位到中栏时间流里的卡片。 */
.result-index ol { list-style: none; margin: var(--space-2) 0 0; padding: 0; display: grid; gap: var(--space-1); }
.result-index-item { display: grid; grid-template-columns: minmax(0, 1fr) auto; column-gap: var(--space-2); width: 100%; padding: var(--space-2); border: 1px solid transparent; border-radius: var(--radius-md); background: none; text-align: left; color: var(--text); cursor: pointer; }
.result-index-item:hover { border-color: var(--border); }
.result-index-item:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.result-index-title { font-size: var(--ds-font-sm); line-height: var(--ds-line-sm); font-weight: 600; }
.result-index-detail { grid-column: 1; font-size: var(--ds-font-sm); line-height: var(--ds-line-sm); color: var(--text-muted); overflow-wrap: anywhere; }
.result-index-time { grid-column: 2; grid-row: 1; font-size: var(--ds-font-sm); color: var(--text-muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
.runtime-action-card { padding: var(--space-3); margin-block: var(--space-2); }
.runtime-action-summary { display: grid; gap: var(--space-2); margin-block: var(--space-3); }
.runtime-action-summary > div { display: grid; gap: var(--space-1); }
.runtime-action-summary dt { color: var(--text-muted); }
.runtime-action-summary dd { margin: 0; overflow-wrap: anywhere; }
.runtime-action-card pre { white-space: pre-wrap; overflow-wrap: anywhere; }
.agent-internal-review { color: var(--text-muted); margin-block: var(--space-2); }
.agent-internal-review summary { cursor: pointer; }
.home-pane[data-home-workspace] .scope-workspace-center-scroll {
  padding-bottom: calc(var(--workspace-arrow-button-size) + var(--space-4));
}
.home-pane[data-home-workspace] .scope-workspace-center-scroll-content { overflow-anchor: auto; }
.scope-scroll-jump { border-radius: 999px; font-size: var(--ds-font-sm); }
@media (pointer: coarse) {
  .session-stream.conversation { padding-bottom: calc(var(--touch-hit-min) + var(--space-4)); }
}
.task-center-system-body { margin-top: var(--space-2); }
/* DESIGN §4/11: enlarge touch hit areas independently from visual controls.
   Reserve space between chips so the transparent targets cannot overlap. */
:root { --touch-hit-min: 44px; }
@media (pointer: coarse) {
  [data-discovery-search-card] button[data-discovery-chip],
  [data-ai-prompt-submit],
  [data-session-back-link],
  [data-runtime-actions] button,
  [data-discovery-results] button {
    position: relative;
  }
  [data-discovery-search-card] button[data-discovery-chip] {
    margin-block: var(--space-2);
  }
  :is([data-discovery-search-card] button[data-discovery-chip], [data-ai-prompt-submit],
    [data-session-back-link], [data-runtime-actions] button, [data-discovery-results] button)::after {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    width: max(100%, var(--touch-hit-min));
    height: max(100%, var(--touch-hit-min));
    transform: translate(-50%, -50%);
  }
}
@media (max-width: 980px) { .task-work-order-kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 560px) { .task-work-order-kpis { grid-template-columns: 1fr; } .task-work-order-kpis article { padding: 10px; } }

