  padding: var(--space-4);
  font-size: var(--ds-font-sm);
  line-height: var(--ds-line-sm);
}
.review-author-page.is-editing { display: flex; flex-direction: column; overflow: hidden; }
.review-author-page h1, .review-author-page h2, .review-author-page h3, .review-author-page small {
  font-size: var(--ds-font-sm); line-height: var(--ds-line-sm);
}
.review-author-page button, .review-author-page input, .review-author-page select {
  min-height: var(--control-h-form); padding: var(--space-1) var(--space-2); border-radius: var(--radius-control);
}
