.review-author-page.review-page button { min-height: var(--control-h-form); line-height: var(--ds-line-sm); padding: var(--space-1) var(--space-2); }
.review-author-page .review-quiet { background: transparent; border-color: transparent; }
.review-author-page .review-toolbar { gap: var(--space-2); margin-block: var(--space-2); flex-shrink: 0; }
.review-author-org { display: grid; grid-template-columns: repeat(4,minmax(0,1fr)) var(--control-h-form); gap: var(--space-2); align-items: end; padding-bottom: var(--space-3); border-bottom: 1px solid var(--border); flex-shrink: 0; }
