/* ── 沉浸式通讯（/mail 全屏覆盖工作台 · feat/mail-immersive）─────────────────
   布局：顶栏（返回/标题/搜索/AI问/同步/写信）+ 三栏（左导航 / 会话列表 / 阅读）。
   复用 token：--ds-* / --space-* / --accent；分栏延续 1px 发丝线、gap 0 基线。 */
.list-page.mail-immersive {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  flex-direction: column;
  gap: 0;
  width: 100%;
  max-width: none;
  background: var(--canvas);
  color: var(--text);
}
/* 顶栏 */
.mi-topbar {
  flex: none;
  height: 52px;
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: 0 var(--space-4);
  background: var(--bg);
  border-bottom: 1px solid var(--ds-border);
  overflow-x: auto;
  scrollbar-width: none;
}
.mi-back {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex: none;
  height: 32px;
  padding: 0 12px 0 8px;
  border: 1px solid var(--ds-border);
  border-radius: var(--radius-control);
  background: var(--ds-surface);
  color: var(--text);
  font-size: var(--ds-font-sm);
  cursor: pointer;
  white-space: nowrap;
}
.mi-back:hover { border-color: var(--accent); color: var(--accent-text); }
.mi-back > span[aria-hidden="true"] { font-size: 16px; line-height: 1; }
.mi-title { margin: 0; font-size: 15px; font-weight: 600; flex: none; }
.mi-searchwrap {
  flex: 1 1 auto;
  max-width: 560px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  gap: 8px;
  height: 34px;
  padding: 0 12px;
  border: 1px solid var(--ds-border);
  border-radius: 17px;
  background: var(--ds-surface);
  color: var(--ds-text-dim);
  min-width: 180px;
}
.mi-searchwrap .mail-ico { width: 14px; height: 14px; flex: none; }
.mi-search {
  flex: 1;
  min-width: 0;
  border: 0;
  background: none;
  outline: none;
  color: var(--text);
  font-size: var(--ds-font-sm);
  height: 100%;
}
.mi-sync {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex: none;
  font-size: var(--ds-font-helper);
  color: var(--ds-text-dim);
  white-space: nowrap;
}
.mi-syncdot { width: 8px; height: 8px; border-radius: 50%; background: #1a9e54; flex: none; }
.mi-syncdot.is-syncing { background: var(--accent); animation: mi-pulse 1.2s ease-in-out infinite; }
@keyframes mi-pulse { 50% { opacity: 0.35; } }
.mi-topbar .btn { flex: none; }
/* 三栏 */
.mail-immersive .mi-grid {
  display: grid;
  grid-template-columns: 232px 400px minmax(0, 1fr);
  gap: 0;
  flex: 1 1 auto;
  min-height: 0;
  align-items: stretch;
  overflow: hidden;
}
/* 左导航 */
.mi-rail {
  border-right: 1px solid var(--ds-border);
  background: var(--bg);
  padding: var(--space-3) var(--space-2);
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  overflow-y: auto;
  min-height: 0;
  min-width: 0;
}
.mi-folders { display: grid; gap: 2px; }
.mi-folder {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 34px;
  padding: 0 10px;
  border: 0;
  border-radius: var(--ds-radius-sm);
  background: none;
  color: var(--text);
  font-size: var(--ds-font-sm);
  cursor: pointer;
  text-align: left;
}
.mi-folder:hover { background: color-mix(in srgb, var(--text) 5%, transparent); }
.mi-folder.is-on {
  background: color-mix(in srgb, var(--accent) 10%, transparent);
  color: var(--accent-text);
  font-weight: 600;
}
.mi-folder .mail-ico { width: 16px; height: 16px; flex: none; color: var(--ds-text-dim); }
.mi-folder.is-on .mail-ico { color: var(--accent-text); }
.mi-count {
  margin-left: auto;
  font-size: var(--font-tag);
  color: var(--ds-text-dim);
  background: color-mix(in srgb, var(--text) 7%, transparent);
  border-radius: 9px;
  padding: 1px 7px;
  white-space: nowrap;
}
.mi-folder.is-on .mi-count,
