  color: var(--accent-text);
  background: color-mix(in srgb, var(--accent) 16%, transparent);
}
.mi-stages .mail-pane-label { margin: 0 0 6px 10px; }
.mi-stagechips { display: flex; flex-wrap: wrap; gap: 6px; padding: 0 4px; }
.mi-stagechip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 24px;
  padding: 0 10px;
  border: 1px solid var(--ds-border);
  border-radius: 12px;
  background: var(--ds-surface);
  color: var(--ds-text-dim);
  font-size: var(--ds-font-helper);
  cursor: pointer;
  white-space: nowrap;
}
.mi-stagechip:hover { border-color: var(--accent); color: var(--accent-text); }
.mi-stagechip.is-on {
  border-color: var(--accent);
  color: var(--accent-text);
  background: color-mix(in srgb, var(--accent) 10%, transparent);
  font-weight: 600;
}
.mi-stagechip .mi-count { margin-left: 0; }
.mi-unboundonly {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 32px;
  padding: 0 10px;
  border: 0;
  border-radius: var(--ds-radius-sm);
