  cursor: pointer;
  text-align: left;
}
.mi-unboundonly .mail-ico { width: 15px; height: 15px; }
.mi-unboundonly.is-on { color: var(--accent-text); font-weight: 600; }
.mi-letters { border-top: 1px solid var(--ds-border); padding-top: var(--space-2); }
.mi-letters .mail-pane-label { margin: 0 0 6px 10px; }
.mi-railfoot {
  margin-top: auto;
  border-top: 1px solid var(--ds-border);
  padding-top: var(--space-2);
  display: grid;
  gap: 6px;
}
.mi-railfoot .muted { font-size: var(--ds-font-helper); }
.mi-keys { margin: 0; font-size: var(--ds-font-helper); color: var(--ds-text-dim); }
/* 会话列表 */
.mi-listhead {
  display: flex;
  align-items: baseline;
  gap: 8px;
  flex: none;
  padding: var(--space-3) var(--space-3) var(--space-2);
  border-bottom: 1px solid var(--ds-border);
}
.mi-listhead strong { font-size: var(--ds-font-sm); }
.mi-listhead .muted { font-size: var(--ds-font-helper); }
.mail-immersive .mail-list {
  border-right: 1px solid var(--ds-border);
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
}
.mail-immersive .mail-list-scroll { flex: 1 1 auto; }
.mail-tree-conversation { position: relative; }
.mi-hoverbar {
  position: absolute;
  right: 8px;
  top: 6px;
  z-index: 3;
  display: none;
  gap: 2px;
  padding: 2px;
  border: 1px solid var(--ds-border);
  border-radius: var(--ds-radius-sm);
  background: var(--ds-surface);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
}
.mail-tree-conversation:hover .mi-hoverbar { display: flex; }
.mi-hoverbar button {
  width: 26px;
  height: 24px;
  border: 0;
  border-radius: 4px;
  background: none;
  color: var(--ds-text-dim);
  font-size: 13px;
  cursor: pointer;
}
.mi-hoverbar button:hover {
  background: color-mix(in srgb, var(--text) 7%, transparent);
  color: var(--text);
}
/* 阅读区 */
.mi-threadbar {
  position: sticky;
  top: 0;
  z-index: 5;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 0;
  background: var(--canvas);
  border-bottom: 1px solid var(--ds-border);
}
.mi-tsubject {
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 42%;
  flex: none;
}
.mi-kolchip {
  flex: none;
  height: 20px;
  padding: 0 8px;
  border-radius: 10px;
  font-size: var(--font-tag);
  display: inline-flex;
  align-items: center;
  color: var(--accent-text);
  background: color-mix(in srgb, var(--accent) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--accent) 30%, transparent);
  white-space: nowrap;
}
.mi-tspacer { flex: 1; }
.mi-stagewrap {
  border: 1px solid var(--ds-border);
  border-radius: var(--ds-radius-sm);
  background: var(--bg);
  padding: var(--space-2) var(--space-3);
  margin: var(--space-3) 0;
}
