.mi-aibar .muted { margin: 0; font-size: var(--ds-font-helper); }
.mi-airow {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 38px;
  padding: 0 14px;
  border: 1px solid color-mix(in srgb, var(--accent) 45%, var(--ds-border));
  border-radius: 19px;
  background: var(--ds-surface);
}
.mi-spark { color: var(--accent-text); flex: none; }
.mi-aiinput {
  flex: 1;
  min-width: 0;
  border: 0;
  background: none;
  outline: none;
  font-size: var(--ds-font-sm);
  color: var(--text);
  height: 100%;
}
.mi-ctx {
  flex: none;
  font-size: var(--ds-font-helper);
  color: var(--accent-text);
  background: color-mix(in srgb, var(--accent) 10%, transparent);
  border-radius: 9px;
  padding: 2px 8px;
  white-space: nowrap;
  max-width: 42%;
  overflow: hidden;
  text-overflow: ellipsis;
}
.mi-aichips { display: flex; gap: 6px; flex-wrap: wrap; }
.mi-aichip {
  height: 26px;
  padding: 0 12px;
  border: 1px solid var(--ds-border);
  border-radius: 13px;
  background: var(--ds-surface);
